import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`ACP-Laufzeitsteuerung zum Aktivieren der Weiterleitung, Auswählen von Backends, Einschränken zulässiger Zielagenten und Festlegen des Projektionsverhaltens für gestreamte Dialogschritte.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Zulässige ACP-Agenten`},help:{"v1-f2mw0d-3a":`Zulassungsliste der IDs von ACP-Zielagenten, die für ACP-Laufzeitsitzungen erlaubt sind. Eine leere Liste bedeutet keine zusätzliche Einschränkung durch die Zulassungsliste.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`ACP-Backend`},help:{"v1-1s1l6bz-2v":`ID des standardmäßigen ACP-Laufzeit-Backends (zum Beispiel: acpx). Muss mit einem registrierten Backend eines ACP-Laufzeit-Plugins übereinstimmen.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`ACP-Standardagent`},help:{"v1-7donnu-2c":`ID des ACP-Zielagenten, der ersatzweise verwendet wird, wenn beim Starten von ACP-Instanzen kein explizites Ziel angegeben wird.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`ACP-Weiterleitung aktiviert`},help:{"v1-1ug9t9m-3w":`Unabhängiger Schalter für die Weiterleitung von Dialogschritten in ACP-Sitzungen (Standard: true). Auf false setzen, um ACP-Befehle verfügbar zu halten und gleichzeitig die Ausführung von ACP-Dialogschritten zu blockieren.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP aktiviert`},help:{"v1-1uonl1v-2a":`Globaler Schalter für die ACP-Funktion. Deaktiviert lassen, solange ACP-Laufzeit und Richtlinie nicht konfiguriert sind.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`ACP-Fallback-Backends`},help:{"v1-1wvdifq-5m":`Geordnete Liste von ACP-Fallback-Backend-IDs, die ausprobiert werden, wenn das primäre Backend mit UNAVAILABLE fehlschlägt (zum Beispiel: Anfragelimit erreicht / Kontingent ausgeschöpft). Jeder Eintrag muss einem registrierten Backend eines ACP-Laufzeit-Plugins entsprechen.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Installationsbefehl für die ACP-Laufzeit`},help:{"v1-1jjuv9m-39":"Optionaler Installations-/Einrichtungsbefehl für Betreiber, der von `/acp install` und `/acp doctor` angezeigt wird, wenn die ACP-Backend-Anbindung fehlt."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`ACP-Stream`},help:{"v1-1bka5p-2v":`Steuerung der ACP-Streaming-Projektion für Blockgröße, Metadatensichtbarkeit und Zustellungsverhalten ohne Duplikate.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Zustellungsmodus des ACP-Streams`},help:{"v1-19gdmx1-3s":`ACP-Zustellungsart: live streamt die projizierte Ausgabe schrittweise, final_only puffert die gesamte projizierte ACP-Ausgabe bis zu den Abschlussereignissen des Durchlaufs.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Wiederholungsunterdrückung im ACP-Stream`},help:{"v1-manh32-3d":`Bei true (Standard) werden wiederholte Zeilen der ACP-Status-/Tool-Projektion innerhalb eines Durchlaufs unterdrückt, während die ACP-Rohereignisse unverändert bleiben.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Tag-Sichtbarkeit im ACP-Stream`},help:{"v1-1ybhx22-34":`Sichtbarkeitsüberschreibungen pro sessionUpdate für die ACP-Projektion (zum Beispiel usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Agenten`},help:{"v1-2rc4v8-55":`Wurzel der Agenten-Laufzeitkonfiguration. Gleichrangige Einträge auf der Wurzelebene verwalten Infrastruktur und agentenübergreifende Standardwerte; agents.defaults verwaltet das Verhalten der Agentenschleife; Agenteneinträge können beide Bereiche überschreiben, sofern dies unterstützt wird.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Agenten-Standardeinstellungen`},help:{"v1-1af7k5b-5a":`Gemeinsame Standardeinstellungen, die von Agenten übernommen werden, sofern sie nicht pro Eintrag in agents.entries überschrieben werden. Verwenden Sie Standardeinstellungen, um ein einheitliches Basisverhalten sicherzustellen und doppelte Konfigurationen pro Agent zu reduzieren.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Ziel der Authentifizierungsvererbung`},help:{"v1-2d16wl-2x":`Aus Kompatibilitätsgründen beim Upgrade festgelegter Eigentümer des geerbten Anmeldedatenspeichers, bis die Anmeldedaten pro Agent verlagert werden.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Eigentümer der Authentifizierungsvererbung`},help:{"v1-1a1s7nm-4s":`Agent, dessen bisheriger Anmeldedatenspeicher nach dem Entfernen der Standardmarkierung die Vererbungsquelle bleibt. Wird beim Upgrade automatisch eingetragen, wenn der frühere Eigentümer nicht main war.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Maximale Zeichenzahl pro Bootstrap-Datei`},help:{"v1-drlo3i-37":`Maximale Anzahl an Zeichen pro Bootstrap-Datei des Arbeitsbereichs, die vor einer Kürzung in den System-Prompt eingefügt werden (Standard: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Maximale Gesamtzeichenzahl für Bootstrap-Dateien`},help:{"v1-1evwsjb-2c":`Maximale Gesamtzahl an Zeichen aller eingefügten Bootstrap-Dateien des Arbeitsbereichs (Standard: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Verdichtung`},help:{"v1-1qxdwz8-5p":`Verhalten bei der Kontextverdichtung, wenn sich der Kontext den Token-Limits nähert, einschließlich Strategie und Sicherung von Gedächtnisinhalten vor der Verdichtung. Verwenden Sie diese Einstellung, wenn lange laufende Sitzungen bei begrenzten Kontextfenstern eine stabile Kontinuität benötigen.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Integrierte automatische Kontextverdichtung`},help:{"v1-1et7vwu-5l":`Integrierte proaktive automatische Komprimierung aktivieren (Standard: true). Auf false setzen, um die schwellenwertgesteuerte integrierte Komprimierung zu stoppen, während die Überlaufwiederherstellung von OpenClaw, die Vorabkomprimierung und der manuelle Befehl /compact erhalten bleiben.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Richtlinie für Bezeichner bei der Komprimierung`},help:{"v1-hby01l-4l":`Richtlinie zur Beibehaltung von Bezeichnern in Komprimierungszusammenfassungen: "strict" stellt integrierte Hinweise zur Beibehaltung undurchsichtiger Bezeichner voran (Standard), während "off" dieses Präfix deaktiviert.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Bei Komprimierung beizubehaltende aktuelle Tokens`},help:{"v1-tgysub-5h":`Minimales Token-Budget, das bei der Komprimierung aus dem neuesten Gesprächsfenster erhalten bleibt. Höhere Werte schützen die unmittelbare Kontextkontinuität, niedrigere Werte bewahren mehr vom weiter zurückliegenden Verlauf.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`Größenschwellenwert des aktiven Transkripts für die Komprimierung`},help:{"v1-u715n1-90":`Byte-Schwellenwert, der die normale lokale Vorabkomprimierung auslöst, wenn das für das Modell sichtbare Transkriptfenster (seit der letzten Komprimierung oder Zurücksetzung) diese Größe erreicht (Bytes oder Zeichenfolgen wie "20mb"). Zum Deaktivieren auf 0 setzen oder nicht festlegen. Begrenzt auch native Rollout-Transkripte des Codex app-server; übergroße native Threads beginnen von vorn.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Gedächtnissicherung vor der Komprimierung`},help:{"v1-18q0ve9-55":`Einstellungen zur Gedächtnissicherung vor der Komprimierung, die vor einer starken Komprimierung einen Schreibvorgang des Agenten ins Gedächtnis ausführen. Für lange Sitzungen aktiviert lassen, damit wichtiger Kontext vor einer drastischen Kürzung dauerhaft gespeichert wird.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Gedächtnissicherung vor der Kompaktierung aktiviert`},help:{"v1-9xllgp-5o":`Aktiviert die Gedächtnissicherung vor der Kompaktierung, bevor die Laufzeitumgebung den Verlauf nahe den Token-Limits stärker reduziert. Lassen Sie diese Option aktiviert, sofern Sie nicht bewusst gedächtnisbezogene Nebeneffekte in eingeschränkten Umgebungen deaktivieren möchten.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`Schwellenwert der Transkriptgröße für die Gedächtnissicherung vor der Kompaktierung`},help:{"v1-1rzov1e-93":`Erzwingt die Gedächtnissicherung vor der Kompaktierung, wenn der für das Modell sichtbare Transkriptausschnitt diesen Schwellenwert erreicht (Bytes oder Zeichenfolgen wie "2mb"). Nach der Kompaktierung umfasst dies den beibehaltenen letzten Teil und nachfolgende Gesprächsrunden statt des verworfenen Verlaufs. Verhindern Sie damit, dass lange Sitzungen hängen bleiben, auch wenn die Token-Zähler veraltet sind; zum Deaktivieren auf 0 setzen.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`Modellüberschreibung für die Gedächtnissicherung vor der Kompaktierung`},help:{"v1-1r3ctyu-7w":`Optionale Anbieter-/Modellüberschreibung, die nur für Gesprächsrunden zur Gedächtnissicherung vor der Kompaktierung verwendet wird. Legen Sie hierfür ein lokales Modell wie ollama/qwen3:8b fest, wenn die Extraktion dauerhaft zu speichernder Gedächtnisinhalte nicht das kostenpflichtige Modell der aktiven Sitzung nutzen soll. Die Überschreibung gilt exakt und übernimmt nicht die Fallback-Kette des aktiven Modells.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Weicher Schwellenwert für die Gedächtnissicherung vor der Kompaktierung`},help:{"v1-1dqo2l1-5c":`Abstand zur Kompaktierung (in Tokens), bei dem die Gedächtnissicherung vor der Kompaktierung ausgelöst wird. Verwenden Sie früher greifende Schwellenwerte für eine zuverlässigere dauerhafte Speicherung oder knappere Schwellenwerte für seltenere Sicherungen.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Vorabprüfung zur Kompaktierung während eines Durchlaufs`},help:{"v1-am6gbh-6x":`Optionale Vorabprüfung in eingebetteten OpenClaw-Werkzeugschleifen, die eine drohende Kontextüberlastung erkennt, nachdem ein Werkzeugergebnis angehängt wurde und bevor der nächste Modellaufruf erfolgt. Wenn sie aktiviert ist, verwendet OpenClaw die bestehende Wiederherstellungslogik der Vorabprüfung, um Werkzeugergebnisse zu kürzen oder den Kontext vor einem erneuten Versuch zu kompaktieren.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Vorabprüfung zur Kompaktierung während eines Durchlaufs aktiviert`},help:{"v1-engbwe-5u":`Strukturierte Prüfungen auf drohende Kontextüberlastung während eines Durchlaufs für eingebettete OpenClaw-Werkzeugschleifen aktivieren. Standard: false. Deaktiviert lassen, es sei denn, lange Sitzungen mit vielen Werkzeugaufrufen überschreiten das Kontextlimit, bevor die normale Kompaktierung am Ende des Durchlaufs ausgeführt werden kann.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Kompaktierungsmodus`},help:{"v1-1unahwc-76":`Modus der Kompaktierungsstrategie: "safeguard" (der tatsächliche Standard, wenn nicht festgelegt) wendet Schutzmechanismen an, um den jüngsten Kontext zu erhalten, während "default" eine einfache Zusammenfassung ohne diese Mechanismen verwendet. "default" nur festlegen, wenn die Zusammenfassung mit Schutzmechanismen bei Ihrem Anbieter Probleme verursacht.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Abweichendes Modell für die Kompaktierung`},help:{"v1-cfeys9-6q":`Optionale Angabe von Anbieter/Modell oder eines konfigurierten Alias ohne Anbieterpräfix, die nur für die Zusammenfassung bei der Kompaktierung verwendet wird. Aliasse ohne Anbieterpräfix werden vor der Weiterleitung aufgelöst; eine konfigurierte wörtliche Modell-ID hat Vorrang, wenn sie mit einem Alias kollidiert. Nicht festlegen, um weiterhin das primäre Agentenmodell zu verwenden.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Benutzer über Kompaktierung benachrichtigen`},help:{"v1-lvymm8-bv":`Wenn aktiviert, werden kurze Hinweise zur Kontextpflege an den Benutzer gesendet: beim Start und Abschluss der Komprimierung (zum Beispiel „🧹 Kontext wird komprimiert...“ und „🧹 Komprimierung abgeschlossen“) sowie wenn die Speichersicherung vor der Komprimierung ihre Versuche ausgeschöpft hat und die Antwort daher mit Einschränkungen fortgesetzt wird (zum Beispiel „⚠️ Speicherpflege vorübergehend fehlgeschlagen; Ihre Antwort wird fortgesetzt.“). Standardmäßig deaktiviert, damit die Kontextpflege unbemerkt und ohne Unterbrechungen erfolgt.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Kontextabschnitte nach der Komprimierung`},help:{"v1-1n0ln2u-5f":`Namen der H2/H3-Abschnitte aus AGENTS.md, die nach der Komprimierung bei expliziter Aktivierung erneut eingefügt werden. Nicht festlegen oder auf [] setzen, um das erneute Einfügen zu deaktivieren. Explizit auf ["Session Startup", "Red Lines"] setzen, um das bisherige Standardpaar zu aktivieren.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Indexsynchronisierung nach der Komprimierung`},help:{"v1-ekpjeq-6l":`Steuert den Modus für die Neuindizierung des Sitzungsspeichers nach der Komprimierung: "off", "async" oder "await" (Standard: "async"). Verwenden Sie "await" für maximale Aktualität, "async" für eine geringere Komprimierungslatenz und "off" nur, wenn die Synchronisierung des Sitzungsspeichers anderweitig erfolgt.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Komprimierungsanbieter`},help:{"v1-kiwk91-86":`ID eines registrierten Komprimierungsanbieter-Plugins, das für die Zusammenfassung verwendet wird. Wenn die ID festgelegt und der Anbieter registriert ist, wird dessen Methode summarize() anstelle der integrierten summarizeInStages-Pipeline aufgerufen. Bei einem Fehler des Anbieters wird auf die integrierte Zusammenfassung zurückgegriffen. Nicht festlegen, um die standardmäßige integrierte Zusammenfassung zu verwenden.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Qualitätssicherung der Komprimierung`},help:{"v1-u9ognp-4k":`Wiederholungseinstellungen für die Qualitätsprüfung von Zusammenfassungen bei der Komprimierung im Safeguard-Modus. Im Safeguard-Modus ist diese Funktion standardmäßig aktiviert; setzen Sie enabled: false, um die Prüfung und erneute Erstellung von Zusammenfassungen zu überspringen.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Qualitätssicherung bei der Komprimierung aktiviert`},help:{"v1-1xk2vt3-36":`Aktiviert Qualitätsprüfungen von Zusammenfassungen und Wiederholungsversuche zur erneuten Erstellung bei der Komprimierung im Safeguard-Modus. Standard: true im Safeguard-Modus.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Maximale Wiederholungsversuche der Qualitätssicherung bei der Komprimierung`},help:{"v1-n7l46y-3y":`Maximale Anzahl der Wiederholungsversuche zur erneuten Erstellung nach einer fehlgeschlagenen Qualitätsprüfung einer Zusammenfassung im Safeguard-Modus. Verwenden Sie kleine Werte, um zusätzliche Latenz und Token-Kosten zu begrenzen.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Neueste Gesprächsbeiträge bei der Komprimierung beibehalten`},help:{"v1-y34ihi-5k":`Anzahl der neuesten Benutzer- und Assistentenbeiträge, die außerhalb der Zusammenfassung im Safeguard-Modus wortgetreu beibehalten werden (Standard: 3). Erhöhen Sie diesen Wert, um den genauen Kontext des jüngsten Dialogs zu bewahren, oder verringern Sie ihn, um die Einsparungen durch Komprimierung zu maximieren.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Denkniveau bei der Komprimierung`},help:{"v1-1vafgaw-g1":`Denkstufe, die nur für eingebettete OpenClaw-Kompaktierungszusammenfassungen verwendet wird: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" oder "inherit". Standardmäßig wird die Kompaktierungspräferenz des Anbieters verwendet, andernfalls "low"; natives lokales Ollama bevorzugt "off". Mit "inherit" wird die Denkstufe der Sitzung übernommen. Explizite Einstellungen überschreiben die Standardwerte des Anbieters, und die gewählte Stufe wird auf den vom tatsächlichen Kompaktierungsmodell und der Laufzeit unterstützten Bereich begrenzt. Die native Kompaktierung des Codex app-server ignoriert diese Einstellung, da ihre Kompaktierungsanfrage keine vorgangsspezifische Überschreibung der Denkstufe unterstützt. OpenClaw protokolliert dazu eine Warnung.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Zeitlimit für die Kompaktierung (Sekunden)`},help:{"v1-2bhn29-7m":`Sicherheitszeitfenster in Sekunden für jede Modellanfrage der integrierten Kompaktierung (Standard: 180). Bei mehrstufiger Kompaktierung beginnt das Zeitfenster mit jeder aufeinanderfolgenden Anfrage neu, sodass die gesamte Kompaktierung länger dauern kann. Eine von einem Plugin gesteuerte Kompaktierung erhält ein einziges Zeitfenster für den gesamten Vorgang.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Kontexteinfügung`},help:{"v1-u18x0-7u":`Steuert das Einfügen von Bootstrap-Dateien des Arbeitsbereichs in der eingebetteten Laufzeitumgebung: "always" verwendet das normale Einfügen (Standard), "continuation-skip" überspringt geeignete Fortsetzungsrunden nach einer protokollierten Runde mit vollständigem Bootstrap, und "never" deaktiviert das Einfügen. Steuert nicht die CLI-gestützte Prompt-Vorbereitung.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Standardmäßige Kontextlimits`},help:{"v1-1coeez8-5d":`Gezielte Standardwerte für das Kontextbudget pro Agent für ausgewählte umfangreiche Auszüge und eingefügte Promptblöcke. Damit lassen sich begrenzte Lese- und Einfügungsgrößen anpassen, ohne unbegrenzte Aufrufpfade erneut zu öffnen.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Standardmäßige maximale Zeichenanzahl für memory_get`},help:{"v1-1qb40qv-4v":`Standardmäßige maximale Anzahl der von memory_get zurückgegebenen Zeichen, bevor Metadaten zur Kürzung und ein Fortsetzungshinweis hinzugefügt werden. Erhöhen Sie diesen Wert, um sich den früheren, größeren Auszügen anzunähern, halten Sie ihn jedoch begrenzt.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Standardmäßige maximale Zeichenanzahl nach der Kompaktierung`},help:{"v1-64qo8g-5r":`Standardmäßige maximale Anzahl der Zeichen aus AGENTS.md, die bei der Kontextaktualisierung nach der Kompaktierung eingefügt werden. Senken Sie diesen Wert, um die Wiederherstellung nach der Kompaktierung kostengünstiger zu machen, oder erhöhen Sie ihn für Agenten, die längere Startanweisungen benötigen.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Arbeitsverzeichnis`},help:{"v1-1y8wlxn-6a":`Arbeitsverzeichnis für Agentenantwortläufe, getrennt von der Arbeitsbereichsinitialisierung und den Gedächtnisdateien. Agentenspezifische cwd-Werte und beim Sitzungsstart festgelegte cwd-Werte haben Vorrang. Unterstützt ~ und relative Pfade; ein abweichendes cwd erfordert einen Lauf außerhalb der Sandbox.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Entscheidungsmodell`},help:{"v1-7nd7ze-64":`Optionaler Anbieter/optionales Modell für typisierte Auswahlentscheidungen, Bewertungen und Wahrscheinlichkeiten boolescher Werte. Wenn nicht festgelegt oder leer, werden Entscheidungsaufrufe deaktiviert. Unterstützende Plugins senden aufgabenbezogene Informationen in begrenztem Umfang an diesen Anbieter; Chat- und Hilfsmodelle bleiben unverändert.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`Eingebettetes OpenClaw`},help:{"v1-1keek32-3k":`Sicherheitseinstellungen für die eingebettete OpenClaw-Ausführungsumgebung, die steuern, inwiefern lokalen Agenteneinstellungen im Arbeitsbereich vertraut wird und wie diese in OpenClaw-Sitzungen angewendet werden.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Ausweichverfahren bei Cyberrichtlinien`},help:{"v1-xvv6wl-2r":`Automatische Eskalation an Daybreak bei Ablehnungen aufgrund von OpenAI-Cyberrichtlinien in der eingebetteten Laufzeitumgebung, sofern eine sichere Wiederholung möglich ist.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Wartezeit für das Ausweichverfahren bei Cyberrichtlinien`},help:{"v1-16smtrl-25":`Wie lange ein nicht verfügbares Eskalationsziel in der aktuellen Sitzung übersprungen wird.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Modus des Ausweichverfahrens bei Cyberrichtlinien`},help:{"v1-rzsd2b-2h":`Automatische Eskalation aktivieren ("auto", Standard) oder Ablehnungen des Anbieters als endgültig behandeln ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`Modell für das Ausweichverfahren bei Cyberrichtlinien`},help:{"v1-1aaj8nn-1t":`Anbieter/Modell, das als Ziel für die automatische Eskalation bei Cyberrichtlinien verwendet wird.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Ausführungsvertrag für eingebettetes OpenClaw`},help:{"v1-1fch2ig-66":`Ausführungsvertrag für eingebettetes OpenClaw: "default" behält das Standardverhalten der Ausführungsumgebung bei, während "strict-agentic" die strukturierte Planverfolgung und die nicht sichtbare Wiederherstellung von Gesprächsschritten für unterstützte Läufe der GPT-5-Familie von OpenAI/OpenAI Codex aktiviert.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Richtlinie für Projekteinstellungen von eingebettetem OpenClaw`},help:{"v1-fdyy04-65":'Legt fest, wie eingebettetes OpenClaw mit der arbeitsbereichslokalen Datei `.openclaw/settings.json` umgeht: "sanitize" (Standard) entfernt shellPath/shellCommandPrefix, "ignore" deaktiviert Projekteinstellungen vollständig und "trusted" übernimmt Projekteinstellungen unverändert.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Experimentelle Agentenoptionen`},help:{"v1-cvv5cl-2w":`Experimentelle Standardoptionen für Agenten. Lassen Sie diese deaktiviert, es sei denn, Sie testen gezielt eine Vorschaufunktion.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Schlanken Modus für lokale Modelle aktivieren (experimentell)`},help:{"v1-gj06u6-7b":`Erweiterte Einstellung zur Fehlerbehebung, die optionale Tools wie browser, automations und message einschränkt. Standardmäßig deaktiviert; unterstützte lokale Laufzeitumgebungen verwenden die automatische Tool-Suche ohne diese Einschränkung. Explizite Tool-Freigaben und erforderliche Zustellungstools bleiben erhalten.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Standard-Schnellmodus für Agenten`},help:{"v1-zv4y98-2z":`Standardrichtlinie für den Schnellmodus der Agentenschleife ("auto", true oder false). Einzelne Agenteneinträge überschreiben sie.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`Heartbeat-Agent`},help:{"v1-1jynxej-3w":`Agent, der für Heartbeat-Läufe im Hintergrund zuständig ist, wenn keine agentenspezifische Heartbeat-Konfiguration vorhanden ist. Nicht festlegen, um das konfigurierte Standardrouting beizubehalten.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Heartbeat-Richtlinie für Direktnachrichten`},help:{"v1-nhyxa9-41":`Steuert, ob Heartbeat-Nachrichten an Direktchats zugestellt werden dürfen: "allow" (Standard) erlaubt die Zustellung von Direktnachrichten und "block" unterdrückt den Versand an direkte Empfänger.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Heartbeat-Zeitlimit (Sekunden)`},help:{"v1-1se21py-5f":`Maximal zulässige Zeit in Sekunden für einen Heartbeat-Agentendurchlauf, bevor er abgebrochen wird. Nicht festlegen, um agents.defaults.timeoutSeconds zu verwenden, falls gesetzt; andernfalls wird das Heartbeat-Intervall verwendet, begrenzt auf 600 Sekunden.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Max. menschenähnliche Verzögerung (ms)`},help:{"v1-vnmvli-1m":`Maximale Verzögerung in ms für benutzerdefinierte humanDelay (Standard: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Min. menschenähnliche Verzögerung (ms)`},help:{"v1-5nrtr5-1l":`Minimale Verzögerung in ms für benutzerdefinierte humanDelay (Standard: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Modus für menschenähnliche Verzögerung`},help:{"v1-k7hyg3-1n":`Verzögerungsstil für blockweise Antworten ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Max. Bildabmessung (px)`},help:{"v1-vju8x-2u":`Maximale Bildseitenlänge in Pixeln beim Bereinigen von Bilddaten in Transkripten und Tool-Ergebnissen (Standard: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Ausweichmodelle für Bilder`},help:{"v1-1kgx5i9-1b":`Geordnete Liste von Ausweichmodellen für Bilder (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Bildmodell`},help:{"v1-dstqyh-2c":`Optionales Bildmodell (provider/model), das verwendet wird, wenn das primäre Modell keine Bildeingabe unterstützt.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Bildqualität`},help:{"v1-1uyxc5s-6u":`Bevorzugte Medienkomprimierung für das Bild-Tool: "auto" passt sich an Anbieter-/Modellgrenzen und die Bildanzahl an, "efficient" spart Tokens und Bytes, "balanced" behält den aktuellen Mittelweg bei und "high" bewahrt mehr Details bei Screenshots und Dokumentbildern.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Ausweichmodelle für die Bildgenerierung`},help:{"v1-oljfk4-1m":`Ausweichmodelle für die Bildgenerierung in festgelegter Reihenfolge (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Modell für die Bildgenerierung`},help:{"v1-g4yw0h-2o":`Optionales Modell für die Bildgenerierung (provider/model), das von der gemeinsam genutzten Bildgenerierungsfunktion verwendet wird.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Zeitlimit für die Bildgenerierung (ms)`},help:{"v1-9yesfj-31":`Standardzeitlimit für Anbieteranfragen in Millisekunden bei image_generate-Aufrufen. timeoutMs pro Aufruf überschreibt diesen Wert.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Ausweichmodelle für die Musikgenerierung`},help:{"v1-wyg9xe-1m":`Ausweichmodelle für die Musikgenerierung in festgelegter Reihenfolge (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Modell für die Musikgenerierung`},help:{"v1-xs1e2h-2o":`Optionales Modell für die Musikgenerierung (provider/model), das von der gemeinsam genutzten Musikgenerierungsfunktion verwendet wird.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Ausweichmodelle für die Videogenerierung`},help:{"v1-wpbf1e-1m":`Geordnete Ausweichmodelle für die Videogenerierung (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Modell für die Videogenerierung`},help:{"v1-hfmlbl-2o":`Optionales Modell für die Videogenerierung (provider/model), das von der gemeinsam genutzten Videogenerierungsfunktion verwendet wird.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Zeitlimit für die Videogenerierung (ms)`},help:{"v1-1bqj80s-4i":`Standardzeitlimit für Anbieteranfragen in Millisekunden bei video_generate-Aufrufen. timeoutMs pro Aufruf hat Vorrang vor diesem Wert, und dieser Wert hat Vorrang vor den vom Anbieter festgelegten Standardwerten.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Ausweichmodelle`},help:{"v1-t4djq2-24":`Geordnete Ausweichmodelle (provider/model). Werden verwendet, wenn das primäre Modell ausfällt.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Primäres Modell`},help:{"v1-1i8a1v4-v":`Primäres Modell (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Modellrichtlinie`},help:{"v1-z0txb7-2e":`Explizite Richtlinie für Modellüberschreibungen. Lassen Sie sie weg oder lassen Sie allow leer, um jedes Modell zuzulassen.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Zulässige Modelle`},help:{"v1-1fqace-3x":`Zulässige Referenzen für Modellüberschreibungen. Akzeptiert Aliase, vollständige "provider/model"-Referenzen und Anbieter-Platzhalter wie "openai/*". Ein leerer Wert lässt jedes Modell zu.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Modelle`},help:{"v1-13cvq23-4i":`Konfigurierter Modellkatalog und modellspezifische Einstellungen. Einträge enthalten Aliase, Parameter, Laufzeitmetadaten und Überschreibungen für den Code-Modus; sie schränken Modellüberschreibungen nicht ein.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Modelllaufzeit des Standardagenten`},help:{"v1-6km9kx-41":`Optionale modellspezifische Laufzeitrichtlinie für den Standardagenten. Verwenden Sie diese für modellspezifische Laufzeitausnahmen, statt eine Laufzeit für den gesamten Agenten festzulegen.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`Modelllaufzeit-ID des Standardagenten`},help:{"v1-1co96w7-4a":`Modelllaufzeit-ID des Standardagenten: "openclaw", "auto", eine registrierte Plugin-Harness-ID wie "codex" oder ein unterstützter CLI-Backend-Alias wie "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Code-Modus`},help:{"v1-rsdl5o-6x":`OpenClaw Code Mode für genau diesen Anbieter und dieses Modell: „Ein“ erzwingt die Aktivierung, „Aus“ deaktiviert ihn und „Standard“ übernimmt tools.codeMode.enabled. Agentenspezifische Aktivierungseinstellungen haben Vorrang. Dies ändert weder die ausgewählte Laufzeit noch den nativen Code Mode von Codex.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Geltungsbereich der Modellauswahl`},help:{"v1-sj8owq-bl":`Geltungsbereich für Chatbefehle und Modellaktualisierungen von Gateway-Sitzungen ohne expliziten Geltungsbereich: "session" (Standard) ändert nur die aktuelle Sitzung, "agent" aktualisiert zusätzlich das primäre Modell dieses Agenten und "global" aktualisiert zusätzlich den gemeinsamen Rückfallwert agents.defaults.model. Explizite Geltungsbereichsflags haben Vorrang; Änderungen an konfigurierten Standardwerten erfordern Inhaber- oder Administratorberechtigungen. Telegram-Callback-Auswahldialoge und die eingebettete lokale TUI bleiben auf die Sitzung beschränkt.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Maximale PDF-Größe (MB)`},help:{"v1-1uig1dr-1u":`Maximale PDF-Dateigröße in Megabyte für das PDF-Werkzeug (Standard: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Maximale PDF-Seitenzahl`},help:{"v1-11na7hp-1y":`Maximale Anzahl der PDF-Seiten, die das PDF-Tool verarbeitet (Standard: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`PDF-Ersatzmodelle`},help:{"v1-89ebd8-19":`Geordnete Liste der PDF-Ersatzmodelle (Anbieter/Modell).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`PDF-Modell`},help:{"v1-2ktkxt-2y":`Optionales PDF-Modell (Anbieter/Modell) für das PDF-Analysetool. Standardmäßig wird imageModel verwendet, danach das Sitzungsmodell.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Repository-Stammverzeichnis`},help:{"v1-j3sh74-2h":`Optionales Repository-Stammverzeichnis, das in der Laufzeitzeile des Systemprompts angezeigt wird (überschreibt die automatische Erkennung).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`CDP-Quellportbereich des Sandbox-Browsers`},help:{"v1-1jkowdc-2b":`Optionale CIDR-Zulassungsliste für eingehende CDP-Verbindungen an der Container-Grenze (zum Beispiel 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Sandbox-Browser-Netzwerk`},help:{"v1-8m74ud-5w":`Docker-Netzwerk für Sandbox-Browser-Container (Standard: openclaw-sandbox-browser). Verwenden Sie das dedizierte Standardnetzwerk oder ein benutzerdefiniertes Bridge-Netzwerk; "none" wird nicht unterstützt, da die Browsersteuerung veröffentlichte CDP-Ports benötigt.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Beitritt zu Container-Namensräumen für Sandbox-Docker erlauben`},help:{"v1-qm39de-4c":`GEFÄHRLICHE Notfall-Ausnahme, die den Docker-Netzwerkmodus container:<id> für die Sandbox erlaubt. Dadurch wird dem Namensraum eines anderen Containers beigetreten und die Sandbox-Isolation geschwächt.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`Docker-GPUs der Sandbox`},help:{"v1-jj0yhw-4k":`Optionaler Wert für die Docker-GPU-Durchreichung, der an --gpus übergeben wird, zum Beispiel "all" oder "device=GPU-uuid". Erfordert eine kompatible Host-Laufzeitumgebung wie NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Ziel für den Legacy-Sitzungsspeicher`},help:{"v1-1xkej6i-2g":`Zuständiger Agent für die Upgrade-Kompatibilität ausgemusterter main-Agent-Einträge und fester Legacy-Sitzungsspeicher.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Zuständiger Agent für den Legacy-Sitzungsspeicher`},help:{"v1-ommm7e-5w":`Agent, dem nach der Abschaffung der Standardmarkierung ausgemusterte main-Agent-Einträge oder Einträge ohne Zuordnung in einem festen Legacy-Sitzungsspeicher gehören. Wird beim Upgrade automatisch eingetragen, wenn der bisher zuständige Agent weder main noch der einzige Agent war.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Optionale Standard-Zulassungsliste für Skills, die von Agenten geerbt wird, bei denen agents.entries.*.skills nicht angegeben ist. Für uneingeschränkte Skills weglassen oder [] festlegen, damit erbende Agenten keine Skills erhalten. Beachten Sie, dass eine explizite Angabe von agents.entries.*.skills diesen Standard ersetzt, statt mit ihm zusammengeführt zu werden.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Erstellung von Bootstrap-Dateien des Arbeitsbereichs überspringen`},help:{"v1-kbstgw-5v":`Überspringt die automatische Erstellung von Bootstrap-Dateien des Arbeitsbereichs, nicht das Einfügen vorhandener Dateien. Setzen Sie für die eingebettete Laufzeitumgebung agents.defaults.contextInjection auf "never", um das Einfügen zu deaktivieren, sofern dies nicht für einzelne Agenten überschrieben wird.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Übersprungene optionale Bootstrap-Dateien`},help:{"v1-1j2z4yj-4c":`Optionale Bootstrap-Dateien, die nicht in Agenten-Arbeitsbereichen erstellt werden sollen. Gültige Werte: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md wird akzeptiert, hat aber keine Wirkung).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Startkontext`},help:{"v1-1ugsihy-5o":`Von der Laufzeitumgebung verwalteter Vorspann für die erste Interaktion nach "/new" und "/reset" ohne Argumente. Hiermit steuern Sie, ob aktuelle tägliche Gedächtnisdateien vorab in den ersten Prompt geladen werden, statt das Modell entscheiden zu lassen, was es lesen soll.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Startkontext anwenden auf`},help:{"v1-wav4a5-36":`Legt fest, welche Zurücksetzungsbefehle ohne Argumente einen Startkontext erhalten: "new", "reset" oder beide angeben (Standard: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Tage mit täglichem Gedächtnis im Startkontext`},help:{"v1-4i5xcm-3p":`Anzahl der zu ladenden datierten Gedächtnisdateien, rückwärts ab heute in der konfigurierten Benutzerzeitzone gezählt (Standard: 2 für heute + gestern).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Startkontext aktivieren`},help:{"v1-1d5vz2u-4i":`Aktiviert den Startkontext-Vorspann beim Zurücksetzen einer Sitzung ohne Argumente (Standard: true). Deaktivieren Sie dies, um zum rein promptbasierten Verhalten zurückzukehren, ohne dass die Laufzeitumgebung tägliche Gedächtnisdateien lädt.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Maximale Bytes pro Datei im Startkontext`},help:{"v1-11cbian-41":`Maximal zulässige Anzahl an Bytes pro täglicher Gedächtnisdatei beim Erstellen des Startkontexts (Standard: 16384). Dateien, die dieses unter Wahrung der Zeichengrenzen angewendete Leselimit überschreiten, werden übersprungen.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Maximale Zeichen pro Datei im Startkontext`},help:{"v1-10z53s-2u":`Maximale Anzahl an Zeichen, die aus jeder geladenen täglichen Gedächtnisdatei im Startvorspann beibehalten werden (Standard: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Maximale Gesamtzeichenzahl des Startkontexts`},help:{"v1-sf676u-54":`Maximale Gesamtzahl der Zeichen, die aus allen geladenen täglichen Gedächtnisdateien im Startvorspann beibehalten werden (Standard: 2800). Weitere Dateien werden im Vorspann gekürzt, sobald diese Grenze erreicht ist.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Delegierungsmodus für Unteragenten`},help:{"v1-pqewbk-5o":`Stärke der ausschließlich per Prompt gesteuerten Delegierung an Unteragenten. Standardmäßig gilt "prefer" in der Hauptsitzung jedes Agenten und "suggest" in allen anderen Sitzungen; "prefer" weist den Agenten nachdrücklich an, nicht triviale Aufgaben über sessions_spawn zu delegieren.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Ziel des Systemagenten`},help:{"v1-1wwimo9-34":`Zieleinstellungen für die im Hintergrund laufende Inferenz des OpenClaw-Systemagenten und von Custodian sowie für ausgewählte Lesezugriffe von Operatoren ohne expliziten Geltungsbereich.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Eigentümer des Systemagenten`},help:{"v1-15rvt92-8c":`Agent, dessen Modell und Zugangsdaten für Hintergrundanfragen des Systemagenten und von Custodian verwendet werden. Wird auch verwendet, wenn bei models.list, models.authStatus, skills.status, doctor.memory.status oder einem infer-CLI-Befehl, der den agenteneigenen Modell- oder Authentifizierungsstatus ermittelt, agentId oder --agent fehlt; eine explizite agentId in der Anfrage hat immer Vorrang.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Tippintervall (Sekunden)`},help:{"v1-1y701ox-42":`Steuert für jeden Agenten das Intervall in Sekunden, in dem der Tippindikator aktiv gehalten wird. Erhöhen Sie den Wert, um die Aktualisierungshäufigkeit auf allen Kanälen mit Tippindikator zu verringern.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Tippmodus`},help:{"v1-m2hvpw-3m":`Legt fest, wann die Tippanzeige für Agenten startet: "never", "instant", "thinking" oder "message". Ein pro Agent festgelegter typingMode überschreibt diesen Standardwert.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Hilfsmodell`},help:{"v1-1wg7h1a-7s":`Optionales kostengünstigeres Modell (provider/model oder Alias) für kurze interne Aufgaben wie das Generieren von Titeln und Fortschrittsmeldungen. Wenn nicht festgelegt, wird das deklarierte kleine Modell des primären Anbieters verwendet, sofern verfügbar (andernfalls das primäre Modell). Auf eine leere Zeichenfolge setzen, um das Routing für Hilfsaufgaben zu deaktivieren.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Ersatzmodelle für Sprachverarbeitung`},help:{"v1-faazv4-1b":`Geordnete Liste von Ersatzmodellen für Sprachverarbeitung (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Modell für Sprachverarbeitung`},help:{"v1-1yeh3h4-2t":`Optionales Modell für Sprachverarbeitung (provider/model), das für Sprachausgabe, Transkription und Echtzeit-Sprachfunktionen verwendet wird.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Zeitlimit für Sprachverarbeitung (ms)`},help:{"v1-1sbergs-32":`Standardzeitlimit für Anbieteranfragen in Millisekunden bei Vorgängen mit Modellen für Sprachverarbeitung, sofern der Aufrufer Zeitlimits unterstützt.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Arbeitsbereich`},help:{"v1-1lssx8l-5w":`Standard-Arbeitsbereich des Agenten für Initialisierungs- und Gedächtnisdateien. Wird auch als Arbeitsverzeichnis verwendet, wenn agents.defaults.cwd nicht festgelegt ist. Bei der Ausführung über Wrapper explizit festlegen, damit die Pfadauflösung deterministisch bleibt.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Agentenliste`},help:{"v1-yurood-5l":`Explizite Liste konfigurierter Agenten mit IDs und optionalen Überschreibungen für Modell, Tools, Identität und Arbeitsbereich. IDs dauerhaft stabil halten, damit Bindungen, Genehmigungen und Sitzungsrouting deterministisch bleiben.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Veraltete Agentenlaufzeit`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`ID der veralteten Agentenlaufzeit`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Maximale Zeichenzahl für Agenten-Bootstrap`},help:{"v1-rsf1es-4j":`Agentenspezifische Überschreibung der maximalen Zeichenzahl pro Bootstrap-Datei des Arbeitsbereichs, die in den System-Prompt dieses Agenten eingefügt wird. Weglassen, um agents.defaults.bootstrapMaxChars zu übernehmen.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Maximale Gesamtzeichenzahl für Agenten-Bootstrap`},help:{"v1-1bal68p-4y":`Agentenspezifische Überschreibung der maximalen Gesamtzeichenzahl aller Bootstrap-Dateien des Arbeitsbereichs, die in den System-Prompt dieses Agenten eingefügt werden. Weglassen, um agents.defaults.bootstrapTotalMaxChars zu übernehmen.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Kontexteinfügung für Agenten`},help:{"v1-1j68ys8-50":`Agentenspezifische Einstellung für das Einfügen von Bootstrap-Dateien des Arbeitsbereichs in die eingebettete Laufzeitumgebung. Weglassen, um agents.defaults.contextInjection zu übernehmen. Steuert nicht die CLI-gestützte Prompt-Vorbereitung.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Kontextgrenzen für Agenten`},help:{"v1-f1qxq8-3c":`Optionale agentenspezifische Überschreibungen für die gezielten Einstellungen des Kontextbudgets. Nicht angegebene Felder übernehmen die Werte aus agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Maximale Zeichenzahl für memory_get des Agenten`},help:{"v1-12hlmsv-1v":`Agentenspezifische Überschreibung des standardmäßigen maximalen Zeichenbudgets für memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Maximale Zeichenzahl des Agenten nach der Komprimierung`},help:{"v1-15s0npd-1w":`Agentenspezifische Überschreibung des Zeichenbudgets für AGENTS.md-Auszüge nach der Komprimierung.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Arbeitsverzeichnis des Agenten`},help:{"v1-mv43ak-6a":`Arbeitsverzeichnis für die Antwortläufe dieses Agenten. Überschreibt agents.defaults.cwd, jedoch nicht das beim Start einer Sitzung festgelegte cwd; Bootstrap- und Gedächtnisdateien bleiben im Arbeitsbereich. Unterstützt ~ und relative Pfade; ein abweichendes cwd erfordert einen Lauf ohne Sandbox.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Entscheidungsmodell des Agenten`},help:{"v1-1mih8bf-3j":`Entscheidungsmodell pro Agent. Wenn nicht festgelegt, wird agents.defaults.decisionModel übernommen; eine leere Zeichenfolge deaktiviert Entscheidungsaufrufe für diesen Agenten.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`Eingebettetes OpenClaw des Agenten`},help:{"v1-uoomza-4b":`Optionale agentenspezifische Überschreibungen für eingebettetes OpenClaw. Damit lässt sich für bestimmte Agenten ein strengeres GPT-5-Ausführungsverhalten aktivieren, ohne die globale Standardeinstellung zu ändern.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Ausführungsvertrag für eingebettetes OpenClaw des Agenten`},help:{"v1-1d1jaoi-7k":`Optionale agentenspezifische Überschreibung des Ausführungsvertrags für eingebettetes OpenClaw. Setzen Sie "strict-agentic", um für diesen Agenten bei unterstützten OpenAI/OpenAI Codex-Läufen der GPT-5-Familie eine strukturierte Planverfolgung und eine nicht sichtbare Wiederherstellung von Gesprächsrunden zu aktivieren, oder "default", um das Standardverhalten des Runners zu übernehmen.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Experimentelle Optionen des Agenten`},help:{"v1-1r06jov-2a":`Agentenspezifische experimentelle Optionen. Nicht angegebene Felder übernehmen die Werte aus agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Schlanker Modus für lokale Modelle des Agenten`},help:{"v1-5o3tgx-58":`Agentenspezifische Einstellung zur Fehlerbehebung für den schlanken Modus lokaler Modelle. Aktivieren Sie diese nur, wenn das Einschränken optionaler Tools einen nachgewiesenen Modellfehler behebt, ohne die Tools aller Agenten zu reduzieren.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Standard für den Schnellmodus des Agenten`},help:{"v1-1ujydjc-3o":`Optionaler Standardwert für den Schnellmodus pro Agent ("auto", true oder false). Gilt, wenn keine abweichende Einstellung für den Schnellmodus pro Nachricht oder Sitzung festgelegt ist.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Richtlinie für Heartbeat-Direktnachrichten`},help:{"v1-11gl9l0-41":`Agentenspezifische Überschreibung der Richtlinie für die Heartbeat-Zustellung per Direktnachricht (DM); verwenden Sie "block" für Agenten, die Heartbeat-Benachrichtigungen nur an Ziele außerhalb von Direktnachrichten senden sollen.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Heartbeat-Zeitlimit (Sekunden)`},help:{"v1-kdetv4-6s":`Agentenspezifische maximale Dauer in Sekunden für einen Heartbeat-Agentendurchlauf, bevor er abgebrochen wird. Nicht festlegen, um das zusammengeführte Heartbeat-Zeitlimit zu übernehmen, danach agents.defaults.timeoutSeconds, sofern festgelegt, andernfalls das Heartbeat-Intervall, begrenzt auf 600 Sekunden.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Identitätsavatar`},help:{"v1-pzp9gr-1t":`Agentenavatar (Pfad relativ zum Arbeitsbereich, http(s)-URL oder Daten-URI).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Modellrichtlinie des Agenten`},help:{"v1-17d5je8-2r":`Agentenspezifische Richtlinie für Modellüberschreibungen. Eine explizite Zulassungsliste ersetzt die Standardrichtlinie für diesen Agenten.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Zulässige Agentenmodelle`},help:{"v1-v1ueke-5b":`Zulässige Modellreferenzen für Überschreibungen bei diesem Agenten. Akzeptiert Aliasse, vollständige "provider/model"-Referenzen und Präfixmuster mit abschließendem Platzhalter wie "provider/*" oder "provider/namespace/*"; ein leerer Wert erlaubt jedes Modell.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Modellüberschreibungen des Agenten`},help:{"v1-nld1vq-1v":`Agentenspezifische Überschreibungen des Modellkatalogs mit vollständigen Anbieter-/Modell-IDs als Schlüssel.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Modelllaufzeit des Agenten`},help:{"v1-7b59y-3s":`Optionale modellspezifische Laufzeitrichtlinie für diesen Agenten. Verwenden Sie diese für agentenspezifische Modellausnahmen, statt eine Laufzeit für den gesamten Agenten festzulegen.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`ID der Modelllaufzeit des Agenten`},help:{"v1-1ckfc39-46":`Agentenspezifische Modelllaufzeit-ID: "openclaw", "auto", eine registrierte Plugin-Harness-ID wie "codex" oder ein unterstützter CLI-Backend-Alias wie "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Code-Modus`},help:{"v1-91zu7f-7m":`OpenClaw Code Mode für diesen Agenten und genau diesen Anbieter/dieses Modell: Ein erzwingt die Aktivierung, Aus deaktiviert ihn, und Standard übernimmt zuerst die Aktivierungseinstellung des Agenten, dann die gemeinsame Modellüberschreibung und schließlich tools.codeMode.enabled. Dies ändert weder die ausgewählte Laufzeit noch den nativen Code Mode von Codex.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Standard für die Sichtbarkeit der Gedankengänge des Agenten`},help:{"v1-13ly0xf-3m":`Optionale agentenspezifische Standardeinstellung für die Sichtbarkeit der Gedankengänge (on|off|stream). Gilt, wenn keine Überschreibung auf Nachrichten- oder Sitzungsebene festgelegt ist.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Agentenlaufzeit`},help:{"v1-avjgkf-3l":`Optionaler Laufzeitdeskriptor für diesen Agenten. Verwenden Sie embedded für die standardmäßige OpenClaw-Ausführung oder acp für die Standardeinstellungen eines externen ACP-Harness.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`ACP-Laufzeit des Agenten`},help:{"v1-91zvdk-3i":`ACP-Laufzeitvorgaben für diesen Agenten bei runtime.type=acp. ACP-Überschreibungen auf Bindungsebene haben weiterhin pro Konversation Vorrang.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`ACP-Harness-Agent des Agenten`},help:{"v1-1pm98vp-37":`Optionale ID des ACP-Harness-Agenten, der für diesen OpenClaw-Agenten verwendet werden soll (zum Beispiel codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`ACP-Backend des Agenten`},help:{"v1-1u3cdsg-2n":`Optionale Überschreibung des ACP-Backends für die ACP-Sitzungen dieses Agenten (andernfalls wird der globale Wert acp.backend verwendet).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`ACP-Arbeitsverzeichnis des Agenten`},help:{"v1-d9p9rf-1t":`Optionales Standardarbeitsverzeichnis für die ACP-Sitzungen dieses Agenten.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`ACP-Modus des Agenten`},help:{"v1-yatuk4-21":`Optionaler Standardmodus für die ACP-Sitzungen dieses Agenten (persistent oder oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Laufzeittyp des Agenten`},help:{"v1-139fbk6-2r":`Laufzeittyp für diesen Agenten: "embedded" (Standardlaufzeit von OpenClaw) oder "acp" (ACP-Harness-Vorgaben).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`CDP-Quellbereich des Sandbox-Browsers des Agenten`},help:{"v1-1q1qyso-1d":`Agentenspezifische Überschreibung der CIDR-Zulassungsliste für CDP-Quellen.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Netzwerk des Sandbox-Browsers des Agenten`},help:{"v1-13bdfww-4c":`Agentenspezifische Überschreibung für das Docker-Netzwerk des Sandbox-Browsers. Verwenden Sie ein Bridge-Netzwerk; "none" wird nicht unterstützt, da die Browsersteuerung veröffentlichte CDP-Ports benötigt.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Beitritt zu Container-Namespaces in Docker für die Agenten-Sandbox erlauben`},help:{"v1-1xtnseb-2i":`GEFÄHRLICHE agentenspezifische Überschreibung für Beitritte zu Container-Namespaces im Docker-Netzwerkmodus der Sandbox.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`Docker-GPUs der Agenten-Sandbox`},help:{"v1-1kek1n2-1t":`Agentenspezifische Überschreibung der Docker-GPU-Durchreichung für Sandbox-Container.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Skill-Filter des Agenten`},help:{"v1-igchue-6v":`Optionale Liste zugelassener Skills für diesen Agenten. Wenn sie weggelassen wird, erbt der Agent agents.defaults.skills, sofern festgelegt; andernfalls bleiben Skills uneingeschränkt. Setzen Sie [], um keine Skills zuzulassen. Eine explizite Liste ersetzt geerbte Standardwerte vollständig, statt mit ihnen zusammengeführt zu werden.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Skills-Limits des Agenten`},help:{"v1-1sv10v9-4y":`Optionale agentenspezifische Überschreibungen für die Budgets des Skills-Subsystems. Verwenden Sie dies, wenn ein Agent ein anderes Skills-Prompt-Budget benötigt, ohne einen zweiten allgemeinen Konfigurationspfad für Kontextlimits einzuführen.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Maximale Zeichenzahl im Skills-Prompt des Agenten`},help:{"v1-dys63y-52":`Agentenspezifische Überschreibung des Zeichenbudgets für den Skills-Prompt. Dies erweitert den bestehenden Pfad skills.limits.maxSkillsPromptChars, statt dasselbe Budget über contextLimits zu steuern.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Delegationsmodus für Subagenten`},help:{"v1-1rkgh6p-4s":`Agentenspezifische Überschreibung der Delegationsstärke für Subagenten. Weglassen, um in der Hauptsitzung dieses Agenten "prefer" und andernorts "suggest" zu verwenden; ein explizites "prefer" oder "suggest" hat immer Vorrang.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Standard-Denkniveau des Agenten`},help:{"v1-173q7vy-43":`Optionales agentenspezifisches Standard-Denkniveau. Überschreibt agents.defaults.thinkingDefault für diesen Agenten, wenn keine nachrichten- oder sitzungsspezifische Überschreibung festgelegt ist.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Ergänzungen zur Tool-Freigabeliste des Agenten`},help:{"v1-1550ui9-46":`Agentenspezifische ergänzende Freigabeliste für Tools zusätzlich zur globalen Richtlinie und zur Profilrichtlinie. Eng begrenzen, um eine versehentliche Ausweitung der Berechtigungen bei spezialisierten Agenten zu vermeiden.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Tool-Richtlinie des Agenten nach Anbieter`},help:{"v1-mthxv9-4t":`Agentenspezifische Überschreibungen der anbieterspezifischen Tool-Richtlinien zur kanalbezogenen Steuerung von Funktionen. Verwenden, wenn ein einzelner Agent bei einem Anbieter strengere Einschränkungen benötigt als bei anderen.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Code-Modus des Agenten`},help:{"v1-118t8u5-65":`Agentenspezifische Optionen für den Code-Modus. Ein expliziter Wert für enabled überschreibt die gemeinsamen Modellvorgaben und globalen Aktivierungsvorgaben; eine agentenspezifische codeMode-Überschreibung für das Modell hat Vorrang. Andere Optionen werden mit tools.codeMode zusammengeführt und überschreiben dessen Werte, ohne die Aktivierung zu ändern.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Exec-Zeitlimit des Agenten (Sekunden)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Überschreibung der GitHub CLI-Identität des Agenten`},help:{"v1-mjwdh4-38":`Vollständige Überschreibung der verwalteten GitHub CLI-Identität und des Git-Autors für diesen Agenten. Weglassen, um die Systemidentität zu übernehmen.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`E-Mail-Adresse des Git-Autors des Agenten`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Name des Git-Autors des Agenten`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Art der GitHub-Anmeldedaten des Agenten`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`GitHub-Profilversion des Agenten`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Zulassungsliste für Nachrichtenaktionen des Agenten`},help:{"v1-1g5gov3-67":`Agentenspezifische Zulassungsliste für Nachrichtenaktionen des message-Tools. Für öffentliche Sandbox-Agenten eine minimale Liste wie ["send"] festlegen, damit Lese-, Bearbeitungs-, Lösch-, Reaktions- und andere anbieterspezifische Nachrichtenaktionen ausgeblendet und blockiert bleiben.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Kontextübergreifender Nachrichtenversand des Agenten (anbieterübergreifend)`},help:{"v1-pehesn-49":`Agentenspezifische Einstellung für das anbieterübergreifende Senden. Übernimmt die globale Einstellung (Standard: true). Auf false setzen, um anbieterübergreifende Nachrichten für diesen Agenten zu blockieren.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Kontextübergreifende Agenten-Nachrichten (gleicher Anbieter)`},help:{"v1-s9u09h-4t":`Agentenspezifische Schutzregel für das Senden von Nachrichten an andere Unterhaltungen beim selben Anbieter. Setzen Sie sowohl diese Einstellung als auch allowAcrossProviders auf false, um öffentliche Agenten auf die aktuelle Unterhaltung zu beschränken.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Werkzeugprofil des Agenten`},help:{"v1-1du76ix-57":`Agentenspezifische Überschreibung der Werkzeugprofilauswahl, wenn ein Agent einen anderen grundlegenden Funktionsumfang benötigt. Sparsam einsetzen, damit Richtlinienunterschiede zwischen Agenten bewusst gewählt und überprüfbar bleiben.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Agentenschwarm`},help:{"v1-420ljs-2c":`Agentenspezifische Schwarm-Überschreibung. Die Werte werden mit der übergeordneten Konfiguration tools.swarm zusammengeführt und haben dabei Vorrang.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Tippmodus des Agenten`},help:{"v1-oxir52-2e":`Überschreibt die Standardrichtlinie für den Beginn der Tippanzeige für einen Agenten, ohne andere Agenten zu ändern.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Hilfsmodell des Agenten`},help:{"v1-1v9oskz-2z":`Optionale agentenspezifische Überschreibung des Hilfsmodells für kurze interne Aufgaben. Überschreibt agents.defaults.utilityModel.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Generation der Agentenzuständigkeit`},help:{"v1-m2hp61-8g":`Dauerhafte Generationsmarkierung für die Zuständigkeit in Multi-Agenten-Systemen. "explicit" bedeutet, dass Hintergrundkanäle, Heartbeat, Systemagenten-Konsultationen, Talk, cron und direkte CLI-Operationen einen für die jeweilige Oberfläche zuständigen Agenten ermitteln müssen oder andernfalls sicherheitshalber abgebrochen werden. OpenClaw setzt diese Markierung automatisch beim Erstellen oder Migrieren einer Flotte; bei einem einzelnen Agenten weglassen.`}},approvals:{label:{"v1-1m405m7-9":`Genehmigungen`},help:{"v1-4y3in-5w":`Routing-Einstellungen für die Weiterleitung von Genehmigungsanfragen für exec und Plugins an Chat-Ziele außerhalb der ursprünglichen Sitzung. Lassen Sie diese deaktiviert, sofern Betreiber Genehmigungen nicht ausdrücklich auch außerhalb der Sitzung einsehen müssen.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Weiterleitung von exec-Genehmigungen`},help:{"v1-1r2mozk-5v":`Bündelt die Einstellungen zur Weiterleitung von exec-Genehmigungen, darunter Aktivierung, Routing-Modus, Filter und explizite Ziele. Konfigurieren Sie diese hier, wenn Genehmigungsanfragen operative Kanäle erreichen müssen und nicht nur den ursprünglichen Thread.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Agentenfilter für Genehmigungen`},help:{"v1-xbuhd3-5i":'Optionale Liste zulässiger Agenten-IDs, für die Genehmigungen weitergeleitet werden dürfen, zum Beispiel `["primary", "ops-agent"]`. Begrenzen Sie damit die Reichweite der Weiterleitung und vermeiden Sie Benachrichtigungen in Kanälen für nicht betroffene Agenten.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`exec-Genehmigungen weiterleiten`},help:{"v1-1t0whe8-5s":`Aktiviert die Weiterleitung von exec-Genehmigungsanfragen an konfigurierte Zustellziele (Standard: false). Lassen Sie diese Option in Umgebungen mit geringem Risiko deaktiviert und aktivieren Sie sie nur, wenn die für Genehmigungen zuständigen Personen Anfragen im Kanal sehen müssen.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Modus für die Genehmigungsweiterleitung`},help:{"v1-1dedfo4-69":`Legt fest, wohin Genehmigungsanfragen gesendet werden: "session" verwendet den ursprünglichen Chat, "targets" die konfigurierten Ziele und "both" beide Wege. Verwenden Sie "session" als Grundeinstellung und erweitern Sie diese nur, wenn der operative Arbeitsablauf Redundanz erfordert.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Sitzungsfilter für Genehmigungen`},help:{"v1-smeg8e-5u":'Optionale Filter für Sitzungsschlüssel, die als Teilzeichenfolgen oder reguläre Ausdrücke abgeglichen werden, zum Beispiel `["discord:", "^agent:ops:"]`. Verwenden Sie eng gefasste Muster, damit nur die vorgesehenen Genehmigungskontexte an gemeinsam genutzte Ziele weitergeleitet werden.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Ziele für die Genehmigungsweiterleitung`},help:{"v1-17ah848-5u":`Explizite Zustellziele, die verwendet werden, wenn der Weiterleitungsmodus Ziele einschließt, jeweils mit Angaben zu Kanal und Zieladresse. Beschränken Sie die Ziellisten auf das erforderliche Minimum und prüfen Sie jedes Ziel, bevor Sie eine umfassende Weiterleitung aktivieren.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`Konto-ID des Genehmigungsziels`},help:{"v1-16zopng-5e":`Optionale Kontoauswahl für Kanalkonfigurationen mit mehreren Konten, wenn Genehmigungen über einen bestimmten Kontokontext geleitet werden müssen. Verwenden Sie diese Option nur, wenn für den Zielkanal mehrere Identitäten konfiguriert sind.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Zielkanal für Genehmigungen`},help:{"v1-ji1igl-59":`Kanal-/Anbieter-ID für die Zustellung weitergeleiteter Genehmigungen, etwa discord, slack oder die ID eines Plugin-Kanals. Verwenden Sie nur gültige Kanal-IDs, damit die Zustellung von Genehmigungen nicht aufgrund unbekannter Routen unbemerkt fehlschlägt.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`Thread-ID des Genehmigungsziels`},help:{"v1-1axynw7-59":`Optionaler Ziel-Thread bzw. optionales Zielthema für Kanäle, die die Zustellung weitergeleiteter Genehmigungen in Threads unterstützen. Verwenden Sie diese Option, um den Genehmigungsverkehr auf operative Threads statt auf Hauptkanäle zu beschränken.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Zieladresse für Genehmigungen`},help:{"v1-1ijng7e-5n":`Zielkennung innerhalb des Zielkanals (je nach Anbieter Kanal-ID, Benutzer-ID oder Thread-Ursprung). Prüfen Sie die Bedeutung für den jeweiligen Anbieter, da sich das Zielformat je nach Kanalintegration unterscheidet.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Weiterleitung von Plugin-Genehmigungen`},help:{"v1-1m6pzxv-6b":`Bündelt die Einstellungen zur Weiterleitung von Plugin-Genehmigungen, einschließlich Aktivierung, Routing-Modus, Filtern und expliziten Zielen. Unabhängig von der Weiterleitung von Ausführungsgenehmigungen. Konfigurieren Sie diese Einstellungen, wenn Plugin-Genehmigungsanfragen betriebliche Kanäle erreichen müssen.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Agentenfilter für Plugin-Genehmigungen`},help:{"v1-jb1bra-4b":'Optionale Zulassungsliste mit Agenten-IDs, für die Plugin-Genehmigungen weitergeleitet werden dürfen, zum Beispiel `["primary", "ops-agent"]`. Damit begrenzen Sie die Reichweite der Weiterleitung.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Plugin-Genehmigungen weiterleiten`},help:{"v1-1ntctaf-3v":`Aktiviert die Weiterleitung von Plugin-Genehmigungsanfragen an konfigurierte Zustellziele (Standard: false). Unabhängig von approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Weiterleitungsmodus für Plugin-Genehmigungen`},help:{"v1-1h62vy4-3z":`Legt fest, wohin Plugin-Genehmigungsanfragen gesendet werden: "session" verwendet den ursprünglichen Chat, "targets" die konfigurierten Ziele und "both" sendet über beide Wege.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Sitzungsfilter für Plugin-Genehmigungen`},help:{"v1-1eppxmt-57":'Optionale Filter für Sitzungsschlüssel, die als Teilzeichenfolgen oder Muster im Stil regulärer Ausdrücke abgeglichen werden, zum Beispiel `["discord:", "^agent:ops:"]`. Verwenden Sie eng gefasste Muster, damit nur die vorgesehenen Genehmigungskontexte weitergeleitet werden.'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Weiterleitungsziele für Plugin-Genehmigungen`},help:{"v1-o92qze-3k":`Explizite Zustellungsziele, die verwendet werden, wenn der Weiterleitungsmodus für Plugin-Genehmigungen Ziele einschließt, jeweils mit Kanal- und Zielangaben.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`Konto-ID des Ziels für Plugin-Genehmigungen`},help:{"v1-1wf3lqn-3j":`Optionale Kontoauswahl für Kanalkonfigurationen mit mehreren Konten, wenn Plugin-Genehmigungen über einen bestimmten Kontokontext weitergeleitet werden müssen.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Zielkanal für Plugin-Genehmigungen`},help:{"v1-1mzhzi9-34":`Kanal-/Anbieter-ID für die Zustellung weitergeleiteter Plugin-Genehmigungen, etwa discord, slack oder die ID eines Plugin-Kanals.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`Ziel-Thread-ID für Plugin-Genehmigungen`},help:{"v1-1scaw9c-2v":`Optionaler Ziel-Thread bzw. optionales Zielthema für Kanäle, die die Zustellung weitergeleiteter Plugin-Genehmigungen in Threads unterstützen.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Zieladresse für Plugin-Genehmigungen`},help:{"v1-sh5te1-31":`Zielkennung innerhalb des Zielkanals (je nach Anbieter Kanal-ID, Benutzer-ID oder Ausgangsnachricht des Threads).`}},attachments:{label:{"v1-8925gh-b":`Anhänge`},help:{"v1-1xvgkss-40":`Übergeordnetes Aufbewahrungsverhalten für alle Anbieter und Tools, die Medien dauerhaft speichern. Verwenden Sie ttlHours, wenn allgemein zwischengespeicherte Medien nach einer begrenzten Zeit bereinigt werden sollen.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`Aufbewahrungsdauer für Anhänge (TTL in Stunden)`},help:{"v1-1g90day-9e":`Optionale Aufbewahrungsdauer in Stunden für gespeicherte Medien, die von der allgemeinen mtime-Bereinigung erfasst werden. Lassen Sie diesen Wert ungesetzt, um diese Bereinigung zu deaktivieren, oder verwenden Sie Werte wie 24 (1 Tag) oder 168 (7 Tage), um ältere zwischengespeicherte Medien regelmäßig zu entfernen. Verwaltete ausgehende Medien (im Chat generierte Anhänge) sind ausgenommen und unterliegen einer eigenen Aufbewahrungsregelung, die SQLite und Transkripte berücksichtigt.`}},audio:{label:{"v1-11wczsp-5":`Audio`}},auth:{label:{"v1-5xz433-4":`Authentifizierung`},help:{"v1-1eu3aud-5c":`Stammkonfiguration der Authentifizierungsprofile für Anbieterzugangsdaten mit mehreren Profilen und eine auf Abkühlzeiten basierende Failover-Reihenfolge. Halten Sie Profile minimal und explizit, damit das automatische Failover-Verhalten nachvollziehbar bleibt.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Reihenfolge der Authentifizierungsprofile`},help:{"v1-1x6kknp-1w":`Geordnete IDs der Authentifizierungsprofile pro Anbieter (für automatisches Failover verwendet).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Authentifizierungsprofile`},help:{"v1-kzoqcn-1j":`Benannte Authentifizierungsprofile (Anbieter + Modus + optionale E-Mail-Adresse).`}},bindings:{label:{"v1-1hcih9f-8":`Tastenbelegungen`},help:{"v1-y7hrzb-4i":`Bindungsregeln auf oberster Ebene für das Routing und die dauerhafte Zuordnung von ACP-Konversationen. Verwenden Sie type=route für normales Routing und type=acp für dauerhafte ACP-Harness-Bindungen.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Überschreibungen der ACP-Bindung`},help:{"v1-1t4lisi-44":`Optionale ACP-Überschreibungen pro Bindung für bindings[].type=acp. Diese Ebene überschreibt die Standardwerte von agents.entries.*.runtime.acp für die zugeordnete Konversation.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Backend der ACP-Bindung`},help:{"v1-rsrbkp-2x":`Überschreibung des ACP-Backends für diese Bindung (fällt auf das ACP-Backend der Agentenlaufzeit zurück, danach auf das globale acp.backend).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Arbeitsverzeichnis der ACP-Bindung`},help:{"v1-ngpkj0-1y":`Abweichendes Arbeitsverzeichnis für ACP-Sitzungen, die über diese Bindung erstellt werden.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Bezeichnung der ACP-Bindung`},help:{"v1-azce82-23":`Benutzerfreundliche Bezeichnung für ACP-Status und -Diagnose in dieser gebundenen Konversation.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Modus der ACP-Bindung`},help:{"v1-cgq8xv-1v":`Abweichender ACP-Sitzungsmodus für diese Bindung (persistent oder oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`Agenten-ID der Bindung`},help:{"v1-17ra0cl-4m":`ID des Zielagenten, der den Datenverkehr erhält, wenn die entsprechende Abgleichregel der Bindung erfüllt ist. Verwenden Sie nur gültige, konfigurierte Agenten-IDs, damit das Routing nicht zur Laufzeit fehlschlägt.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Abgleichregel der Bindung`},help:{"v1-sc1w2e-51":`Abgleichregelobjekt, das festlegt, wann eine Bindung gilt, einschließlich Kanal und optionaler Einschränkungen für Konto und Kommunikationspartner. Halten Sie die Regeln eng gefasst, um eine unbeabsichtigte Übernahme durch Agenten über Kontextgrenzen hinweg zu vermeiden.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`Konto-ID der Bindung`},help:{"v1-1d209g7-56":`Optionale Kontoauswahl für Kanalkonfigurationen mit mehreren Konten, damit die Bindung nur für eine Identität gilt. Verwenden Sie diese Einstellung, wenn die Route auf ein Konto beschränkt werden muss, und lassen Sie sie andernfalls ungesetzt.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Kanal der Bindung`},help:{"v1-d22m5-54":"Kanal- oder Anbieterkennung, für die diese Bindung gilt, etwa `telegram`, `discord` oder die Kanal-ID eines Plugins. Verwenden Sie den konfigurierten Kanalschlüssel exakt, damit die Auswertung der Bindung zuverlässig funktioniert."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`Gilden-ID der Bindung`},help:{"v1-jzzfj1-4x":`Optionale Einschränkung auf eine Guild-/Server-ID im Discord-Stil für die Auswertung von Zuordnungen in Bereitstellungen mit mehreren Servern. Verwenden Sie diese, wenn dieselben Peer-Kennungen in verschiedenen Guilds vorkommen können.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Peer-Abgleich der Zuordnung`},help:{"v1-gcjxff-4i":`Optionaler Peer-Abgleich für bestimmte Unterhaltungen anhand von Peer-Typ und Peer-ID. Verwenden Sie diesen, wenn nur eine einzelne Direktunterhaltung, Gruppe oder ein Kanal einem Agenten fest zugeordnet werden soll.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`Peer-ID der Zuordnung`},help:{"v1-86fbh7-4b":`Unterhaltungskennung für den Peer-Abgleich, etwa eine Chat-ID, Kanal-ID oder Gruppen-ID des Anbieters. Geben Sie diese exakt an, damit Übereinstimmungen nicht unbemerkt ausbleiben.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Peer-Typ der Zuordnung`},help:{"v1-uufscp-4x":`Typ der Peer-Unterhaltung: "direct", "group", "channel" oder das ältere "dm" (veralteter Alias für direct). Verwenden Sie für neue Konfigurationen vorzugsweise "direct" und stimmen Sie kind auf die Kanalsemantik ab.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Rollen der Zuordnung`},help:{"v1-6s891m-4k":`Optionale rollenbasierte Filterliste für Anbieter, die Rollen an den Chat-Kontext anhängen. Verwenden Sie diese, um Nachrichten von privilegierten oder betrieblichen Rollen an spezialisierte Agenten weiterzuleiten.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`Team-ID der Zuordnung`},help:{"v1-hh9ps2-48":`Optionale Einschränkung auf eine Team-/Arbeitsbereichs-ID für Anbieter, die Chats unter Teams organisieren. Fügen Sie diese hinzu, wenn Zuordnungen auf einen einzelnen Arbeitsbereichskontext beschränkt werden sollen.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Sitzung der Zuordnung`},help:{"v1-x325l2-4v":`Optionale Überschreibungen der Sitzungseinstellungen für Konversationen, die dieser Bindung entsprechen. Verwenden Sie diese, wenn eine spezifische Route denselben Agenten beibehalten, aber die Sitzungskontinuität anders abgrenzen soll.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Sitzungsgeltungsbereich für Direktnachrichten in der Bindung`},help:{"v1-10sg3xw-4s":`Optionale Überschreibung des Sitzungsgeltungsbereichs für Direktnachrichten in dieser Routenbindung. Behalten Sie beispielsweise global session.dmScope="main" bei und verwenden Sie gleichzeitig "per-account-channel-peer" für ausgewählte Direktkontakte.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Sitzungsgeltungsbereich für Gruppen in der Bindung`},help:{"v1-1ys2u7k-6n":`Optionale Überschreibung des Sitzungsgeltungsbereichs für Gruppen/Kanäle in dieser Routenbindung. "per-group" hält übereinstimmende Räume getrennt und lässt sie unabhängig von dmScope im Hintergrund von der Hauptsitzung des Agenten beobachten; "main" führt ihren Kontext in main zusammen und erfordert keine Beobachtung.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Bindungstyp`},help:{"v1-172mhtk-3o":`Art der Bindung. Verwenden Sie "route" für normales Routing (oder lassen Sie den Wert bei älteren Routeneinträgen weg) und "acp" für dauerhafte ACP-Konversationsbindungen.`}},broadcast:{label:{"v1-awqjh0-j":`Agentengruppen-Threads`},help:{"v1-1tz72sr-6b":`Verwenden Sie Agentengruppen-Threads, um mehrere konfigurierte Agenten in einer eingehenden Konversation auszuführen, jeweils in einer eigenen Sitzung. Einträge mit Kanalpräfix unterstützen eine begrenzte Anzahl von Folgerunden; ältere WhatsApp-Peer-Arrays behalten das Verhalten mit einem einzigen Durchlauf bei.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Teilnehmer und Optionen der Agentengruppe`},help:{"v1-1b63zmt-7d":`Verwenden Sie eine Peer-ID mit Kanalpräfix (zum Beispiel "telegram:-100123"), um ein Array von Agenten-IDs oder ein strikt definiertes Objekt mit agents, mentionGating, maxRounds und maxTurns zu konfigurieren. Einträge mit Kanalpräfix haben Vorrang vor älteren WhatsApp-Peer-Schlüsseln und erlauben höchstens 16 Agenten.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Teilnehmer der Agentengruppe`},help:{"v1-g5o0ky-43":`IDs der teilnehmenden Agenten aus agents.entries (maximal: 16). Jeder Teilnehmer verwendet eine eigene Sitzung für diesen Kanal, dieses Konto, diese Konversation und diesen Thread.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Maximale Rundenanzahl der Agentengruppe`},help:{"v1-i6v4jc-5a":`Maximale Anzahl an Runden pro eingehender Nachricht, einschließlich der ersten Runde (Ganzzahl: 1–4, Standard: 1). In Folgerunden werden Antworten der anderen Teilnehmer in begrenztem Umfang und mit Angabe des jeweiligen Verfassers geteilt. Die Runden enden, sobald alle Teilnehmer aussetzen.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Maximale Anzahl an Teilnehmerzügen der Agentengruppe`},help:{"v1-1kiv8dy-72":`Maximale Anzahl an Teilnehmerzügen pro eingehender Nachricht über alle Runden hinweg (Ganzzahl: 1–32, Standard: agents.length). Plätze werden vor der parallelen Ausführung reserviert; begrenzt werden Agentenzüge, nicht einzelne Nachrichtenblöcke oder Sendevorgänge durch Tools. Budgets werden nach einem Neustart nicht fortgesetzt.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Teilnehmerauswahl der Agentengruppe per Erwähnung`},help:{"v1-uay9zu-5u":`Nur explizit per @ erwähnte Teilnehmer auswählen, wenn es Übereinstimmungen gibt; andernfalls alle Teilnehmer ausführen (Standard: true). Namen ohne @ oder Emojis wählen keine Teilnehmer aus. Kanal-Zulassungslisten und Zugangsregeln gelten weiterhin.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Strategie der Agentengruppe`},help:{"v1-p4k9hu-4q":`Ausführungsreihenfolge der Teilnehmer: "parallel" (Standard) führt Agenten gleichzeitig aus, während "sequential" sie in der konfigurierten Reihenfolge ausführt. Jede Runde wird abgeschlossen, bevor die nächste beginnt.`}},browser:{label:{"v1-13dzmen-7":`Browser`},help:{"v1-5b74wi-5l":`Browser-Laufzeiteinstellungen für lokale oder entfernte CDP-Verbindungen, Profilrouting und das Verhalten von Screenshots/Snapshots. Behalten Sie die Standardwerte bei, sofern Ihr Automatisierungsworkflow keine angepassten Browser-Transporteinstellungen erfordert.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Import von Systemprofilen erlauben`},help:{"v1-1lsvlxw-5w":`Erlaubt macOS-Hosts, Cookies aus einem lokalen Systemprofil eines Browsers der Chrome-Familie in ein verwaltetes OpenClaw-Browserprofil zu importieren. Deaktivieren Sie diese Option, um den Cookie-Import aus Browserprofilen und die zugehörige Zustimmungsabfrage der macOS-Schlüsselbundverwaltung zu verhindern.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Browser-Modus nur zum Verbinden`},help:{"v1-xaw7xm-4s":`Beschränkt den Browser-Modus auf das Verbinden mit bestehenden Instanzen, ohne lokale Browserprozesse zu starten. Verwenden Sie diese Option, wenn alle Browsersitzungen extern von einem entfernten CDP-Anbieter verwaltet werden.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`CDP-URL des Browsers`},help:{"v1-2n72jb-65":`URL des CDP/DevTools-Endpunkts zum Verbinden mit einer extern verwalteten Browserinstanz. Verwenden Sie diese für zentrale Browser-Hosts, Tunnel oder Verbindungen mit bestehenden Sitzungen und beschränken Sie den Zugriff auf die URL auf vertrauenswürdige Netzwerkpfade.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Standardprofil des Browsers`},help:{"v1-a6xo96-52":`Name des Browserprofils, das standardmäßig ausgewählt wird, wenn Aufrufer nicht ausdrücklich ein Profil wählen. Verwenden Sie ein stabiles Profil mit geringen Berechtigungen als Standard, um die versehentliche Nutzung von Zustandsdaten über Kontextgrenzen hinweg zu reduzieren.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Browser aktiviert`},help:{"v1-19qr4oj-56":`Aktiviert die Browser-Anbindung im Gateway, damit Browser-Tools und CDP-gesteuerte Workflows ausgeführt werden können. Deaktivieren Sie diese Option, wenn keine Browser-Automatisierung benötigt wird, um die Angriffsfläche und den Aufwand beim Start zu reduzieren.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Browser-Evaluate aktiviert`},help:{"v1-1oa79mq-59":`Aktiviert browserseitige Evaluate-Hilfsfunktionen zur Skriptauswertung zur Laufzeit, sofern unterstützt. Lassen Sie diese Option deaktiviert, sofern Ihre Workflows keine Evaluate-Funktionen benötigen, die über Snapshots und Navigation hinausgehen.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Pfad zur ausführbaren Browser-Datei`},help:{"v1-1plb4ki-6i":`Expliziter Pfad zur ausführbaren Browser-Datei, wenn die automatische Erkennung für Ihre Host-Umgebung nicht ausreicht. Verwenden Sie einen stabilen absoluten Pfad oder einen mit ~ beginnenden Pfad zu Ihrem Benutzerverzeichnis im Betriebssystem, damit das Startverhalten über Neustarts hinweg deterministisch bleibt.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Relay für Browser-Erweiterungen`},help:{"v1-6ywlwr-4e":`Kompatibilitätseinstellungen für die Authentifizierung am Relay für Chrome-Erweiterungen. Behalten Sie die Übergangsphase für die bisherige Authentifizierung nur bei, solange ältere gekoppelte Erweiterungen oder externe CDP-Clients sie noch benötigen.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Bisherige Browser-Relay-Authentifizierung zulassen`},help:{"v1-pj2e90-63":`Akzeptiert vorübergehend die bisherige Relay-Authentifizierung über Bearer, Basic und Token-Subprotokolle. Standard: true für eine Übergangsphase. Setzen Sie den Wert auf false, sobald alle Erweiterungen und externen CDP-Clients Browser Relay Authentication v2 verwenden.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Headless-Modus des Browsers`},help:{"v1-1rswq8j-5a":`Erzwingt den Browser-Start im Headless-Modus, wenn das lokale Startprogramm Browser-Instanzen startet. Lassen Sie den Headless-Modus in Serverumgebungen aktiviert und deaktivieren Sie ihn nur, wenn die Fehlersuche eine sichtbare Benutzeroberfläche erfordert.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Browsermodus ohne Sandbox`},help:{"v1-slntux-4w":`Deaktiviert die Flags für die Sandbox-Isolation von Chromium in Umgebungen, in denen Sandboxing zur Laufzeit fehlschlägt. Lassen Sie diese Option nach Möglichkeit deaktiviert, da die Schutzmaßnahmen zur Prozessisolation reduziert werden.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Browserprofile`},help:{"v1-1x8lf05-51":`Verbindungszuordnung benannter Browserprofile für die explizite Weiterleitung an CDP-Ports oder URLs mit optionalen Metadaten. Verwenden Sie konsistente Profilnamen und vermeiden Sie sich überschneidende Endpunktdefinitionen.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Browserprofilmodus zum ausschließlichen Verbinden`},help:{"v1-2b5zs0-5a":`Profilspezifische Einstellung, die den lokalen Browserstart überspringt und ausschließlich eine Verbindung zu einem vorhandenen CDP-Endpunkt herstellt. Nützlich, wenn ein Profil extern verwaltet wird, andere jedoch lokal gestartet werden.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`CDP-Port des Browserprofils`},help:{"v1-gx1yiq-49":`Profilspezifischer lokaler CDP-Port für Verbindungen zu Browserinstanzen über einen Port statt über eine URL. Verwenden Sie für jedes Profil einen eindeutigen Port, um Verbindungskonflikte zu vermeiden.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`CDP-URL des Browserprofils`},help:{"v1-x491r0-64":`Profilspezifische CDP/DevTools-Endpunkt-URL für die explizite Browserweiterleitung anhand des Profilnamens. Verwenden Sie diese für entfernte CDP-Hosts, Tunnel oder Profile mit bestehenden Sitzungen, die sich über einen laufenden Chrome DevTools-Endpunkt verbinden sollen.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Treiber des Browserprofils`},help:{"v1-17byyx6-5r":`Browser-Treibermodus pro Profil. Verwenden Sie "openclaw" (oder die ältere Variante "clawd") für CDP-basierte Profile, "existing-session" für die Anbindung über Chrome DevTools MCP oder "extension" für das authentifizierte Chrome-Erweiterungs-Relay.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Pfad zur ausführbaren Datei des Browserprofils`},help:{"v1-29azyv-4w":`Profilspezifischer Pfad zur ausführbaren Browserdatei für lokal gestartete, verwaltete Browserprofile. Überschreibt browser.executablePath und akzeptiert Pfade, die mit ~ für das Benutzerverzeichnis des Betriebssystems beginnen.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Headless-Modus des Browserprofils`},help:{"v1-p4jtgv-4u":`Profilspezifische Überschreibung des Headless-Modus für lokal gestartete Browserinstanzen. Verwenden Sie diese Einstellung, wenn ein Profil im Headless-Modus bleiben soll, ohne browser.headless für alle anderen Profile zu erzwingen.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Chrome-MCP-Argumente des Browserprofils`},help:{"v1-rc45ke-5g":`Zusätzliche profilspezifische Chrome-DevTools-MCP-Argumente für die Anbindung über existing-session, etwa --no-usage-statistics. Hier angegebene Endpunktargumente überschreiben die integrierte automatische Verbindung oder die Auswahl der Browser-URL.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Chrome-MCP-Befehl des Browserprofils`},help:{"v1-1xpty8o-2h":`Profilspezifischer Chrome-DevTools-MCP-Befehl für die Anbindung über existing-session. Standardmäßig wird npx verwendet.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Benutzerdatenverzeichnis des Browserprofils`},help:{"v1-5xvgex-9h":`Profilspezifisches Chromium-Benutzerdatenverzeichnis zum Anbinden an bestehende Sitzungen über Chrome DevTools MCP. Verwenden Sie dies für Brave, Edge, Chromium oder nicht standardmäßige Chrome-Profile, wenn die integrierte automatische Verbindung auf dem ausgewählten Host oder Browser-Knoten das falsche Browser-Datenverzeichnis wählen würde. Pfade, die mit ~ beginnen, werden zum Benutzerverzeichnis des Betriebssystems erweitert.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Standardeinstellungen für Browser-Snapshots`},help:{"v1-v19wdy-4y":`Standardkonfiguration für die Snapshot-Erfassung, die verwendet wird, wenn Aufrufer keine expliziten Snapshot-Optionen angeben. Passen Sie diese für ein einheitliches Erfassungsverhalten über Kanäle und Automatisierungsabläufe hinweg an.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Browser-Snapshot-Modus`},help:{"v1-joeyxp-5c":`Standardmodus für die Snapshot-Extraktion, der steuert, wie Seiteninhalte für die Verarbeitung durch Agenten umgewandelt werden. Wählen Sie den Modus, der Lesbarkeit, Wiedergabetreue und Token-Verbrauch für Ihre Arbeitsabläufe in Einklang bringt.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`SSRF-Richtlinie für den Browser`},help:{"v1-1qbp9im-5e":`Schutzeinstellungen gegen serverseitige Anfragenfälschung für Browser- und Netzwerkabrufe, die interne Hosts erreichen könnten. Behalten Sie im Produktivbetrieb restriktive Standardeinstellungen bei und geben Sie nur ausdrücklich genehmigte Ziele frei.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Zulässige Hostnamen für den Browser`},help:{"v1-1rng39-2k":`Exakte Hostnamen oder IP-Literale, die bei Prüfungen der SSRF-Richtlinie für den Browser zugelassen werden. Halten Sie die Liste so kurz wie möglich.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Lokalen IPv6-Unicast-Adressbereich für den Browser zulassen`},help:{"v1-1glx5cy-2c":`Lokale IPv6-Unicast-Adressen (fc00::/7) für vertrauenswürdige Fake-IP-Proxy-Umgebungen zulassen.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Browser: RFC-2544-Benchmark-Bereich zulassen`},help:{"v1-10ateu3-2i":`IP-Adressen aus dem RFC-2544-Benchmark-Bereich (198.18.0.0/15) für vertrauenswürdige Fake-IP-Proxy-Umgebungen zulassen.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Browser: Gesperrte Hostnamen`},help:{"v1-nug0we-6k":`Hostnamenmuster, die vor der DNS-Auflösung und der Prüfung von Zulassungsregeln gesperrt werden, auch wenn der Zugriff auf private Netzwerke aktiviert ist. Unterstützt exakte Hostnamen und "*.example.com" ausschließlich für Subdomains; fügen Sie "example.com" separat hinzu, um die Stammdomain zu sperren. Leer oder nicht festgelegt werden keine zusätzlichen Sperren angewendet.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Browser: Privates Netzwerk zulassen (gefährlich)`},help:{"v1-17103pi-4m":`Erlaubt Browser-Werkzeugen den Zugriff auf Adressbereiche privater Netzwerke. Standardmäßig deaktiviert, wenn nicht festgelegt; nur für ausdrücklich vertrauenswürdige Ziele in privaten Netzwerken aktivieren.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Browser: Tab-Bereinigung`},help:{"v1-1ctwaad-4y":`Richtlinie zur bestmöglichen Bereinigung von Browser-Tabs, die von Sitzungen des primären Agenten geöffnet wurden. Aktiviert lassen, damit sich bei lang laufenden Gateways keine veralteten Sandbox-Tabs oder Tabs verwalteter Browser ansammeln.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Browser: Tab-Bereinigung aktiviert`},help:{"v1-4sv97p-3u":`Aktiviert die Bereinigung inaktiver, nachverfolgter Browser-Tabs für Sitzungen des primären Agenten. Nur deaktivieren, wenn externe Werkzeuge den Lebenszyklus der Tabs vollständig verwalten.`}},channels:{label:{"v1-1ju93md-8":`Kanäle`},help:{"v1-12yv6ma-5n":`Konfigurationen der Kanalanbieter sowie gemeinsame Standardwerte, die Zugriffsrichtlinien, die Sichtbarkeit von Heartbeats und das Verhalten je Oberfläche steuern. Standardwerte zentral verwalten und nur bei Bedarf pro Anbieter überschreiben.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Kanal-Standardeinstellungen`},help:{"v1-uz6veb-4p":`Standardverhalten für Kanäle, das anbieterübergreifend gilt, wenn keine anbieterspezifischen Einstellungen festgelegt sind. Damit lässt sich eine einheitliche Basisrichtlinie durchsetzen, bevor einzelne Anbieter angepasst werden.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Standardmäßiger Schutz vor Bot-Schleifen`},help:{"v1-1lpznyk-4w":`Standardeinstellungen für den paarweisen Schleifenschutz bei Kanalanbietern, die Schutzmechanismen gegen Bot-zu-Bot-Schleifen unterstützen. Verwenden Sie anbieterspezifische Überschreibungen nur, wenn ein Kanal ein anderes Budget benötigt.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Standardabklingzeit für Bot-Schleifen in Sekunden`},help:{"v1-1yl5ird-2z":`Abklingzeit in Sekunden, die für ein Paar gilt, nachdem es das Schleifenbudget überschritten hat. Der Standardwert für unterstützende Kanäle beträgt 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Standardmäßiger Schutz vor Bot-Schleifen aktiviert`},help:{"v1-3ruik-4r":`Aktiviert den paarweisen Schleifenschutz standardmäßig für unterstützende Kanäle, wenn von Bots verfasste Nachrichten zur Weiterleitung gelangen können. Anbieter können den Schutz weiterhin deaktivieren, wenn Bots ignoriert werden.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Standardanzahl der Bot-Schleifenereignisse pro Zeitfenster`},help:{"v1-1u0mdjc-41":`Maximale Anzahl von Ereignissen, die ein Sender-Empfänger-Paar innerhalb des konfigurierten Zeitfensters austauschen darf, bevor die Unterdrückung beginnt. Der Standardwert für unterstützende Kanäle beträgt 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Standardzeitfenster für Bot-Schleifen in Sekunden`},help:{"v1-12xpmen-2m":`Länge des gleitenden Zeitfensters in Sekunden für paarweise Schleifenbudgets. Der Standardwert für unterstützte Kanäle ist 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Standardmäßige Kontextsichtbarkeit`},help:{"v1-1hze3g1-5o":`Standardmäßige Sichtbarkeit zusätzlicher Kontextinformationen aus abgerufenen Zitaten, Threads und Verläufen: "all" (gesamten Kontext beibehalten), "allowlist" (nur Absender auf der Zulassungsliste) oder "allowlist_quote" (Zulassungsliste + explizite Zitate beibehalten).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Standardmäßige Gruppenrichtlinie`},help:{"v1-ntl9m4-4n":`Standardmäßige Gruppenrichtlinie für alle Kanäle: "open", "disabled" oder "allowlist". Behalten Sie für sicherere Produktionsumgebungen "allowlist" bei, sofern eine breite Gruppenbeteiligung nicht ausdrücklich gewünscht ist.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`Standardmäßige Heartbeat-Sichtbarkeit`},help:{"v1-49bw75-4v":`Standardmäßige Heartbeat-Sichtbarkeitseinstellungen für Statusmeldungen von Anbietern oder Kanälen. Passen Sie diese global an, um störende Meldungen zum fehlerfreien Betrieb zu reduzieren und gleichzeitig Warnungen sichtbar zu halten.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`Heartbeat-Warnungen anzeigen`},help:{"v1-8dk8zx-4g":`Zeigt bei true Heartbeat-Warnungen zu Beeinträchtigungen und Fehlern an, damit Probleme in den Betreiberkanälen umgehend sichtbar werden. Lassen Sie diese Option im Produktionsbetrieb aktiviert, damit fehlerhafte Kanalzustände sichtbar sind.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`Heartbeat-OK-Status anzeigen`},help:{"v1-17tg3mk-4z":`Zeigt bei true Heartbeat-Statuseinträge mit dem Status „Funktionsfähig/OK“ in Kanalstatusausgaben an. In Umgebungen mit vielen Meldungen auf false belassen und nur aktivieren, wenn das Betriebsteam ausdrückliche Bestätigungen der Funktionsfähigkeit benötigt.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`Indikator für Heartbeat verwenden`},help:{"v1-1w12cs2-4m":`Aktiviert, sofern unterstützt, eine kompakte Heartbeat-Darstellung als Indikator statt ausführlichem Statustext. Verwenden Sie den Indikatormodus für dicht bestückte Dashboards mit vielen aktiven Kanälen.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Standardmäßige implizite Erwähnungen`},help:{"v1-4gtdyv-48":`Standardrichtlinie dafür, ob Antworten auf Bot-Nachrichten, zitierte Bot-Nachrichten und Threads mit Bot-Beteiligung Nachrichtenkanäle, die dies unterstützen, auch ohne ausdrückliche Erwähnung aktivieren.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Standardmäßige implizite Erwähnungen durch Bot-Zitate`},help:{"v1-va1u5v-2v":`Zitierte Bot-Nachrichten standardmäßig als implizite Erwähnungen behandeln. Aus Gründen der Abwärtskompatibilität ist der Standardwert true.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Standardmäßige implizite Erwähnungen durch Antworten an den Bot`},help:{"v1-lm44c3-39":`Antworten auf die eigenen Nachrichten des Bots standardmäßig als implizite Erwähnungen behandeln. Aus Gründen der Abwärtskompatibilität ist der Standardwert true.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Standardmäßige implizite Erwähnungen durch Thread-Beteiligung`},help:{"v1-160205h-3o":`Folgenachrichten in Threads, an denen der Bot beteiligt war, standardmäßig als implizite Erwähnungen behandeln. Aus Gründen der Abwärtskompatibilität ist der Standardwert true.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Modellüberschreibungen für Kanäle`},help:{"v1-1b01spx-2p":`Zuordnung Anbieter -> Kanal-ID / ID des Direktnachrichtenkontakts -> Modellüberschreibung (Werte sind Anbieter/Modell oder Aliasse).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Cloud-Worker`},help:{"v1-10carc4-5v":`Optional aktivierbare Cloud-Worker-Profile für temporäre Remote-Umgebungen. Wenn dieser Abschnitt fehlt oder keine Profile enthält, bleibt die Erstellung von Cloud-Workern nicht verfügbar und das bestehende Verhalten des Gateway-/Knotenstatus unverändert.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Cloud-Worker-Desktop (experimentell)`},help:{"v1-vllayc-3n":`Aktiviert die experimentelle Schnittstelle worker.desktop.observe und den Desktop-Bereich der Control UI für Cloud-Worker-Umgebungen mit Desktop-Unterstützung.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Pool vorbereiteter Cloud-Worker`},help:{"v1-rw51o5-6b":`Grenzwerte für vorbereitete Cloud-Worker, die für spätere Sitzungen bereitgehalten werden. Für reservierte Worker fallen bis zum Abschluss der Bereinigung durch den Anbieter Gebühren für laufende Maschinen an. Ihr festgelegter Ablaufzeitpunkt richtet sich nach dem tatsächlichen Projektbedarf und der bestehenden Leerlaufrichtlinie des Anbieters.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Obergrenze für einsatzbereite Cloud-Worker in Reserve`},help:{"v1-1mpd1dt-7u":`Gateway-weite Obergrenze für nicht zugewiesene, vorbereitete Cloud-Worker über alle Projekte und Profile hinweg (Standard: 4). Worker in Vorbereitung und Reserven, deren Bereinigung noch nicht bestätigt wurde, werden auf die Obergrenze angerechnet. Auf 0 setzen, um nicht zugewiesene Reserven abzubauen und das Nachfüllen zu deaktivieren, während die Wiederverwendung von Snapshots und aktive Sitzungen erhalten bleiben.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Cloud-Worker-Profile`},help:{"v1-eii67l-3j":`Benannte Cloud-Worker-Profile. Jedes Profil wählt einen durch ein Plugin registrierten Worker-Anbieter aus und enthält anbieterspezifische Einstellungen.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Cloud-Worker-Profil`},help:{"v1-1v2w7jl-4u":`Ein Cloud-Worker-Profil, das beim Erstellen einer Umgebung anhand seines Namens ausgewählt wird. Verwenden Sie für Anbieterzugangsdaten unterstützte Referenzen, statt vertrauliche Daten direkt in diesen Block einzubetten.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Cloud-Worker-Installationsmethode`},help:{"v1-blrtbf-74":`Worker-Installationsmethode: "bundle" (Standard) überträgt den installierten Build des Gateways mit Inhalts-Hash und unterstützt veröffentlichte Versionen, Entwicklungsversionen und unveröffentlichte Versionen; "npm" installiert exakt die Gateway-Version und ist nur verfügbar, wenn diese Version veröffentlicht ist.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Cloud-Worker-Anbieter`},help:{"v1-1p4s4c1-44":`Von einem Plugin registrierte Worker-Anbieter-ID. Das konfigurierte Plugin muss diese ID bereitstellen, bevor das Gateway Umgebungen anhand des Profils bereitstellen kann.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Zielanzahl einsatzbereiter Cloud-Worker in Reserve`},help:{"v1-1nwve9s-7w":`Zielanzahl nicht zugewiesener, vorbereiteter Worker pro berechtigtem Projekt, das dieses Profil verwendet (Standard: 1), begrenzt durch die Gateway-weite Obergrenze für den Pool vorbereiteter Worker. Auf 0 setzen, um die Reserven dieses Profils zu deaktivieren, während die Wiederverwendung von Snapshots erhalten bleibt. Worker in Vorbereitung und Reserven, deren Bereinigung noch nicht bestätigt wurde, werden auf die Zielanzahl angerechnet.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Anbietereinstellungen für Cloud-Worker`},help:{"v1-mq7u32-4j":`Anbieterspezifische Einstellungen, die vom ausgewählten Plugin validiert werden. Verwenden Sie SecretRef-Objekte für Werte mit Geheimnissen; opake Einstellungen erhalten keine automatische Auflösung von Geheimnissen.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Leerlaufdauer bis zum Anhalten von Cloud-Workern`},help:{"v1-1keuwgh-4w":`Gibt einen inaktiven Cloud-Worker nach dieser Dauer, etwa 45m oder 2h, automatisch frei; bei der nächsten Nachricht wird ein Ersatz bereitgestellt. Minimum: 1m. Nicht festlegen, wenn Worker weiterlaufen sollen.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Projektprofile für Cloud-Worker`},help:{"v1-1kkfrif-46":`Standardprofilnamen für Cloud-Worker, zugeordnet anhand der normalisierten Repository-Identität in Kleinbuchstaben (host/owner/repo). Explizite Profil-IDs für die Zuweisung haben Vorrang.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Projektprofil für Cloud-Worker`},help:{"v1-1mux5u0-30":`Name des Cloud-Worker-Profils, das standardmäßig verwendet wird, wenn der Ursprung des Sitzungs-Worktrees mit dieser Repository-Identität übereinstimmt.`}},commands:{label:{"v1-15x4mpf-8":`Befehle`},help:{"v1-1gi0dr2-5a":`Steuert anbieterübergreifend die Verfügbarkeit von Chatbefehlen, Zugriffsbeschränkungen auf Eigentümer und den Zugriff auf Befehle mit erhöhten Rechten. Behalten Sie die Standardwerte bei, sofern Sie keine strengeren Kontrollen für Betreiber oder eine breitere Verfügbarkeit von Befehlen benötigen.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Zugriffsregeln für Befehle mit erhöhten Rechten`},help:{"v1-7azkw-5g":`Definiert Zulassungsregeln für Befehle mit erhöhten Rechten nach Kanal und Absender für Befehlsschnittstellen auf Eigentümerebene. Verwenden Sie eng eingegrenzte, anbieterspezifische Identitäten, damit privilegierte Befehle nicht einem breiten Chat-Publikum zugänglich sind.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Bash-Chat-Befehl erlauben`},help:{"v1-83ah7w-36":"Erlaubt dem Bash-Chat-Befehl (`!`; Alias `/bash`), Shell-Befehle auf dem Host auszuführen (Standard: false; erfordert tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Bash-Vordergrunddauer (ms)`},help:{"v1-1o0o4dw-2c":`Wie lange Bash wartet, bevor es in den Hintergrund wechselt (Standard: 2000; bei 0 erfolgt der Wechsel sofort).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`/config erlauben`},help:{"v1-151bb7c-21":`Erlaubt dem Chat-Befehl /config, die Konfiguration auf dem Datenträger zu lesen und zu schreiben (Standard: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`/debug erlauben`},help:{"v1-y1lc3j-1y":`Erlaubt den Chat-Befehl /debug für Überschreibungen, die nur zur Laufzeit gelten (Standard: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`/mcp erlauben`},help:{"v1-1rtwcgd-2o":`Erlaubt dem Chat-Befehl /mcp, die MCP-Serverkonfiguration von OpenClaw unter mcp.servers zu verwalten (Standard: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Native Befehle`},help:{"v1-dighr2-5n":`Registriert native Slash- und Menübefehle bei Kanälen, die die Befehlsregistrierung unterstützen (Discord, Slack, Telegram). Lassen Sie diese Option zur besseren Auffindbarkeit aktiviert, sofern Sie nicht bewusst rein textbasierte Befehlsabläufe verwenden.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Native Skill-Befehle`},help:{"v1-19gtqci-5h":`Registriert native Skill-Befehle, damit Benutzer Skills direkt über die Befehlsmenüs der Anbieter aufrufen können, sofern dies unterstützt wird. Stimmen Sie diese Einstellung mit Ihrer Skill-Richtlinie ab, damit die verfügbaren Befehle den Erwartungen der Betreiber entsprechen.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Befehlsinhaber`},help:{"v1-1di38gv-3y":`Explizite Zulassungsliste für Inhaber bei Befehlen, die Inhabern vorbehalten sind. Verwenden Sie kanalspezifische IDs (optional mit einem Präfix wie "whatsapp:+15551234567"). '*' wird ignoriert.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`/plugins erlauben`},help:{"v1-akwy9y-33":`Erlaubt den Chatbefehl /plugins, um erkannte Plugins aufzulisten und sie in der Konfiguration zu aktivieren oder zu deaktivieren (Standard: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Neustart erlauben`},help:{"v1-m32fv2-27":`/restart, /update und externe Neustart-Anfragen über SIGUSR2 zulassen (Standard: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Textbefehle`},help:{"v1-1utu76s-5j":`Aktiviert die Erkennung von Textbefehlen in Chateingaben zusätzlich zu nativen Befehlsschnittstellen, sofern verfügbar. Lassen Sie diese Option aktiviert, um die Kompatibilität mit Kanälen zu gewährleisten, die keine native Befehlsregistrierung unterstützen.`}},cron:{label:{"v1-1qlte4b-b":`Automatisierungen`},help:{"v1-4md8ic-5u":`Globale Zeitplanereinstellungen für gespeicherte Automatisierungen, parallele Ausführungen, alternative Zustellung und die Aufbewahrung von Ausführungssitzungen. Behalten Sie die Standardeinstellungen bei, sofern Sie nicht das Automatisierungsvolumen skalieren oder externe Webhook-Empfänger integrieren.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Automatisierungen aktiviert`},help:{"v1-y8otx6-5i":`Aktiviert die Ausführung von Automatisierungen für gespeicherte Zeitpläne, die vom Gateway verwaltet werden. Lassen Sie diese Option für normale Erinnerungs- und Automatisierungsabläufe aktiviert. Deaktivieren Sie sie nur, um alle Automatisierungen anzuhalten, ohne Aufträge zu löschen.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Aufbewahrung von Automatisierungssitzungen`},help:{"v1-4wagu6-7e":"Legt fest, wie lange abgeschlossene Automatisierungssitzungen vor der Bereinigung aufbewahrt werden (`24h`, `7d`, `1h30m` oder `false`, um die Bereinigung zu deaktivieren; eine Dauer von null wie `0h` deaktiviert sie ebenfalls; Standard: `24h`). Verwenden Sie eine kürzere Aufbewahrungsdauer, um den Speicherzuwachs bei häufigen Ausführungen zu reduzieren."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Verpasste wiederkehrende Automatisierungen überspringen`},help:{"v1-w9wfmo-66":`Überspringt beim Start von Gateway verpasste wiederkehrende cron/every-Termine und plant stattdessen deren nächste zukünftige Ausführung, anstatt sie nachzuholen. Standard: false. Aktivieren Sie diese Option, um veraltete Erinnerungen nach Ausfallzeiten zu vermeiden; einmalige at-Aufträge werden weiterhin nachgeholt.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`SSRF-Richtlinie für Automatisierungs-Webhooks`},help:{"v1-1xlfqnu-5h":`SSRF-Richtlinie, die auf jeden ausgehenden Automatisierungs-Webhook angewendet wird. Private, Loopback-, Link-Local- und interne Ziele bleiben blockiert, sofern diese Richtlinie sie nicht ausdrücklich zulässt. Lassen Sie diese Einstellung ungesetzt, um strenge Zustellungsregeln beizubehalten.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Zulässige Hostnamen für Automatisierungs-Webhooks`},help:{"v1-1i94hyz-3n":`Exakte Hostnamen oder IP-Literale, die für die Zustellung von Automatisierungs-Webhooks zulässig sind, einschließlich ansonsten blockierter Ziele. Halten Sie die Liste möglichst klein.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`IPv6-Unique-Local-Bereich für Automatisierungs-Webhooks zulassen`},help:{"v1-rke0oj-3b":`Erlaubt Automatisierungs-Webhooks an IPv6-Unique-Local-Adressen (fc00::/7). Verwenden Sie diese Option nur in vertrauenswürdigen Fake-IP-Proxy-Umgebungen.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`RFC-2544-Benchmark-Bereich für Automatisierungs-Webhooks zulassen`},help:{"v1-x1usg4-3h":`Erlaubt Automatisierungs-Webhooks an IP-Adressen im Benchmark-Bereich gemäß RFC 2544 (198.18.0.0/15). Nur mit vertrauenswürdigen Fake-IP-Proxy-Umgebungen verwenden.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Blockierte Hostnamen für Automatisierungs-Webhooks`},help:{"v1-16cv1ic-6a":`Hostnamenmuster, die bei der Zustellung von Automatisierungs-Webhooks vor der DNS-Auflösung und der Prüfung von Zulassungsregeln abgelehnt werden. Unterstützt exakte Hostnamen und "*.example.com" nur für Subdomains; fügen Sie "example.com" separat hinzu, um die Stammdomain zu blockieren. Wenn leer oder nicht festgelegt, werden keine zusätzlichen Sperren angewendet.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Privates Netzwerk für Automatisierungs-Webhooks erlauben (gefährlich)`},help:{"v1-1n9710c-3t":`Erlaubt Automatisierungs-Webhooks an Ziele in privaten und internen Netzwerken. Deaktiviert lassen, sofern nicht alle konfigurierten Webhook-Ziele vertrauenswürdig sind.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Bearer-Token für Automatisierungs-Webhooks`},help:{"v1-1l90hxg-5l":`Bearer-Token, das im Webhook-Modus an POST-Anfragen zur Zustellung von Automatisierungs-Webhooks angehängt wird. Verwenden Sie vorzugsweise die Ersetzung über Secrets oder Umgebungsvariablen und wechseln Sie dieses Token regelmäßig, wenn gemeinsam genutzte Webhook-Endpunkte über das Internet erreichbar sind.`}},desktop:{label:{"v1-rs698z-7":`Desktop`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Lokaler Desktop`},help:{"v1-99weio-30":`Desktop-Beobachtung für gekoppelte Knoten oder die experimentelle Gateway-Host-Quelle auf Basis eines lokalen VNC-Servers.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Desktop-Freigabe`},help:{"v1-m9lbcj-83":`Aktiviert die Desktop-Quelle dieses Rechners. Bei gekoppelten macOS-, Windows- und Linux-Knoten ist sie standardmäßig aktiviert; eine explizite Freigabeeinstellung in der Desktop-App hat Vorrang. Die Labs-Quelle des Gateway-Hosts ist standardmäßig deaktiviert und übernimmt Änderungen sofort. Starten Sie einen gekoppelten Knoten neu, nachdem Sie dessen Desktop-Konfiguration geändert haben.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Verwalteter Desktop des Linux-Hosts`},help:{"v1-1r7n22m-49":`Startet und überwacht unter Linux einen monitorlosen TigerVNC/XFCE-Desktop, der nur über Loopback erreichbar ist. Ein explizit angegebener Port oder ein vorhandener VNC-Server am Standardport hat weiterhin Vorrang.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Lokale VNC-Passwortdatei`},help:{"v1-1m5lsox-37":`Absoluter Pfad zur VNC-Passwortdatei. Unter macOS weglassen, um beim Öffnen des Desktop-Viewers die Zugangsdaten des Kontos einzugeben.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Lokaler VNC-Port`},help:{"v1-1ku4w9b-2b":`Loopback-RFB-Port eines bereits laufenden VNC-Servers auf diesem Rechner (Standard: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Diagnose`},help:{"v1-1d5rnym-5p":`Diagnoseeinstellungen für gezielte Ablaufverfolgung, Telemetrieexport und Cache-Prüfung bei der Fehlerbehebung. Beschränken Sie die Basisdiagnose im Produktivbetrieb auf ein Minimum und aktivieren Sie detailliertere Signale nur zur Untersuchung von Problemen.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Cache-Ablaufverfolgung`},help:{"v1-10523zm-5b":`Protokollierungseinstellungen für die Cache-Ablaufverfolgung zur Beobachtung von Cache-Entscheidungen und Nutzdatenkontext bei eingebetteten Ausführungen. Aktivieren Sie diese vorübergehend zur Fehlerbehebung und deaktivieren Sie sie anschließend, um den Umfang sensibler Protokolldaten zu reduzieren.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Cache-Ablaufverfolgung aktiviert`},help:{"v1-2c1umi-1v":`Momentaufnahmen der Cache-Ablaufverfolgung für eingebettete Agentenausführungen protokollieren (Standard: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Diagnose aktiviert`},help:{"v1-a46pxt-4h":`Hauptschalter für die Ausgabe der Diagnoseinstrumentierung in Protokollen und Telemetrie-Anbindungspfaden. Standardmäßig aktiviert; nur in stark eingeschränkten Umgebungen auf false setzen.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Diagnose-Flags`},help:{"v1-x4w5ok-33":`Gezielte Diagnoseprotokolle per Flag aktivieren (z. B. ["telegram.http"]). Unterstützt Platzhalter wie "telegram.*" oder "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`OpenTelemetry-Exporteinstellungen für Traces, Metriken und Protokolle, die von Gateway-Komponenten ausgegeben werden. Zur Integration mit zentralisierten Observability-Backends und Pipelines für verteiltes Tracing verwenden.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`OpenTelemetry-Inhaltserfassung`},help:{"v1-19tid4t-2t":`Optionale Erfassung von OTEL-Span-Inhalten. Standardmäßig deaktiviert; true erfasst Nachrichteninhalte außer Systemnachrichten sowie Tool-Inhalte.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry aktiviert`},help:{"v1-193bm0-5b":`Aktiviert die OpenTelemetry-Exportpipeline für Traces, Metriken und Protokolle anhand der konfigurierten Endpunkt- und Protokolleinstellungen. Deaktiviert lassen, solange Collector-Endpunkt und Authentifizierung nicht vollständig konfiguriert sind.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`OpenTelemetry-Endpunkt`},help:{"v1-4rrd1x-4y":`URL des Collector-Endpunkts für die OpenTelemetry-Exportübertragung, einschließlich Schema und Port. Einen erreichbaren, vertrauenswürdigen Collector-Endpunkt verwenden und nach der Einführung auf Fehler bei der Datenaufnahme achten.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`OpenTelemetry-Übertragungsintervall (ms)`},help:{"v1-1moqogc-53":`Intervall in Millisekunden für die regelmäßige Übertragung gepufferter Telemetriedaten an den Collector. Erhöhen, um die Exporthäufigkeit zu reduzieren, oder verringern, um bei der aktiven Störungsbehebung schneller Einblick zu erhalten.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`OpenTelemetry-Header`},help:{"v1-s26t2a-52":`Zusätzliche HTTP-Anfrageheader, die mit OpenTelemetry-Exportanfragen gesendet werden und häufig zur Mandantenauthentifizierung oder zum Routing dienen. Hinterlegen Sie Geheimnisse in Werten aus Umgebungsvariablen und vermeiden Sie unnötig viele Header.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`OpenTelemetry-Logs aktiviert`},help:{"v1-12wo6rv-4k":`Aktiviert den Export von Logsignalen über OpenTelemetry zusätzlich zu lokalen Protokollzielen. Verwenden Sie diese Option, wenn eine zentrale Logkorrelation über Dienste und Agenten hinweg erforderlich ist.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`OpenTelemetry-Log-Endpunkt`},help:{"v1-1vgzldu-40":`Signalspezifischer OTLP/HTTP-Endpunkt für Logs. Wenn festgelegt, überschreibt dieser diagnostics.otel.endpoint und OTEL_EXPORTER_OTLP_ENDPOINT nur für den Logexport.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`OpenTelemetry-Log-Exporter`},help:{"v1-9bzywd-5q":`Logexportziel für diagnostics.otel.logs. Verwenden Sie "otlp" für den konfigurierten OTLP-Log-Endpunkt, "stdout" für einen JSON-Datensatz pro stdout-Zeile in Container-Log-Pipelines und "both", wenn beide Ziele benötigt werden.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`OpenTelemetry-Metriknamenspräfix`},help:{"v1-1epdpi9-b2":`Ersetzt das Standardpräfix "openclaw." bei OpenClaw-eigenen Metriknamen. Verwenden Sie eine leere Zeichenfolge, um das Präfix zu entfernen, oder bis zu 128 ASCII-Buchstaben, Ziffern, Unterstriche, Punkte, Bindestriche und Schrägstriche, beginnend mit einem Buchstaben. Fügen Sie benötigte Trennzeichen hinzu, zum Beispiel "acme."; standardmäßige gen_ai.*-Metriknamen bleiben unverändert. Wenn Sie diesen Wert ändern, müssen Dashboards und Warnmeldungen aktualisiert werden, die die alten Namen abfragen.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`OpenTelemetry-Metriken aktiviert`},help:{"v1-13r4cf4-4x":`Aktiviert den Export von Metriksignalen an den konfigurierten OpenTelemetry-Collector-Endpunkt. Für Dashboards zum Laufzeitzustand aktiviert lassen und nur deaktivieren, wenn das Metrikvolumen minimiert werden muss.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`OpenTelemetry-Metrikendpunkt`},help:{"v1-qlfh7x-47":`Signalspezifischer OTLP/HTTP-Metrikendpunkt. Wenn festgelegt, überschreibt dieser diagnostics.otel.endpoint und OTEL_EXPORTER_OTLP_ENDPOINT ausschließlich für den Metrikexport.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`OpenTelemetry-Protokoll`},help:{"v1-17ine8s-5e":`OTel-Transportprotokoll für den Telemetrieexport. Nur "http/protobuf" wird akzeptiert. Führen Sie "openclaw doctor --fix" aus, um einen gespeicherten veralteten Wert "grpc" zu korrigieren oder quellenspezifische Hinweise zur manuellen Bearbeitung zu erhalten.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`OpenTelemetry-Trace-Stichprobenrate`},help:{"v1-brcwep-50":`Trace-Stichprobenrate (0–1), die steuert, welcher Anteil der Trace-Daten an Observability-Backends exportiert wird. Niedrigere Raten reduzieren Zusatzaufwand und Kosten, während höhere Raten die Detailgenauigkeit bei der Fehlersuche verbessern.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`OpenTelemetry-Dienstname`},help:{"v1-1hpiqon-5d":`Dienstname, der in Telemetrie-Ressourcenattributen gemeldet wird, um diese Gateway-Instanz in Observability-Backends zu identifizieren. Verwenden Sie stabile Namen, damit Dashboards und Warnmeldungen über Bereitstellungen hinweg konsistent bleiben.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`OpenTelemetry-Traces aktiviert`},help:{"v1-j7zrrp-4s":`Aktiviert den Export von Trace-Signalen an den konfigurierten OpenTelemetry-Collector-Endpunkt. Aktiviert lassen, wenn Tracing zur Latenzanalyse oder Fehlersuche benötigt wird, und deaktivieren, wenn Sie nur Metriken und Protokolle wünschen.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`OpenTelemetry-Endpunkt für Traces`},help:{"v1-8yw5p1-43":`Signalspezifischer OTLP/HTTP-Endpunkt für Traces. Wenn festgelegt, überschreibt dieser diagnostics.otel.endpoint und OTEL_EXPORTER_OTLP_ENDPOINT nur für den Export von Traces.`}},discovery:{label:{"v1-l2sr05-9":`Erkennung`},help:{"v1-1sqleij-4w":`Einstellungen zur Diensterkennung für lokale mDNS-Ankündigungen und optionale standortübergreifende Präsenzsignalisierung. Beschränken Sie die Erkennung auf die vorgesehenen Netzwerke, um die unbeabsichtigte Offenlegung von Dienstmetadaten zu vermeiden.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`mDNS-Erkennung`},help:{"v1-vtbyyq-4w":`Konfigurationsgruppe für die mDNS-Erkennung zur Ankündigung im lokalen Netzwerk und zur Anpassung des Erkennungsverhaltens. Behalten Sie für die übliche LAN-Erkennung den minimalen Modus bei, sofern keine zusätzlichen Metadaten erforderlich sind.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`mDNS-Erkennungsmodus`},help:{"v1-1p28pd5-2m":`mDNS-Broadcast-Modus ("minimal" ist der Standard, "full" enthält cliPath/sshPort, "off" deaktiviert mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Standortübergreifende Erkennung`},help:{"v1-1akkqjm-53":`Konfigurationsgruppe für die standortübergreifende Erkennung, um Erkennungssignale über das lokale Netzwerksegment hinaus bereitzustellen. Aktivieren Sie diese nur in Bereitstellungen, die die Gateway-Präsenz gezielt standortübergreifend zusammenführen.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Domäne für standortübergreifende Erkennung`},help:{"v1-rxrygo-4m":`Optionale Unicast-DNS-SD-Domäne für die standortübergreifende Erkennung, etwa openclaw.internal. Verwenden Sie diese, wenn Sie die Gateway-Erkennung gezielt über den lokalen mDNS-Bereich hinaus veröffentlichen.`}},env:{label:{"v1-1zc80q-b":`Umgebung`},help:{"v1-1ao5po6-55":`Einstellungen zum Importieren und Überschreiben von Umgebungsvariablen, die dem Gateway-Prozess Laufzeitvariablen bereitstellen. In diesem Abschnitt steuern Sie das Laden von Shell-Umgebungsvariablen und das explizite Einfügen von Variablen.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Import der Shell-Umgebung`},help:{"v1-1gw487t-4y":`Einstellungen zum Importieren von Umgebungsvariablen aus Ihrer Login-Shell beim Start. Lassen Sie diese Funktion aktiviert, wenn Sie auf im Profil definierte Geheimnisse oder PATH-Anpassungen angewiesen sind.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Import der Shell-Umgebung aktiviert`},help:{"v1-5tiuup-5u":`Aktiviert das Laden von Umgebungsvariablen aus dem Shell-Profil des Benutzers während der Startinitialisierung. Lassen Sie diese Funktion auf Entwicklungsrechnern aktiviert oder deaktivieren Sie sie in abgeschotteten Dienstumgebungen mit expliziter Verwaltung der Umgebungsvariablen.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Zeitlimit für den Import der Shell-Umgebung (ms)`},help:{"v1-nsk2yf-5c":`Maximal zulässige Zeit in Millisekunden für die Ermittlung der Shell-Umgebung, bevor das Fallback-Verhalten greift. Verwenden Sie kürzere Zeitlimits für einen schnelleren Start oder erhöhen Sie das Limit bei aufwendiger Shell-Initialisierung.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Überschreibungen für Umgebungsvariablen`},help:{"v1-yxc3z7-5n":`Explizite Schlüssel-Wert-Überschreibungen für Umgebungsvariablen, die zur Laufzeit in die Prozessumgebung von OpenClaw übernommen werden. Verwenden Sie diese für eine deterministische Konfiguration der Umgebungsvariablen, statt sich ausschließlich auf Nebeneffekte des Shell-Profils zu verlassen.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Gateway-Laufzeiteinstellungen für Bindungsmodus, Authentifizierung, Control UI, Remote-Transport und Betriebssicherheit. Behalten Sie restriktive Standardwerte bei, sofern Sie das Gateway nicht bewusst über vertrauenswürdige lokale Schnittstellen hinaus zugänglich machen.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Gateway: x-real-ip-Fallback zulassen`},help:{"v1-1wr3qmw-4c":`Aktiviert den Fallback auf x-real-ip, wenn x-forwarded-for in Proxy-Szenarien fehlt. Lassen Sie diese Funktion deaktiviert, sofern Ihr Ingress-Stack dieses Kompatibilitätsverhalten nicht erfordert.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Gateway-Authentifizierung`},help:{"v1-70b6ni-50":`Authentifizierungsrichtlinie für den HTTP-/WebSocket-Zugriff auf das Gateway, einschließlich Modus, Anmeldedaten, Verhalten bei vertrauenswürdigen Proxys und Ratenbegrenzung. Lassen Sie die Authentifizierung bei jeder Bereitstellung aktiviert, die nicht auf Loopback beschränkt ist.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Tailscale-Identität zur Gateway-Authentifizierung zulassen`},help:{"v1-vqtmgw-53":`Ermöglicht bei entsprechender Konfiguration, dass vertrauenswürdige Tailscale-Identitätsverfahren die Authentifizierungsprüfungen des Gateways erfüllen. Verwenden Sie dies nur, wenn Ihre Tailnet-Identitäten gut abgesichert sind und die Arbeitsabläufe Ihrer Betreiber davon abhängen.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Identitätsbasierte Berechtigungszuweisungen für das Gateway`},help:{"v1-1h0zxy7-5n":`Ordnet verifizierten Identitäten von vertrauenswürdigen Proxys oder Tailscale Betreiberberechtigungen zu, die nur für die jeweilige Verbindung gelten. Bei E-Mail-Schlüsseln wird die Groß-/Kleinschreibung ignoriert; die zugewiesenen Berechtigungen ergänzen die Geräteberechtigungen, bevor die Berechtigungsobergrenze der Verbindung angewendet wird.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Gateway-Authentifizierungsmodus`},help:{"v1-j8rodq-9t":`Gateway-Authentifizierungsmodus: "none", "token", "password" oder "trusted-proxy", abhängig von Ihrer Edge-Architektur. Der Token-/Passwortmodus wählt das konfigurierte Geheimnis (gateway.auth.token oder gateway.auth.password); Clients können es in einem der beiden Authentifizierungsfelder beim Verbindungsaufbau senden. Verwenden Sie Token/Passwort bei direkter Erreichbarkeit und trusted-proxy nur hinter gehärteten, identitätsbewussten Proxys.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Gateway-Passwort`},help:{"v1-1ndt0u2-4g":`Gemeinsames Geheimnis, das durch gateway.auth.mode=password ausgewählt wird. Clients können es entweder in auth.token oder auth.password senden. Der Passwortmodus ist für Tailscale Funnel erforderlich.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Ratenbegrenzung für die Gateway-Authentifizierung`},help:{"v1-1kstr42-54":`Einstellungen zur Begrenzung von Anmelde- und Authentifizierungsversuchen, um das Risiko von Brute-Force-Angriffen auf Zugangsdaten am Gateway zu verringern. In öffentlich zugänglichen Umgebungen aktiviert lassen und die Schwellenwerte an das übliche Datenverkehrsaufkommen anpassen.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Gateway-Token`},help:{"v1-16i7cxs-5q":`Gemeinsames Geheimnis, das durch gateway.auth.mode=token ausgewählt wird, den Standard bei der lokalen Ersteinrichtung. Clients können es entweder in auth.token oder auth.password senden. Bindungen an Nicht-Loopback-Adressen erfordern einen aktivierten Authentifizierungsmodus.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Gateway-Authentifizierung über vertrauenswürdigen Proxy`},help:{"v1-12fsi5d-58":`Zuordnung von Authentifizierungsheadern bei vertrauenswürdigen Proxys für vorgelagerte Identitätsanbieter, die Benutzer-Claims einfügen. Nur mit bekannten Proxy-CIDRs und strikten Header-Zulassungslisten verwenden, um gefälschte Identitätsheader zu verhindern.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`GitHub-Identität über Cloudflare Access OIDC`},help:{"v1-1puth4k-6t":`Optionale verifizierte GitHub-Identität von einem ausgewählten Cloudflare Access OIDC-Anbieter. Erfordert die standardmäßigen Access-Header für E-Mail und Assertion. Bei fehlenden Claims bleiben die Profile auf E-Mail beschränkt; vorhandene Profilrollen und Einstellungen zur Co-Autorenschaft bleiben erhalten.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Claim für die GitHub-Konto-ID`},help:{"v1-pcaaw7-57":`Exakter weitergeleiteter OIDC-Claim, dessen Wert eine verifizierte GitHub-Konto-ID als Zeichenfolge einer positiven Dezimalzahl ist. Konfigurieren Sie Access so, dass dieser in oidc_fields weitergeleitet wird; verwenden Sie niemals einen nicht verifizierten, vom Benutzer bearbeitbaren Claim.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Cloudflare Access-Aussteller`},help:{"v1-gykv03-56":`Exakter HTTPS-Origin des vertrauenswürdigen Cloudflare Access-Teams, z. B. https://example.cloudflareaccess.com, ohne abschließenden Schrägstrich. Claims anderer Aussteller liefern keine GitHub-Identität.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`Cloudflare Access OIDC-Anbieter-ID`},help:{"v1-kbyo5w-44":`Exakte Access-Identitätsanbieter-ID für die vertrauenswürdige OIDC-Integration. Ein Anzeigename des Anbieters oder ein übereinstimmender Claim-Name allein begründet kein Vertrauen.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Automatische Gerätefreigabe über vertrauenswürdigen Proxy`},help:{"v1-uh32ha-6z":`Optionale Richtlinie zur automatischen Freigabe neuer Bediengeräte mit Browser- oder nativer Benutzeroberfläche sowie von Berechtigungserweiterungen für denselben Schlüssel nach der Authentifizierung über einen vertrauenswürdigen Proxy. Gewährte Berechtigungen werden durch deviceAutoApprove.scopes und, sofern vorhanden, den Header x-openclaw-scopes des Proxys begrenzt.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Automatische Gerätefreigabe über vertrauenswürdigen Proxy aktiviert`},help:{"v1-1nntwls-78":`Gibt neue Bediengeräte mit Browser- oder nativer Benutzeroberfläche sowie Berechtigungserweiterungen für denselben Schlüssel automatisch frei, nachdem der Reverse-Proxy einen zugelassenen Benutzer authentifiziert hat. Standard: false. Nur aktivieren, wenn die Identitätsabsicherung durch den Proxy stark genug ist, um die manuelle Gerätekopplung zu ersetzen.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Berechtigungsbereiche für die automatische Gerätegenehmigung über vertrauenswürdige Proxys`},help:{"v1-raeila-g3":`Maximale Berechtigungsbereiche für automatisch genehmigte Operator-Geräte. Standardmäßig operator.read, operator.write, operator.approvals und operator.questions. Angeforderte Berechtigungsbereiche werden auf diese Liste begrenzt; Anfragen ohne Berechtigungsbereiche erhalten diese Liste. Wenn nicht festgelegt, fügt die automatische Genehmigung für ältere UI-Clients auch operator.questions hinzu; eine explizite Liste wird niemals erweitert. Wenn operator.admin explizit aufgeführt wird, kann jeder über einen Proxy authentifizierte Benutzer automatisch vollständige Administratorrechte genehmigen lassen. Anfragen ohne Berechtigungsbereiche erhalten dann ebenfalls automatisch vollständige Administratorrechte. Dies löst außerdem einen kritischen Befund bei der Sicherheitsprüfung sowie eine Warnung beim Start des Gateway aus.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Gateway-Bindungsmodus`},help:{"v1-1unqude-4y":`Netzwerk-Bindungsprofil: "auto", "lan", "loopback", "custom" oder "tailnet", um die Erreichbarkeit über Schnittstellen zu steuern. Behalten Sie "loopback" für den rein lokalen Betrieb bei; "auto" kann alle Schnittstellen zugänglich machen.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`CLI-Agenten`},help:{"v1-1qqo8m2-5a":`Erkennung externer CLI-Sitzungsengines in der Control UI, die über den Sitzungskatalog des Gateway bereitgestellt werden. Standardmäßig aktiviert; deaktivieren Sie diese Option, um zu verhindern, dass diese Engines über die Modellauswahl für neue Sitzungen gestartet werden.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`CLI-Agenten aktiviert`},help:{"v1-ufu7fx-8p":`Zeigt bei true katalogbasierte CLI-Agenten in der Modellauswahl für neue Sitzungen in der Control UI an (Standard: true). Setzen Sie den Wert auf false, um CLI-Agenten und die Erstellung nativer CLI-Sitzungen zu deaktivieren. Es werden nur Kataloge aufgeführt, die Unterstützung für die Sitzungserstellung melden. Die Auswahl bleibt ausgeblendet, wenn das Gateway keine Unterstützung für Sitzungskataloge meldet.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Hosting-Einstellungen für die Control UI, einschließlich Aktivierung, Pfadkonfiguration und Absicherung von Browser-Origins und Authentifizierung. Beschränken Sie die Erreichbarkeit der UI auf das Nötigste und richten Sie vor einer Bereitstellung im Internet starke Authentifizierungskontrollen ein.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Zulässige Origins für die Control UI`},help:{"v1-1stgitk-9i":`Zulässige Browser-Origins für WebSocket-Verbindungen der Control UI und von WebChat (nur vollständige Origins, z. B. https://control.example.com). Erforderlich für Bereitstellungen der Control UI außerhalb der Loopback-Schnittstelle, sofern der gefährliche Host-Header-Fallback nicht ausdrücklich aktiviert ist. Die Einstellung ["*"] erlaubt jede Browser-Origin und sollte außerhalb streng kontrollierter lokaler Tests vermieden werden.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Externe Einbettungs-URLs für die Control UI zulassen`},help:{"v1-obwpfg-6s":`GEFÄHRLICHE Option, die gehosteten Einbettungen das Laden absoluter externer http(s)-URLs erlaubt. Lassen Sie diese Option deaktiviert, es sei denn, Ihre Control UI bettet gezielt vertrauenswürdige Seiten von Drittanbietern ein; gehostete Dokumente unter /__openclaw__/canvas und /__openclaw__/a2ui benötigen sie nicht.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Link-Favicons automatisch abrufen`},help:{"v1-bn9u34-ag":`Favicons für Links und Social-Media-Vorschauen für Browser-Tabs über den Gateway abrufen (standardmäßig aktiviert). Karten für Browser-Tabs laden öffentliche Seitenmetadaten und darin angegebene Bilder ohne Browser-Cookies oder Zugangsdaten für Websites. Alle Anfragen unterliegen strengen SSRF-Prüfungen und einer ressourcenbegrenzten HTML- und Bildverarbeitung. Auf false setzen, um sowohl den automatischen Abruf von Favicons als auch von Seitenvorschauen zu deaktivieren; Live-Screenshots des Browsers sind davon nicht betroffen.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Basispfad der Control UI`},help:{"v1-1dx68ar-1w":`Optionales URL-Präfix, unter dem die Control UI bereitgestellt wird (z. B. /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Community-Einladung in der Control UI`},help:{"v1-1rz3zsx-73":`Zeigt die Einladung zur Discord-Community in der von diesem Gateway bereitgestellten Control UI an (standardmäßig aktiviert). Auf false setzen, um sie für alle Browser auszublenden, die diese UI-Bereitstellung nutzen. Änderungen werden nach dem Neuladen im Browser oder einer erneuten Verbindung wirksam; beim erneuten Aktivieren bleiben lokal im Browser vorgenommene Ausblendungen erhalten.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Gefährlichen Origin-Fallback über den Host-Header zulassen`},help:{"v1-1t1qi4c-7v":`GEFÄHRLICHE Option, die einen auf dem Host-Header basierenden Origin-Fallback für WebSocket-Prüfungen von Control UI/WebChat aktiviert. Dieser Modus wird unterstützt, wenn Ihre Bereitstellung bewusst auf einer Host-Header-basierten Origin-Richtlinie beruht; die explizite Konfiguration von gateway.controlUi.allowedOrigins bleibt die empfohlene, sicherheitsgehärtete Standardeinstellung.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Sandbox-Modus für Einbettungen in der Control UI`},help:{"v1-d54l3a-7c":'Iframe-Sandbox-Richtlinie für gehostete Einbettungen in der Control UI. "strict" deaktiviert Skripte, "scripts" erlaubt interaktive Einbettungen unter Beibehaltung der Origin-Isolation (Standard), und "trusted" fügt `allow-same-origin` für Dokumente derselben Website hinzu, die bewusst erweiterte Berechtigungen benötigen.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI aktiviert`},help:{"v1-1hhyymc-4w":`Aktiviert bei true die Bereitstellung der Control UI des Gateway über dessen HTTP-Prozess. Für die lokale Administration aktiviert lassen und deaktivieren, wenn eine externe Verwaltungsoberfläche sie ersetzt.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Control UI-Umgebung`},help:{"v1-paarso-4n":`Optionale öffentliche Umgebungskennzeichnung, die im Streifen der Control UI, im Agenten-Avatar, in Beschriftungs-Badges, im Browsertitel und im Favicon angezeigt wird. Lassen Sie sie weg, um das Standarderscheinungsbild beizubehalten.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Umgebungsfarbe der Control UI`},help:{"v1-mp6cta-2i":`Benannte Farbskala für die Umgebung: teal, amber, purple, coral, pink, blue, green, red oder gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Umgebungsbezeichnung der Control UI`},help:{"v1-1njve3z-3z":`Umgebungsbezeichnung, die in der Control UI und im Browser-Tab angezeigt wird; führende und nachfolgende Leerzeichen werden entfernt. Die Bezeichnung muss 1 bis 24 Zeichen enthalten.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Experimentelle Funktionen der Control UI`},help:{"v1-1qobi2m-3g":`Optional aktivierbare Experimente der Control UI. Diese Funktionen können sich von Version zu Version ändern und bleiben deaktiviert, solange sie nicht ausdrücklich aktiviert werden.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Benutzeroberfläche für benutzerdefinierte Plugins`},help:{"v1-108u6ts-9e":`Erlaubt benutzerinstallierten Plugins, natives JavaScript in der Control UI auszuführen (Standard: false). Mitgelieferte Plugin-Ansichten bleiben verfügbar. Die benutzerdefinierte UI nutzt die Gateway-Berechtigungen des angemeldeten Bedieners; aktivieren Sie sie nur für vertrauenswürdige Plugins. Änderungen werden ohne Neustart des Gateway wirksam. Laden Sie geöffnete Seiten der Control UI neu, um zuvor geladenen Plugin-Code zu entfernen.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`GitHub-Dienstzugangsdaten der Control UI`},help:{"v1-1p31phh-d6":`SecretRef-gestützter Dienstzugang für die Projekterkennung der Control UI und GitHub-Vorschauen beim Darüberfahren ohne verwaltete Identität. Die Vorschauen verwenden bevorzugt die konfigurierte GitHub-Identität des ausgewählten Agenten und übernehmen die Systemidentität, wenn keine Überschreibung vorliegt. Verwenden Sie bevorzugt eine explizite Konfiguration, um die Dienstzuordnung klar festzulegen. Lassen Sie diese Angabe weg, um den Rückgriff auf GH_TOKEN/GITHUB_TOKEN aus der gemeinsamen Prozessumgebung des Gateway beizubehalten. Ist ein explizit konfigurierter Dienstzugang nicht verfügbar, wird der Zugriff verweigert.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Stammverzeichnis der Control UI-Assets`},help:{"v1-elck04-25":`Optionales Stammverzeichnis im Dateisystem für Control UI-Assets (Standard: dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Sitzungsbeobachter der Control UI`},help:{"v1-1ahs80-8a":`Erstellt mit dem Hilfsmodell des jeweiligen Agenten Live-Zusammenfassungen des Sitzungsstatus für abonnierte Control UI-Clients (standardmäßig aktiviert). Setzen Sie den Wert auf false, um Modellaufrufe des Beobachters im gesamten Gateway zu deaktivieren. Wenn agents.defaults.utilityModel auf eine leere Zeichenfolge gesetzt wird, wird die Beobachtung durch das Hilfsmodell für Agenten deaktiviert, die diesen Wert nicht überschreiben.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Benutzerdefinierter Bind-Host des Gateway`},help:{"v1-lwjcyo-4d":`IPv4-Adresse für eine benutzerdefinierte Bindung. Bestimmte IPv4-Adressen erfordern denselben Gateway-Port auch auf 127.0.0.1. Vermeiden Sie 0.0.0.0, sofern keine Erreichbarkeit über alle Schnittstellen erforderlich ist.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`HTTP-API des Gateway`},help:{"v1-ebtex7-4j":`Konfiguration der HTTP-API des Gateway, die Endpunktschalter und transportseitige Steuerungen der API-Erreichbarkeit bündelt. Lassen Sie nur benötigte Endpunkte aktiviert, um die Angriffsfläche zu verringern.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`HTTP-Endpunkte des Gateway`},help:{"v1-1a0r104-55":`Funktionsschalter für HTTP-Endpunkte der Gateway-API für Kompatibilitätsrouten und optionale Integrationen. Aktivieren Sie Endpunkte gezielt und überwachen Sie die Zugriffsmuster nach der Einführung.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Endpunkt für OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Den OpenAI-kompatiblen Endpunkt `POST /v1/chat/completions` aktivieren (Standard: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Bildlimits für OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Einstellungen für den Abruf und die Validierung von Bildern in OpenAI-kompatiblen `image_url`-Bestandteilen."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Zulässige Bild-MIME-Typen für OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Zulässige MIME-Typen für `image_url`-Bestandteile (Liste ohne Unterscheidung zwischen Groß- und Kleinschreibung)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Bild-URLs für OpenAI Chat Completions zulassen`},help:{"v1-55cb3n-47":"Serverseitige URL-Abrufe für `image_url`-Bestandteile zulassen (Standard: false; Daten-URIs werden weiterhin unterstützt). Setzen Sie diesen Wert auf `false`, um URL-Abrufe vollständig zu deaktivieren."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Maximale Bildgröße in Bytes für OpenAI Chat Completions`},help:{"v1-d920yx-1s":"Maximale Anzahl an Bytes pro abgerufenem oder dekodiertem `image_url`-Bild (Standard: 10 MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`OpenAI Chat Completions: Maximale Weiterleitungen für Bilder`},help:{"v1-1enujsk-1z":"Maximal zulässige Anzahl an HTTP-Weiterleitungen beim Abrufen von `image_url`-URLs (Standard: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`OpenAI Chat Completions: Zeitlimit für Bilder (ms)`},help:{"v1-89w2b9-1x":"Zeitlimit in Millisekunden für das Abrufen von `image_url`-URLs (Standard: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`OpenAI Chat Completions: Zulassungsliste für Bild-URLs`},help:{"v1-n4hlt1-4r":"Optionale Zulassungsliste für Hostnamen beim Abrufen von `image_url`-URLs; unterstützt exakte Hostnamen und Platzhalter wie `*.example.com`. Leere oder nicht angegebene Listen bedeuten keine Einschränkung durch eine Hostnamen-Zulassungsliste."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Gateway-HTTP-Sicherheitsheader`},help:{"v1-n8z1hb-44":`Optionale HTTP-Sicherheitsheader für Antworten, die vom Gateway-Prozess selbst gesetzt werden. Legen Sie diese vorzugsweise an Ihrem Reverse-Proxy fest, wenn TLS dort terminiert wird.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Strict-Transport-Security-Header`},help:{"v1-1buwhc3-3v":`Wert für den Antwortheader Strict-Transport-Security. Nur für HTTPS-Ursprünge festlegen, die Sie vollständig kontrollieren; zum expliziten Deaktivieren false verwenden.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Gateway-Modus`},help:{"v1-nfjirv-5m":`Betriebsmodus des Gateway: "local" führt Kanäle und die Agent-Laufzeit auf diesem Host aus, während "remote" eine Verbindung über einen Remote-Transport herstellt. Behalten Sie "local" bei, sofern Sie nicht bewusst eine verteilte Remote-Gateway-Topologie betreiben.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Skills von Gateway-Knoten aktiviert`},help:{"v1-1xwu6at-3g":`Von gekoppelten Knoten veröffentlichte Skills akzeptieren, solange diese verbunden sind (Standard: true). Setzen Sie den Wert auf false, um von Knoten veröffentlichte Skills zu ignorieren.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Browsermodus für Gateway-Knoten`},help:{"v1-oeu1nc-69":`Browser-Routing über Knoten ("auto" = den Host-Browser bevorzugen und einen einzelnen verbundenen Browser-Knoten verwenden, wenn die lokale Funktion nicht verfügbar ist; "manual" = eine explizite Knotenauswahl oder eine konfigurierte feste Zuordnung erfordern; "off" = Knoten-Routing deaktivieren).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Feste Browser-Knotenzuordnung für das Gateway`},help:{"v1-1cykty2-1p":`Browser-Routing an eine bestimmte Knoten-ID oder einen bestimmten Knotennamen binden (optional).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Zulassungsliste für Gateway-Knoten (zusätzliche Befehle)`},help:{"v1-6l4otb-5m":"Zusätzliche node.invoke-Befehle, die über die Gateway-Standardvorgaben hinaus zugelassen werden sollen (Array von Befehlszeichenfolgen). Das Aktivieren gefährlicher Befehle an dieser Stelle ist eine sicherheitsrelevante Außerkraftsetzung und wird von `openclaw security audit` gemeldet."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Sperrliste für Gateway-Knoten`},help:{"v1-u7c8wx-53":"Namen von Knotenbefehlen, die blockiert werden sollen, auch wenn sie in den vom Knoten gemeldeten Angaben oder in der Standardzulassungsliste enthalten sind (nur exakte Übereinstimmung des Befehlsnamens, z. B. `system.run`; Shell-Text innerhalb dieses Befehls wird nicht geprüft)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Kopplung von Gateway-Knoten`},help:{"v1-gldsi2-4s":`Richtlinieneinstellungen für die Knotenkopplung. Die SSH-verifizierte automatische Genehmigung ist standardmäßig aktiviert; die automatische Genehmigung per CIDR bleibt deaktiviert, sofern keine expliziten CIDR/IP-Zulassungslisten mit vertrauenswürdigen Adressen konfiguriert sind.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`CIDRs für die automatische Genehmigung der Gateway-Knotenkopplung`},help:{"v1-1m6jsxj-6x":`Optional aktivierbare CIDR/IP-Zulassungsliste zur automatischen Genehmigung der erstmaligen Gerätekopplung mit Knotenrolle ohne angeforderte Berechtigungsbereiche. Ohne Konfiguration deaktiviert. Kopplungen für Operator, Browser und Control UI sowie alle Kopplungen zur Erweiterung von Rollen, Berechtigungsbereichen, Metadaten oder öffentlichen Schlüsseln erfordern weiterhin eine manuelle Genehmigung.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Automatische Genehmigung lokaler Gateway-Knotenkopplungen`},help:{"v1-glzm36-41":`Vertrauenswürdige lokale Kopplungen und Zugriffserweiterungen ohne Rückfrage genehmigen (Standard: true); auf false setzen, um zugunsten einer expliziten Genehmigung jedes Geräts auf diesen Komfort zu verzichten.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`SSH-Verifizierung der Gateway-Knotenkopplung`},help:{"v1-1e4da92-ct":"SSH-verifizierte automatische Genehmigung für die erstmalige Gerätekopplung mit Knotenrolle (Standard: aktiviert). Das Gateway verbindet sich per SSH zurück mit dem Kopplungshost (BatchMode, strenge Hostschlüsselprüfung) und genehmigt nur, wenn die Ausgabe von `openclaw node identity` auf dem entfernten Host mit dem zur Genehmigung ausstehenden Geräteschlüssel übereinstimmt. Auf false setzen, um die SSH-Verifizierung zu deaktivieren (unabhängig von autoApproveCidrs, das aktiv bleibt); für ausschließlich manuelle Kopplungen zusätzlich autoApproveCidrs entfernen. Ein Objekt übergeben, um user/identity/timeoutMs/cidrs zu überschreiben."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Plugin-Werkzeuge der Gateway-Knoten`},help:{"v1-1c24iq3-28":`Steuert, ob gekoppelte Knoten für Agenten sichtbare Beschreibungen von Plugin-Werkzeugen veröffentlichen dürfen.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Plugin-Tools von Gateway-Knoten aktiviert`},help:{"v1-14lgfu6-47":`Für Agenten sichtbare Plugin-Tool-Deskriptoren akzeptieren, die von gekoppelten Knoten veröffentlicht werden (Standard: true). Auf false setzen, um alle von Knoten veröffentlichten Plugin-Tools zu ignorieren und zu entfernen.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Gateway-Port`},help:{"v1-for8t5-54":`TCP-Port, den der Gateway-Listener für die API, die Control UI und kanalseitige Eingangspfade verwendet. Verwenden Sie einen dedizierten Port und vermeiden Sie Konflikte mit Reverse-Proxys oder lokalen Entwicklungsdiensten.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Gateway-Portale`},help:{"v1-1v2lkw9-1c":`Einstellungen für die Veröffentlichung von Portalen und privaten Ingress.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Privater Portal-Ingress`},help:{"v1-20w4gq-69":`Optionaler, vom Betreiber verwalteter privater HTTPS-Wildcard-Reverse-Proxy. Leiten Sie den ursprünglichen Host, die Pfade und WebSocket-Upgrades an den dedizierten Loopback-Listener weiter. Die Bearer-Authentifizierung für das Portal bleibt erforderlich. Erfordert einen Neustart des Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Wildcard-Domain für Portale`},help:{"v1-1ipbfad-53":`Reine DNS-Domain für zufällige Portal-Subdomains (zum Beispiel previews.example.net). Konfigurieren Sie Wildcard-DNS und HTTPS privat; verwenden Sie nicht denselben Hostnamen-Namensraum wie für den Gateway oder die Control UI.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Loopback-Port für Portal-Ingress`},help:{"v1-1mb98cv-4g":`Dedizierter Loopback-HTTP-Port, der Anfragen vom privaten Wildcard-HTTPS-Proxy empfängt. Muss sich vom Gateway-Port unterscheiden. Dies ist der Backend-Port, nicht der öffentliche HTTPS-Port.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Öffentlicher Ursprung des Gateway`},help:{"v1-17vekvx-87":`Extern erreichbarer HTTPS-Ursprung des Gateway. HTTP ist nur für localhost, 127.0.0.1 oder [::1] zulässig. MCP OAuth verwendet ihn für jeden Anfragenden, um die Callback-URL unter /oauth/mcp/callback zu erstellen; Links zu Kanalsitzungen und von Plugins generierte Viewer-Links verwenden ihn, um die Control UI und die Gateway-Routen zu erreichen.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Gateway-Push-Zustellung`},help:{"v1-h23oz7-5s":`Einstellungen für die Push-Zustellung, die das Gateway verwendet, wenn es gekoppelte Geräte aufwecken oder benachrichtigen muss. Konfigurieren Sie hier Relay-gestützte APNs für offizielle iOS-Builds; die direkte APNs-Authentifizierung für lokale oder manuelle Builds erfolgt weiterhin über Umgebungsvariablen.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Gateway-APNs-Zustellung`},help:{"v1-4bbafr-4e":`APNs-Zustellungseinstellungen für iOS-Geräte, die mit diesem Gateway gekoppelt sind. Verwenden Sie Relay-Einstellungen für offizielle App Store-Builds, die sich über das externe Push-Relay registrieren.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Gateway-APNs-Relay`},help:{"v1-7glbel-6x":`Einstellungen für externe Relays zum relaygestützten APNs-Versand. Das Gateway verwendet standardmäßig das gehostete OpenClaw-Relay oder dieses benutzerdefinierte Relay für push.test, Aufweckimpulse und das Aufwecken zur erneuten Verbindung, nachdem ein gekoppelter offizieller iOS-Build eine relaygestützte Registrierung veröffentlicht hat.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`Basis-URL des Gateway-APNs-Relays`},help:{"v1-1o8mgnq-69":`Optionale benutzerdefinierte HTTPS-Basis-URL für den externen APNs-Relay-Dienst, den offizielle iOS-Builds aus dem App Store verwenden. Diese URL muss mit der im iOS-Build fest hinterlegten Relay-URL übereinstimmen, damit Registrierung und Versand dieselbe Bereitstellung erreichen.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Zeitlimit für das Gateway-APNs-Relay (ms)`},help:{"v1-a0jkb1-4z":`Zeitlimit in Millisekunden für Sendeanfragen vom Gateway an das APNs-Relay (Standard: 10000). Bei langsameren Relays oder Netzwerken erhöhen oder verringern, um Aufweckversuche schneller abzubrechen.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Konfiguration neu laden`},help:{"v1-d02mvq-4w":`Richtlinie zum Neuladen der Konfiguration im laufenden Betrieb. Legt fest, wie Änderungen angewendet und wann vollständige Neustarts ausgelöst werden. Behalten Sie für möglichst sichere Aktualisierungen im Betrieb das hybride Verhalten bei, außer wenn Sie die internen Abläufe des Neuladens debuggen.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Modus zum Neuladen der Konfiguration`},help:{"v1-1q1etcf-3m":`Steuert, wie Konfigurationsänderungen angewendet werden: "off" ignoriert Änderungen im laufenden Betrieb, und "hybrid" wendet Änderungen an, die im laufenden Betrieb sicher übernommen werden können, und startet anschließend bei Bedarf neu.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Entferntes Gateway`},help:{"v1-6xv7gd-5a":`Verbindungseinstellungen für ein entferntes Gateway über eine direkte Verbindung oder SSH, wenn diese Instanz als Proxy für einen anderen Laufzeithost dient. Verwenden Sie den Remote-Modus nur, wenn der Betrieb auf getrennten Hosts bewusst konfiguriert wurde.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Edge-Authentifizierungsheader für den entfernten Gateway`},help:{"v1-jg9p7d-5o":`HTTP-Header mit geheimen Werten, die an einen identitätsbasierten Proxy vor dem konfigurierten entfernten Gateway übermittelt werden. Die Header werden über WSS ausschließlich an den exakten Ursprung von gateway.remote.url gesendet und folgen niemals Weiterleitungen.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Passwort für den entfernten Gateway`},help:{"v1-16jc0yx-7y":`Gemeinsames Geheimnis, das im Passwortfeld gesendet wird, um diesen Client bei einem entfernten Gateway zu authentifizieren. gateway.auth.mode des Servers bestimmt, welches konfigurierte Geheimnis verwendet wird; sowohl das Token- als auch das Passwortfeld des Clients wird akzeptiert. Verwalten Sie dieses Geheimnis extern und vermeiden Sie Klartextwerte in versionierter Konfiguration.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`SSH-Hostschlüsselrichtlinie für den entfernten Gateway`},help:{"v1-7qoxtb-49":`Richtlinie zur Überprüfung von SSH-Hostschlüsseln unter macOS. "strict" erfordert einen bereits vertrauenswürdigen Hostschlüssel; "openssh" delegiert die Überprüfung ausdrücklich an die wirksame OpenSSH-Konfiguration.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`SSH-Identität für den entfernten Gateway`},help:{"v1-hz2hsm-1f":`Optionaler Pfad zur SSH-Identitätsdatei (wird an ssh -i übergeben).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`SSH-Ziel für den entfernten Gateway`},help:{"v1-85w39w-2t":`Entfernter Gateway über SSH (leitet den Gateway-Port per Tunnel an localhost weiter). Format: user@host oder user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`TLS-Fingerabdruck des entfernten Gateway`},help:{"v1-1ri16lk-23":`Erwarteter sha256-TLS-Fingerabdruck für den entfernten Gateway (fest hinterlegen, um MITM-Angriffe zu verhindern).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Token für den entfernten Gateway`},help:{"v1-1pb9q8w-7v":`Gemeinsames Geheimnis, das im Feld token gesendet wird, um diesen Client bei einem entfernten Gateway zu authentifizieren. gateway.auth.mode des Servers bestimmt, welches konfigurierte Geheimnis verwendet wird; akzeptiert wird sowohl das Client-Feld token als auch das Feld password. Speichern Sie es über die Substitution von Geheimnissen oder Umgebungsvariablen und rotieren Sie es bei Änderungen an der Authentifizierung des entfernten Gateway.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Transport zum entfernten Gateway`},help:{"v1-1acfs7m-54":`Transport für die Remote-Verbindung: "direct" verwendet die konfigurierte URL für die Verbindung, während "ssh" einen SSH-Tunnel nutzt. Verwenden Sie SSH, wenn Sie einen verschlüsselten Tunnel benötigen, ohne entfernte Ports freizugeben.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL des entfernten Gateway`},help:{"v1-va7exe-1b":`WebSocket-URL des entfernten Gateway (ws:// oder wss://).`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Gateway-Operatorrollen`},help:{"v1-b59sc5-6w":`Optionale, profilgebundene Operatorrollen für Team-Gateways. Jede benannte Rolle steuert den Zugriff auf Sitzungen anderer Personen, die Sandbox-Isolation, Sitzungs- und Ausführungsagenten sowie die gewährten Operator-Berechtigungsbereiche. Wenn Sie diesen Abschnitt weglassen, bleibt das bestehende Operatorverhalten erhalten.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`Standard-Operatorrolle`},help:{"v1-1v8add8-4u":`Erforderliche Rolle, die authentifizierten Profilen ohne gültige explizite Zuweisung zugewiesen wird, sobald Operatorrollen konfiguriert sind. Ihr Name muss mit einer konfigurierten Rollendefinition übereinstimmen.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Definitionen der Operatorrollen`},help:{"v1-uv91an-53":`Nicht leere, von Administratoren benannte Rollendefinitionen, die die abschließend festgelegten Richtlinien für Sitzungsfreigabe, Sandbox-Isolation, Agentenzugriff und Operator-Berechtigungsbereiche bündeln, die auf authentifizierte Benutzerprofile angewendet werden.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Definition der Operatorrolle`},help:{"v1-p8tfws-6q":`Eine benannte Operatorrolle. Jede Definition muss ausdrücklich ihre Richtlinie zur Sitzungsfreigabe, die zulässigen Agenten für Sitzungen und Ausführungen sowie die Obergrenze der Operatorberechtigungen angeben. Sie kann außerdem Sandbox-Isolation für neu erstellte Sitzungen und eine Plugin-Zugriffsrichtlinie vorschreiben.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Plugin für die Zugriffsrichtlinie der Operatorrolle`},help:{"v1-1gq4q08-9n":`Optionale exakte Plugin-ID, deren Gateway-Zugriffsrichtlinie diese Rolle autorisieren muss. Der Zugriff wird verweigert, wenn das Plugin fehlt, deaktiviert ist, nicht geladen werden kann oder keine aktuell gültige Autorisierung bereitstellt. Nicht verfügbare Plugin-IDs bleiben als Konfiguration gültig, damit unabhängige Mitarbeiterrollen und der Gateway-Eigentümer den Zugriff wiederherstellen können. Wird dieses Feld weggelassen, entsteht keine Plugin-Abhängigkeit.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Zulässige Agenten der Operatorrolle`},help:{"v1-fvun18-4v":`Agenten, die verfügbar sind, wenn diese Rolle Sitzungen erstellt oder Ausführungen startet: Setzen Sie "*", um alle Agenten zuzulassen, geben Sie Agenten-IDs an, um nur diese Agenten zuzulassen, oder verwenden Sie eine leere Liste, um beides zu deaktivieren.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Sandbox-Isolation der Operatorrolle`},help:{"v1-sknx21-66":`Ausführungsisolation für neu erstellte Sitzungen: "inherit" (Standard) verwendet die Agentenrichtlinie; "required" schreibt dauerhaft eine Sandbox vor, auch wenn der Sandbox-Modus des Agenten deaktiviert ist, und verhindert die Ausführung, wenn das Backend nicht verfügbar ist.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Berechtigungsobergrenze der Operatorrolle`},help:{"v1-1selr2i-4s":`Abschließende Liste der Operatorberechtigungen, die als maximale Verbindungsbefugnisse dieser Rolle gewährt werden. Angeforderte, durch Kopplung oder Identität gewährte sowie erweiterte Berechtigungen werden auf die Schnittmenge mit dieser Liste beschränkt.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Sitzungszugriff der Operatorrolle`},help:{"v1-hsoiop-45":`Berechtigungen zur Sitzungsfreigabe, die dieser Rolle für Sitzungen gewährt werden, die von anderen authentifizierten Personen erstellt wurden; die eigenen Sitzungen einer Person bleiben für diese zugänglich.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Zugriff der Operatorrolle auf andere Sitzungen`},help:{"v1-vf8umx-5r":`Zugriff auf Sitzungen anderer Personen: "none" blendet sie aus, "view" erlaubt das Lesen, "suggest" erlaubt den Vorschlagsablauf und "write" erlaubt die Teilnahme. Eine explizite Sitzungsmitgliedschaft kann zusätzlichen Zugriff gewähren.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Gateway-Tailscale`},help:{"v1-6ar9o-4x":`Einstellungen zur Tailscale-Integration für die Bereitstellung über Serve/Funnel und die Lebenszyklusverwaltung beim Starten/Beenden des Gateway. Deaktiviert lassen, sofern Ihre Bereitstellung nicht bewusst auf eingehende Verbindungen über Tailscale angewiesen ist.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Gateway-Tailscale-Modus`},help:{"v1-6l2099-5a":`Tailscale-Veröffentlichungsmodus: "off", "serve" oder "funnel" für private oder öffentliche Zugriffswege. Verwenden Sie "serve" für Zugriff ausschließlich innerhalb des Tailnets und "funnel" nur, wenn Erreichbarkeit über das öffentliche Internet erforderlich ist.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Gateway-Tailscale-Migrationsschutz für externen Funnel`},help:{"v1-1mntkor-7q":`Veralteter Migrationsschutz für mode='serve'. Wenn ein externer Funnel weiterhin auf den regulären Gateway-Listener verweist, lässt OpenClaw die Bereitstellung unverändert und warnt, dass nur über Plugins authentifizierte Webhooks nutzbar bleiben, bis die Passwortauthentifizierung konfiguriert und der Modus auf 'funnel' umgestellt wurde.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Operator-Terminal`},help:{"v1-18f5rgm-8b":`Operator-Terminal für Control UI und mobile Clients: eine PTY-gestützte Shell auf dem Gateway-Host, beschränkt auf Operator-Sitzungen mit Admin-Berechtigungsumfang. Sie startet im Arbeitsbereich des Zielagenten und wird für vollständig in einer Sandbox ausgeführte Agenten (sandbox.mode 'all') verweigert, statt eine uneingeschränkte Host-Shell bereitzustellen.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Zeitlimit für abgekoppelte Sitzungen des Operator-Terminals`},help:{"v1-k6qbgr-9e":`Anzahl der Sekunden, die eine Terminalsitzung nach einem Verbindungsabbruch (Ruhezustand des Laptops, Neuladen der Seite) bestehen bleibt. Sie kann über terminal.attach erneut verbunden werden, wobei ihre letzte Ausgabe erneut angezeigt wird. Setzen Sie den Wert auf 0, um Sitzungen bei einem Verbindungsabbruch sofort zu beenden. Standard: 300 (5 Minuten). Getrennte Sitzungen führen ihre Befehle weiterhin aus. Verkürzen Sie daher diese Zeit auf gemeinsam genutzten oder öffentlich zugänglichen Hosts.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Bedienerterminal aktiviert`},help:{"v1-1nez06v-7p":`Aktiviert das Operatorterminal für Clients mit Administratorberechtigungen (Standard: true). Dadurch wird eine Shell im Browser oder auf Mobilgeräten mit der Prozessumgebung des Gateway bereitgestellt; setzen Sie den Wert auf false, wenn Operatoren mit Administratorberechtigungen in dieser Bereitstellung keinen Shell-Zugriff auf den Host erhalten sollen. Änderungen werden ohne Neustart des Gateway wirksam.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Shell des Bedienerterminals`},help:{"v1-19mfe6t-5i":`Ausführbare Shell-Datei, die das Bedienerterminal startet. Lassen Sie die Einstellung leer, um die Anmeldeshell des Hosts zu verwenden ($SHELL unter Unix, %ComSpec% unter Windows), oder legen Sie einen bestimmten Interpreter für eine einheitliche Bedienumgebung fest.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`Gateway-TLS`},help:{"v1-1dx77dq-4z":`TLS-Zertifikat- und Schlüsseleinstellungen für die direkte HTTPS-Terminierung im Gateway-Prozess. Verwenden Sie in Produktionsumgebungen explizit konfigurierte Zertifikate und vermeiden Sie die unverschlüsselte Bereitstellung in nicht vertrauenswürdigen Netzwerken.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Gateway-TLS-Zertifikat automatisch generieren`},help:{"v1-1ld6uiu-4w":`Generiert automatisch ein lokales TLS-Zertifikat-Schlüssel-Paar, wenn keine expliziten Dateien konfiguriert sind. Verwenden Sie dies nur für lokale oder Entwicklungsumgebungen und ersetzen Sie es für den Produktionsbetrieb durch echte Zertifikate.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Pfad zum TLS-CA-Bundle des Gateway`},help:{"v1-andqlu-52":`Optionaler Pfad zum CA-Bundle für die Client-Verifizierung oder benutzerdefinierte Anforderungen an die Vertrauenskette am Gateway. Verwenden Sie diese Option, wenn eine private PKI oder benutzerdefinierte Zertifikatsketten Teil der Bereitstellung sind.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Pfad zum TLS-Zertifikat des Gateway`},help:{"v1-1wznaof-4q":`Dateisystempfad zur TLS-Zertifikatsdatei, die das Gateway bei aktiviertem TLS verwendet. Verwenden Sie verwaltete Zertifikatspfade und stimmen Sie die automatische Erneuerung auf diesen Speicherort ab.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`Gateway-TLS aktiviert`},help:{"v1-ykhwp0-4o":`Aktiviert die TLS-Terminierung am Gateway-Listener, sodass Clients direkt über HTTPS/WSS eine Verbindung herstellen. Lassen Sie diese Option bei direkter Erreichbarkeit aus dem Internet oder an jeder Grenze zu nicht vertrauenswürdigen Netzwerken aktiviert.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Pfad zum TLS-Schlüssel des Gateway`},help:{"v1-15knri0-4i":`Dateisystempfad zur privaten TLS-Schlüsseldatei, die das Gateway bei aktiviertem TLS verwendet. Beschränken Sie die Zugriffsrechte für diese Schlüsseldatei und wechseln Sie den Schlüssel gemäß Ihrer Sicherheitsrichtlinie.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Gateway-Richtlinie zur Werkzeugfreigabe`},help:{"v1-1ffol26-5a":`Richtlinie zum Zulassen oder Sperren von Werkzeugen auf Gateway-Ebene, die deren Verfügbarkeit zur Laufzeit unabhängig von Agenten- oder Werkzeugprofilen einschränken kann. Verwenden Sie diese Option für übergreifende Notfallmaßnahmen und zur Absicherung von Produktionsumgebungen.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Gateway-Liste zugelassener Werkzeuge`},help:{"v1-163khb1-4y":`Explizite Liste zugelassener Werkzeuge auf Gateway-Ebene, wenn zur Laufzeit nur eine begrenzte Auswahl an Werkzeugen verfügbar sein soll. Verwenden Sie diese Option für streng abgesicherte Umgebungen, in denen der Werkzeugumfang eng kontrolliert werden muss.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Gateway-Liste gesperrter Werkzeuge`},help:{"v1-1lhssnf-4o":`Explizite Sperrliste für Tools auf Gateway-Ebene, um riskante Tools zu blockieren, selbst wenn Richtlinien auf niedrigeren Ebenen sie zulassen. Verwenden Sie Sperrregeln für Notfallmaßnahmen und zur Absicherung durch mehrschichtige Schutzmaßnahmen.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`CIDRs vertrauenswürdiger Proxys für das Gateway`},help:{"v1-n5zcvf-4f":`CIDR/IP-Zulassungsliste vorgeschalteter Proxys, die weitergeleitete Header zur Clientidentität bereitstellen dürfen. Halten Sie diese Liste eng begrenzt, damit sich nicht vertrauenswürdige Zwischenstationen nicht als Benutzer ausgeben können.`}},hooks:{label:{"v1-j9ywl7-5":`Hooks`},help:{"v1-1mzh0ry-5v":`Automatisierungsschnittstelle für eingehende Webhooks, die externe Ereignisse Aufweck- oder Agentenaktionen in OpenClaw zuordnet. Sichern Sie diese mit expliziten Token-, Sitzungs- und Agentenkontrollen ab, bevor Sie sie außerhalb vertrauenswürdiger Netzwerke zugänglich machen.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`Für Hooks zulässige Agenten-IDs`},help:{"v1-hree88-7c":`Zulassungsliste der tatsächlich verwendeten Agenten-IDs, an die Hook-Anfragen und -Zuordnungen gerichtet werden dürfen, einschließlich der Weiterleitung an den Standardagenten, wenn agentId fehlt. Beschränken Sie damit Automatisierungsereignisse auf dedizierte Dienstagenten und begrenzen Sie das Schadensausmaß, falls ein Hook-Token offengelegt wird.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Für Hooks zulässige Sitzungsschlüsselpräfixe`},help:{"v1-b346oh-4r":`Zulassungsliste akzeptierter Sitzungsschlüsselpräfixe für eingehende Hook-Anfragen, wenn vom Aufrufer bereitgestellte Schlüssel aktiviert sind. Verwenden Sie eng gefasste Präfixe, um das Einschleusen beliebiger Sitzungsschlüssel zu verhindern.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Sitzungsschlüssel in Hook-Anfragen zulassen`},help:{"v1-11n9ps-52":`Erlaubt Aufrufern bei true, einen Sitzungsschlüssel in Hook-Anfragen anzugeben, und ermöglicht so eine vom Aufrufer gesteuerte Weiterleitung. Behalten Sie false bei, sofern vertrauenswürdige Integratoren nicht ausdrücklich eine benutzerdefinierte Sitzungszuordnung benötigen.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Standardsitzungsschlüssel für Hooks`},help:{"v1-bzdgkn-57":`Ersatz-Sitzungsschlüssel für Hook-Zustellungen, wenn eine Anfrage keinen Schlüssel über zulässige Kanäle bereitstellt. Verwenden Sie einen stabilen, aber klar abgegrenzten Schlüssel, um voneinander unabhängige Automatisierungskonversationen nicht zu vermischen.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Hooks aktiviert`},help:{"v1-1mixmjf-4n":`Aktiviert den Hooks-Endpunkt und die Pipeline zur Ausführung von Zuordnungen für eingehende Webhook-Anfragen. Lassen Sie diese Option deaktiviert, sofern Sie nicht aktiv externe Ereignisse an das Gateway weiterleiten.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Gmail-Hook`},help:{"v1-4cibmt-4r":`Einstellungen der Gmail-Push-Integration für Pub/Sub-Benachrichtigungen und die optionale lokale Bereitstellung von Callbacks. Beschränken Sie dies nach Möglichkeit auf dedizierte Gmail-Automatisierungskonten.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Konto für Gmail-Hook`},help:{"v1-12l1h96-4v":`Google-Kontokennung für Gmail-Überwachungs- und Abonnementvorgänge in dieser Hook-Integration. Verwenden Sie ein dediziertes Automatisierungs-Postfachkonto, um die Betriebsberechtigungen getrennt zu halten.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Gmail-Hook: Unsichere externe Inhalte zulassen`},help:{"v1-1w3gdvs-55":`Erlaubt bei Aktivierung die Verarbeitung weniger gründlich bereinigter externer Gmail-Inhalte. Lassen Sie diese Option für sicherere Standardeinstellungen deaktiviert und aktivieren Sie sie nur für vertrauenswürdige E-Mail-Ströme mit kontrollierten Transformationen.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`Callback-URL für Gmail-Hook`},help:{"v1-19fhn6q-4z":`Öffentliche Callback-URL, die Gmail oder zwischengeschaltete Dienste aufrufen, um Benachrichtigungen an diese Hook-Pipeline zu übermitteln. Schützen Sie diese URL durch Token-Validierung und eingeschränkte Erreichbarkeit im Netzwerk.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Gmail-Hook: Nachrichtentext einschließen`},help:{"v1-14cf1c3-52":`Wenn true, wird der E-Mail-Text abgerufen und für die nachgelagerte Zuordnung bzw. Verarbeitung durch Agenten einbezogen. Belassen Sie den Wert auf false, sofern der Nachrichtentext nicht benötigt wird, da dies die Größe und Sensibilität der Nutzdaten erhöht.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Label für Gmail-Hook`},help:{"v1-9zpdg8-4g":`Optionaler Gmail-Labelfilter, der einschränkt, welche mit Labels versehenen Nachrichten Hook-Ereignisse auslösen. Halten Sie die Filter eng gefasst, damit Automatisierungen nicht mit irrelevanten Posteingangsnachrichten überflutet werden.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Maximale Textgröße für Gmail-Hook (Bytes)`},help:{"v1-2aaxx1-4b":`Maximale Anzahl der Gmail-Nutzdatenbytes, die pro Ereignis verarbeitet werden, wenn includeBody aktiviert ist. Verwenden Sie konservative Grenzwerte, um Kosten und Risiken bei der Verarbeitung übergroßer Nachrichten zu reduzieren.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Modellüberschreibung für Gmail-Hook`},help:{"v1-1var65t-59":`Optionale Modellüberschreibung für durch Gmail ausgelöste Ausführungen, wenn Postfachautomatisierungen ein spezifisches Modellverhalten nutzen sollen. Lassen Sie diesen Wert ungesetzt, um die Agentenstandards zu übernehmen, sofern Postfachaufgaben keine Spezialisierung erfordern.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Push-Token für Gmail-Hook`},help:{"v1-h1vx01-4o":`Gemeinsames geheimes Token, das bei Gmail-Push-Hook-Callbacks vor der Verarbeitung von Benachrichtigungen erforderlich ist. Verwenden Sie die Ersetzung durch Umgebungsvariablen und wechseln Sie das Token regelmäßig, wenn Callback-Endpunkte extern zugänglich sind.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Erneuerungsintervall für Gmail-Hook (min)`},help:{"v1-pr1z9-49":`Erneuerungsintervall in Minuten für Gmail-Überwachungsabonnements, um deren Ablauf zu verhindern. Legen Sie es kürzer als die Ablauffristen des Anbieters fest und überwachen Sie die Protokolle auf fehlgeschlagene Erneuerungen.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Lokaler Server für Gmail-Hook`},help:{"v1-hom4wq-54":`Einstellungsblock für den lokalen Callback-Server zum direkten Empfang von Gmail-Benachrichtigungen ohne separate Ingress-Schicht. Nur aktivieren, wenn dieser Prozess Webhook-Datenverkehr selbst entgegennehmen soll.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Bind-Adresse des Gmail-Hook-Servers`},help:{"v1-55bieu-4d":`Bind-Adresse für den lokalen Gmail-Callback-HTTP-Server, wenn Hooks direkt bereitgestellt werden. Auf Loopback beschränken, sofern externer Ingress nicht ausdrücklich erforderlich ist.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Pfad des Gmail-Hook-Servers`},help:{"v1-1jqhcw4-4h":`HTTP-Pfad auf dem lokalen Gmail-Callback-Server, unter dem Push-Benachrichtigungen angenommen werden. Diesen mit der Abonnementkonfiguration abstimmen, um den Verlust von Ereignissen zu vermeiden.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Port des Gmail-Hook-Servers`},help:{"v1-1yku7dz-43":`Port für den lokalen Gmail-Callback-HTTP-Server bei aktiviertem Serve-Modus. Einen dedizierten Port verwenden, um Konflikte mit Gateway- und Steuerungsschnittstellen zu vermeiden.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Gmail-Hook-Abonnement`},help:{"v1-127h8vg-5b":`Pub/Sub-Abonnement, das vom Gateway genutzt wird, um Gmail-Änderungsbenachrichtigungen aus dem konfigurierten Topic zu empfangen. Die Zuständigkeit für das Abonnement klar festlegen, damit mehrere Empfänger nicht unerwartet miteinander konkurrieren.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale für Gmail-Hooks`},help:{"v1-7jzidp-4l":`Konfigurationsblock für die Tailscale-Freigabe zur Veröffentlichung von Gmail-Callbacks über Serve/Funnel-Routen. Private Tailnet-Modi verwenden, bevor ein öffentlicher Ingress-Pfad aktiviert wird.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Tailscale-Modus für Gmail-Hooks`},help:{"v1-vhm395-4u":`Tailscale-Freigabemodus für Gmail-Callbacks: "off", "serve" oder "funnel". Verwenden Sie "serve" für die private Zustellung im Tailnet und "funnel" nur, wenn eingehender Zugriff aus dem öffentlichen Internet erforderlich ist.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Tailscale-Pfad für Gmail-Hook`},help:{"v1-fr8qi-4m":`Von Tailscale Serve/Funnel veröffentlichter Pfad zur Weiterleitung von Gmail-Callbacks, sofern aktiviert. Stimmen Sie ihn mit der Gmail-Webhook-Konfiguration ab, damit Anfragen den vorgesehenen Handler erreichen.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Tailscale-Ziel für Gmail-Hook`},help:{"v1-1twwxge-47":`Lokales Dienstziel, an das Tailscale Serve/Funnel weiterleitet (zum Beispiel http://127.0.0.1:8787). Verwenden Sie explizite Loopback-Ziele, um mehrdeutiges Routing zu vermeiden.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Überschreibung des Denkaufwands für Gmail-Hook`},help:{"v1-17owk9q-4z":`Überschreibung des Denkaufwands für durch Gmail ausgelöste Agentenausführungen: "off", "minimal", "low", "medium" oder "high". Verwenden Sie moderate Standardwerte für routinemäßige Posteingangsautomatisierungen, um Kosten und Latenz zu begrenzen.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Pub/Sub-Thema für Gmail-Hook`},help:{"v1-iled0e-4p":`Name des Google Pub/Sub-Themas, über das Gmail watch Änderungsbenachrichtigungen für dieses Konto veröffentlicht. Stellen Sie vor dem Aktivieren der Überwachung sicher, dass die IAM-Berechtigungen des Themas Gmail die Veröffentlichung erlauben.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Interne Hooks`},help:{"v1-piq9k-4v":`Laufzeiteinstellungen interner Hooks für mitgelieferte oder benutzerdefinierte Ereignishandler, die aus Modulpfaden geladen werden. Verwenden Sie diese für vertrauenswürdige Automatisierungen innerhalb des Prozesses und begrenzen Sie das Laden von Handlern strikt.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Interne Hooks aktiviert`},help:{"v1-1wv0289-4c":`Aktiviert die Verarbeitung interner Hooks und konfigurierter Einträge in der internen Hook-Laufzeitumgebung. Lassen Sie diese Option deaktiviert, sofern interne Hooks nicht bewusst konfiguriert wurden.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Interne Hook-Einträge`},help:{"v1-1ovi38l-4o":`Konfigurierte interne Hook-Einträge zur Registrierung konkreter Laufzeit-Handler und Metadaten. Halten Sie die Einträge explizit und versioniert, damit das Verhalten im Produktivbetrieb nachvollziehbar bleibt.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Interner Hook-Loader`},help:{"v1-11re5ph-4p":`Einstellungen des internen Hook-Loaders, die festlegen, wo beim Start nach Handler-Modulen gesucht wird. Beschränken Sie die Suchverzeichnisse, um unbeabsichtigte Modulkonflikte oder Modulüberlagerungen zu reduzieren.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Zusätzliche Verzeichnisse für interne Hooks`},help:{"v1-1xfdqxg-4c":`Zusätzliche Verzeichnisse, die neben den Standardladepfaden nach internen Hook-Modulen durchsucht werden. Halten Sie diese Liste möglichst klein und kontrolliert, um unbeabsichtigte Modulüberlagerungen zu reduzieren.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Hook-Zuordnungen`},help:{"v1-frhp3v-5i":`Geordnete Zuordnungsregeln, die eingehende Hook-Anfragen abgleichen und Aufweck- oder Agentenaktionen mit optionaler Zustellungsweiterleitung auswählen. Platzieren Sie spezifische Zuordnungen zuerst, damit weit gefasste Musterregeln nicht alles erfassen.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Aktion der Hook-Zuordnung`},help:{"v1-1r5zt5f-5f":`Aktionstyp der Zuordnung: "wake" löst den Aufweckablauf des Agenten aus, während "agent" die Anfrage direkt zur Verarbeitung an den Agenten sendet. Verwenden Sie "agent" für eine sofortige Ausführung und "wake", wenn eine Heartbeat-gesteuerte Verarbeitung bevorzugt wird.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`Agenten-ID der Hook-Zuordnung`},help:{"v1-l0uioz-4y":`Ziel-Agenten-ID für die Ausführung der Zuordnung, wenn das Aktionsrouting keine Standardwerte verwenden soll. Verwenden Sie dedizierte Automatisierungsagenten, um das Webhook-Verhalten von interaktiven Bedienersitzungen zu isolieren.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Hook-Zuordnung: Unsichere externe Inhalte zulassen`},help:{"v1-1np9426-57":`Bei true dürfen Zuordnungsinhalte weniger stark bereinigte externe Nutzdaten in generierten Nachrichten enthalten. Belassen Sie den Wert standardmäßig auf false und aktivieren Sie diese Option nur für vertrauenswürdige Quellen mit geprüfter Transformationslogik.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Hook-Zuordnung: Zustellungskanal`},help:{"v1-oz7pu5-5s":`Abweichender Zustellungskanal für Ausgaben der Zuordnung (zum Beispiel "last", "telegram", "discord", "slack", "signal", "imessage" oder "msteams"). Geben Sie abweichende Kanäle explizit an, um versehentliches Senden an andere Kanäle zu vermeiden.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Hook-Zuordnung: Antwort zustellen`},help:{"v1-12tbbam-5o":`Steuert, ob die Ausführungsergebnisse der Zuordnung an ein Kanalziel zurückgesendet oder ohne Ausgabe verarbeitet werden. Deaktivieren Sie die Zustellung für Hintergrundautomatisierungen, die keine für Benutzer sichtbaren Ausgaben veröffentlichen sollen.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Hook-Zuordnung: Verteilungsschlüssel`},help:{"v1-1d593op-7e":`Schlüssel eines Arrays auf der obersten Ebene der Nutzdaten, über dessen Elemente die Zuordnung verteilt wird: Jedes Element löst eine eigene Aktion aus, und Vorlagen oder Transformationen erhalten Nutzdaten, deren Array nur das aktuelle Element enthält. Die Gmail-Voreinstellung verwendet forEach: messages, sodass gebündelte Push-Nachrichten einen Durchlauf pro E-Mail auslösen.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`Hook-Zuordnungs-ID`},help:{"v1-q1t4zw-57":`Optionale stabile Kennung für einen Hook-Zuordnungseintrag, die für Audits, Fehlerbehebung und gezielte Aktualisierungen verwendet wird. Verwenden Sie eindeutige IDs, damit Protokolle und Konfigurationsvergleiche eindeutig auf Zuordnungen verweisen können.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Abgleich für Hook-Zuordnung`},help:{"v1-6u73k2-5a":`Objekt zur Gruppierung von Abgleichbedingungen für Zuordnungen, etwa Pfad und Quelle, bevor das Aktionsrouting angewendet wird. Halten Sie die Abgleichkriterien spezifisch, damit nicht zugehöriger Webhook-Datenverkehr keine Automatisierungen auslöst.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Abgleichpfad für Hook-Zuordnung`},help:{"v1-1d7dc5j-4k":`Pfadabgleichbedingung für eine Hook-Zuordnung, die üblicherweise mit dem Pfad der eingehenden Anfrage verglichen wird. Damit können Sie das Automatisierungsverhalten nach Gruppen von Webhook-Endpunktpfaden aufteilen.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Abgleichquelle für Hook-Zuordnung`},help:{"v1-177zgy7-52":`Quellenabgleichbedingung für eine Hook-Zuordnung, die typischerweise durch vertrauenswürdige vorgelagerte Metadaten oder Adapterlogik festgelegt wird. Verwenden Sie stabile Quellenkennungen, damit das Routing auch bei Wiederholungsversuchen deterministisch bleibt.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Nachrichtenvorlage für Hook-Zuordnung`},help:{"v1-ggqszl-5c":`Vorlage zum Zusammenführen strukturierter Zuordnungseingaben zum endgültigen Nachrichteninhalt, der an den Zielaktionspfad gesendet wird. Halten Sie Vorlagen deterministisch, damit die nachgelagerte Verarbeitung und das Verhalten stabil bleiben.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Modellüberschreibung für Hook-Zuordnung`},help:{"v1-10qyo4j-5e":`Optionale Modellüberschreibung für durch Zuordnungen ausgelöste Ausführungen, wenn die Automatisierung ein anderes Modell als das Standardmodell des Agenten verwenden soll. Setzen Sie dies sparsam ein, damit das Verhalten bei der Ausführung von Zuordnungen vorhersehbar bleibt.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Name der Hook-Zuordnung`},help:{"v1-zrd9tn-4v":`Lesbarer Anzeigename der Zuordnung, der in Diagnosen und Konfigurationsoberflächen für Betreiber verwendet wird. Halten Sie Namen kurz und aussagekräftig, damit der Routing-Zweck bei der Untersuchung von Vorfällen offensichtlich ist.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Sitzungsschlüssel der Hook-Zuordnung`},help:{"v1-lfnt1n-58":`Explizite Überschreibung des Sitzungsschlüssels für über Zuordnungen zugestellte Nachrichten, um die Thread-Kontinuität zu steuern. Verwenden Sie stabile Schlüssel mit klar abgegrenztem Geltungsbereich, damit wiederholte Ereignisse einander zugeordnet werden, ohne in nicht zugehörige Unterhaltungen einzufließen.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Sitzungsmodus der Hook-Zuordnung`},help:{"v1-1ggtdze-5k":`Steuert die Sitzungskontinuität der Zuordnung: "isolated" startet eine neue Ausführungssitzung, während "persistent" den ermittelten sessionKey wiederverwendet. Behalten Sie isolated bei, sofern die Integration nicht ausdrücklich dauerhaften Kontext benötigt.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Textvorlage der Hook-Zuordnung`},help:{"v1-1rg732b-4y":`Reine Textvorlage als Fallback, wenn eine erweiterte Darstellung der Nutzdaten nicht gewünscht ist oder nicht unterstützt wird. Verwenden Sie diese Vorlage, um eine kurze, einheitliche Zusammenfassung für die Zustellung über Chat-Oberflächen bereitzustellen.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Überschreibung des Denkmodus der Hook-Zuordnung`},help:{"v1-17hq8me-57":`Optionale Überschreibung des Denkaufwands für durch Zuordnungen ausgelöste Ausführungen, um Latenz und Denktiefe abzustimmen. Halten Sie den Aufwand bei Hooks mit hohem Aufkommen gering oder minimal, sofern kein tiefergehendes Schlussfolgern erforderlich ist.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Zeitlimit für Hook-Zuordnung (Sek.)`},help:{"v1-1r44ox2-4i":`Maximal zulässige Laufzeit für die Ausführung einer Zuordnungsaktion, bevor die Behandlung der Zeitüberschreitung greift. Verwenden Sie kürzere Zeitlimits für Webhook-Quellen mit hohem Aufkommen, um einen Rückstau in der Warteschlange zu vermeiden.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Zustellziel der Hook-Zuordnung`},help:{"v1-1p7928e-55":`Zielkennung innerhalb des ausgewählten Kanals, wenn Antworten aus Zuordnungen an ein festes Ziel geleitet werden sollen. Prüfen Sie die anbieterspezifischen Zielformate, bevor Sie Zuordnungen für den Produktivbetrieb aktivieren.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Transformation der Hook-Zuordnung`},help:{"v1-14igxpm-5m":`Konfigurationsblock für die Transformation, der die Vorverarbeitung durch Modul und Export vor der Verarbeitung der Zuordnungsaktion festlegt. Verwenden Sie Transformationen nur aus geprüften Codepfaden und halten Sie das Verhalten deterministisch, um eine reproduzierbare Automatisierung zu gewährleisten.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Export der Hook-Transformation`},help:{"v1-atn8v-4b":`Benannter Export, der aus dem Transformationsmodul aufgerufen werden soll. Ohne Angabe wird der Standardexport des Moduls verwendet. Legen Sie diesen Wert fest, wenn eine Datei mehrere Transformationshandler enthält.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Modul der Hook-Transformation`},help:{"v1-56futq-4v":`Relativer Pfad eines Transformationsmoduls, das aus hooks.transformsDir geladen wird, um eingehende Nutzdaten vor der Zustellung umzuschreiben. Halten Sie Module lokal, geprüft und frei von Pfadtraversierungsmustern.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Aktivierungsmodus der Hook-Zuordnung`},help:{"v1-1dzqfnw-59":`Zeitplanung für die Aktivierung: "now" aktiviert sofort, während "next-heartbeat" die Aktivierung bis zum nächsten Heartbeat-Zyklus aufschiebt. Verwenden Sie den verzögerten Modus für Automatisierungen mit niedrigerer Priorität, die eine leichte Verzögerung tolerieren.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Pfad des Hooks-Endpunkts`},help:{"v1-1l9ijzv-4u":"HTTP-Pfad, den der Hooks-Endpunkt (zum Beispiel `/hooks`) auf dem Gateway-Steuerungsserver verwendet. Verwenden Sie einen nicht erratbaren Pfad und kombinieren Sie ihn mit einer Token-Validierung für einen mehrschichtigen Schutz."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Hooks-Voreinstellungen`},help:{"v1-dp8m0l-4v":`Benannte Pakete mit Hook-Voreinstellungen, die beim Laden angewendet werden, um Standardzuordnungen und Verhaltensvorgaben einzurichten. Verwenden Sie Voreinstellungen explizit, damit Betreiber überprüfen können, welche Automatisierungen aktiv sind.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Hooks-Authentifizierungstoken`},help:{"v1-1ihf6mv-82":`Gemeinsames Bearer-Token, das am Hooks-Eingang zur Authentifizierung von Anfragen geprüft wird, bevor Zuordnungen ausgeführt werden. Behandeln Sie Token-Inhaber am Hook-Eingang als vollständig vertrauenswürdige Aufrufer, nicht als separate Rolle ohne Eigentümerrechte. Verwenden Sie die Ersetzung durch Umgebungsvariablen und rotieren Sie das Token regelmäßig, wenn Webhook-Endpunkte über das Internet erreichbar sind.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Verzeichnis für Hooks-Transformationen`},help:{"v1-1ayj9p0-4t":`Basisverzeichnis für Hook-Transformationsmodule, auf die transform.module-Pfade in Zuordnungen verweisen. Verwenden Sie ein kontrolliertes Repository-Verzeichnis, damit dynamische Importe überprüfbar und vorhersehbar bleiben.`}},logging:{label:{"v1-rq08xq-7":`Protokollierung`},help:{"v1-11an9pb-5e":`Steuert Schweregrad, Ausgabeziele, Formatierung und die Schwärzung sensibler Daten bei der Protokollierung. Wählen Sie für den Produktionsbetrieb ausreichend strenge Protokollierungsstufen und Schwärzungsregeln, ohne nützliche Diagnoseinformationen zu verlieren.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Audit-Protokoll`},help:{"v1-1lauvy2-6w":`Begrenzter Audit-Verlauf ausschließlich mit Metadaten zur Überprüfung durch Betreiber. Datensätze zu Ausführungen und Tools sind standardmäßig aktiviert; Metadaten zum Nachrichtenlebenszyklus erfordern eine separate, datenschutzrelevante Zustimmung. Der Hintergrundschreibprozess arbeitet nach dem Best-Effort-Prinzip und ist kein verlustfreies Compliance-Archiv.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Audit-Protokoll aktiviert`},help:{"v1-snknxb-4v":`Zeichnet neue Audit-Ereignisse für Ausführungen, Tools und aktivierte Nachrichten auf. Standard: true. Änderungen gelten sofort; bereits angenommene Schreibvorgänge werden abgeschlossen, und gespeicherte Datensätze bleiben bis zu ihrem Ablauf abfragbar.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Audit der Ausführungsidentität`},help:{"v1-1ucirwv-5b":`Speichert in begrenztem Umfang Zuordnungen zur Ausführungsidentität für die gezielte Prüfung einzelner Ausführungen. Standard: false. Erfordert logging.audit.enabled und gilt für neu zugelassene Ausführungen; bestehende Kontexte bleiben unverändert.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Umfang des Nachrichten-Audits`},help:{"v1-1yg4lc3-76":`Steuert die Aufzeichnung des Nachrichtenlebenszyklus ohne Nachrichteninhalte: "off" (Standard), "direct" nur für bekannte direkte Unterhaltungen oder "all" für direkte Unterhaltungen, Gruppen, Kanäle und unbekannte Unterhaltungsarten. Erfordert logging.audit.enabled. Änderungen gelten für nachfolgende Lebenszyklusereignisse.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Konsolen-Protokollierungsstufe`},help:{"v1-16badbd-5u":`Konsolenspezifischer Protokollschwellenwert: "silent", "fatal", "error", "warn", "info", "debug" oder "trace" zur Steuerung der Terminalausgabe. Damit reduzieren Sie die lokale Konsolenausgabe und behalten bei Bedarf eine ausführlichere Dateiprotokollierung bei.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Konsolenprotokollformat`},help:{"v1-d7u0iq-3q":`Format der Konsolenausgabe: "pretty" oder "json". Verwenden Sie json für maschinelle Verarbeitungspipelines und pretty für gut lesbare Terminalausgaben.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Pfad der Protokolldatei`},help:{"v1-16gaitv-4w":`Optionaler Dateipfad für dauerhaft gespeicherte Protokollausgaben zusätzlich zur oder anstelle der Konsolenprotokollierung. Verwenden Sie einen verwalteten, beschreibbaren Pfad und stimmen Sie Aufbewahrung und Rotation auf Ihre Betriebsrichtlinien ab.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Protokollstufe`},help:{"v1-1r5yku0-5o":`Primärer Protokollschwellenwert für Ausgaben des Laufzeit-Loggers: "silent", "fatal", "error", "warn", "info", "debug" oder "trace". Behalten Sie im Produktionsbetrieb "info" oder "warn" bei und verwenden Sie debug/trace nur zur Fehleranalyse.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Benutzerdefinierte Schwärzungsmuster`},help:{"v1-1esa6eg-7k":`Benutzerdefinierte Regex-Zeichenfolgen ersetzen die standardmäßige Zeichenfolgenliste für Protokoll- und Transkriptausgaben und ergänzen die Regeln zur Wahrung von Sicherheitsgrenzen für Benutzeroberfläche, Tools und Diagnose. Integrierte Schutzmechanismen für Formularinhalte, strukturierte Authentifizierungsdaten und unformatierte AWS-Schlüssel gelten immer. Verwenden Sie diese Einstellung, um bereitstellungsspezifische Tokens und Kennungen zu maskieren.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Globale MCP-Serverdefinitionen, die von OpenClaw verwaltet werden. Eingebettetes OpenClaw und andere Laufzeitadapter können diese Server nutzen, ohne sie in laufzeiteigenen Projekteinstellungen zu speichern.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`MCP-Apps`},help:{"v1-amyd91-38":`Unterstützung für MCP Apps-Oberflächen. Wenn diese Option aktiviert ist, können konfigurierte MCP-Server interaktive HTML-Ansichten für ihre Tool-Ergebnisse bereitstellen.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps aktiviert`},help:{"v1-ghqy98-3w":`Optionale Aktivierung der Darstellung von MCP Apps und der App-zu-Server-Brücke. Lassen Sie diese Option deaktiviert, sofern Sie den konfigurierten MCP-Servern, die Ressourcen für App-Oberflächen bereitstellen, nicht vertrauen.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Sandbox-Origin für MCP Apps`},help:{"v1-1sxv3mf-6v":`Optionale dedizierte öffentliche HTTP(S)-Origin für MCP Apps. Verwenden Sie diese hinter einem Reverse-Proxy oder TLS-Terminator und leiten Sie Anfragen ausschließlich an den konfigurierten Sandbox-Port für MCP Apps weiter. Sie muss sich von der Origin der Control UI unterscheiden und darf keine Inhalte bereitstellen, die eine Authentifizierung erfordern.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Sandbox-Port für MCP Apps`},help:{"v1-1b8n71l-4p":`Dedizierter Listener-Port der Sandbox für MCP Apps. Standardmäßig wird der Gateway-Port plus eins verwendet. Legen Sie einen unbenutzten Port fest, wenn ein anderer lokaler Dienst oder ein anderes Gateway-Profil diesen Port bereits belegt.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`MCP-Server`},help:{"v1-157ozoz-42":`Benannte MCP-Serverdefinitionen. OpenClaw speichert sie in seiner eigenen Konfiguration, und Laufzeitadapter entscheiden, welche Transportarten zur Ausführungszeit unterstützt werden.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`MCP-Serverauthentifizierung`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`MCP-Clientzertifikat`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`MCP-Clientschlüssel`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`MCP-Clientzertifikat`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`MCP-Clientschlüssel`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Codex-MCP-Projektion`},help:{"v1-slcmq1-6x":`OpenClaw-Projektionsmetadaten ausschließlich für Codex-app-server-Threads. Sie wirken sich weder auf ACP-Sitzungen noch auf die allgemeine Codex-Harness-Konfiguration aus. Lassen Sie diesen Block weg, damit der Server jedem Codex-app-server-Agenten mit dem standardmäßigen MCP-Genehmigungsverhalten von Codex zur Verfügung steht.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Codex-MCP-Agenten`},help:{"v1-8q98n8-67":`Optionale, nicht leere OpenClaw-Agenten-IDs, die diesen MCP-Server in ihrer Codex-app-server-Thread-Konfiguration erhalten sollen. Bei leeren, nur aus Leerzeichen bestehenden oder ungültigen Listen wird der Zugriff verweigert; wird die Liste weggelassen, wird der Server für alle Codex-app-server-Agenten projiziert.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Codex-MCP-Tool-Genehmigung`},help:{"v1-1xql0qr-3d":`Codex-native Schreibweise für denselben serverspezifischen MCP-Tool-Genehmigungsmodus. Verwenden Sie in der OpenClaw-Konfiguration vorzugsweise defaultToolsApprovalMode.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Codex-MCP-Tool-Genehmigung`},help:{"v1-y5vsqq-3s":`Optionaler Codex-MCP-Tool-Genehmigungsmodus für diesen Server: "auto", "prompt" oder "approve". Verwenden Sie diese Einstellung nur für MCP-Server, denen Sie bewusst vertrauen.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`MCP-Verbindungszeitlimit (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`MCP-Server aktiviert`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`MCP-OAuth`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`MCP-OAuth-Authentifizierungsprofil`},help:{"v1-fcrb4u-5z":`ID eines Authentifizierungsprofils mit Aktualisierungsfunktion, das das aktuelle Bearer-Token für diesen entfernten MCP-Server bereitstellt. Wenn diese Option gesetzt ist, löst OpenClaw das Profil zur Laufzeit auf und aktualisiert es, ohne die für die Aktualisierung benötigten Daten an nachgelagerte Komponenten weiterzugeben.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL der MCP-OAuth-Client-Metadaten`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`MCP-OAuth-Identität`},help:{"v1-1ie6ys7-59":`Zuordnung der OAuth-Anmeldedaten für diesen Server. Lassen Sie dieses Feld weg oder verwenden Sie "shared" für vom Betreiber verwaltete Anmeldedaten; verwenden Sie "per-requester", damit jeder authentifizierte Absender sein eigenes Konto verbinden kann.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`MCP-OAuth-Weiterleitungs-URL`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`MCP-OAuth-Berechtigungsumfang`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Zeitlimit für MCP-Anfragen (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`MCP-TLS-Verifizierung`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`MCP-TLS-Verifizierung`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Parallele MCP-Werkzeugaufrufe`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Parallele MCP-Werkzeugaufrufe`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`MCP-Werkzeugauswahl`},help:{"v1-10poyzb-4v":`MCP-Werkzeugauswahl pro Server. Verwenden Sie include, um nur ausgewählte MCP-Werkzeugnamen verfügbar zu machen, oder exclude, um ausgewählte MCP-Werkzeugnamen auszublenden. Einträge akzeptieren exakte Namen und einfache Glob-Muster mit '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Ausgeschlossene MCP-Werkzeuge`},help:{"v1-ijrc5y-1u":`Exakte MCP-Toolnamen oder einfache '*'-Glob-Muster, die auf diesem Server ausgeblendet werden sollen.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Einbezogene MCP-Tools`},help:{"v1-89fdfq-3o":`Exakte MCP-Toolnamen oder einfache '*'-Glob-Muster, die von diesem Server bereitgestellt werden sollen. Ohne Angabe bleiben alle Server-Tools verfügbar, sofern sie nicht ausgeschlossen werden.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL bei Inaktivität für MCP-Sitzungen (ms)`},help:{"v1-j9si74-87":`Optionale Frist in Millisekunden, nach der inaktive MCP-Laufzeitumgebungen von OpenClaw-Sitzungen entfernt werden. Ohne Angabe oder bei 0 bleiben die Laufzeitumgebungen bis zur Sitzungsbereinigung oder zum Herunterfahren des Gateway aktiv. Positive Werte werden abgerundet; aktive Nutzungsrechte und ausstehende Zugriffsanforderungen verhindern die Entfernung. Laufzeitumgebungen, die einem einzelnen Lauf zugeordnet sind, werden weiterhin beendet, sobald dieser einmalige Lauf endet.`}},memory:{label:{"v1-oopaku-6":`Arbeitsspeicher`},help:{"v1-1wlx40m-13":`Konfiguration des integrierten Gedächtnisses (global).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Modus für Quellenangaben aus dem Gedächtnis`},help:{"v1-1q6dxr5-4u":`Steuert die Sichtbarkeit von Quellenangaben in Antworten: "auto" zeigt Quellenangaben an, wenn sie nützlich sind, "on" zeigt sie immer an und "off" blendet sie aus. Behalten Sie "auto" als ausgewogene Standardeinstellung bei, um nützliche Hinweise ohne unnötige Ablenkung zu erhalten.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Gedächtnissuche`},help:{"v1-1ukbud1-25":`Vektorsuche in MEMORY.md und memory/*.md (agentenspezifische Überschreibungen werden unterstützt).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Embedding-Cache der Gedächtnissuche`},help:{"v1-d8h2e4-5b":`Speichert berechnete Embeddings von Textabschnitten in SQLite zwischen, damit Neuindizierung und inkrementelle Aktualisierungen schneller ablaufen (Standard: true). Lassen Sie diese Option aktiviert, sofern Sie nicht die Korrektheit des Caches untersuchen oder den Speicherplatzbedarf minimieren möchten.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Dokumenteingabetyp der Gedächtnissuche`},help:{"v1-1ui33sv-5f":"Optionaler anbieterspezifischer `input_type`-Wert für Gedächtnis-Embeddings zur Dokumentverarbeitung und Indexierung. Verwenden Sie diese Option mit OpenAI-kompatiblen asymmetrischen Embedding-Endpunkten, die eine Kennzeichnung als Passage oder Dokument erfordern."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Gedächtnissuche aktivieren`},help:{"v1-14f11b9-4t":`Hauptschalter für die Indexierung und den Abruf der Gedächtnissuche in diesem Agentenprofil. Lassen Sie ihn für den semantischen Abruf aktiviert und deaktivieren Sie ihn, wenn Sie vollständig zustandslose Antworten wünschen.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Sitzungsindex der Gedächtnissuche (experimentell)`},help:{"v1-qvhv8z-3i":`Indexiert Sitzungsprotokolle für die Gedächtnissuche. Behalten Sie diese erweiterte Überschreibung bei, wenn sich die Vererbung der Abrufeinstellungen auf globaler Ebene und pro Agent unterscheidet.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Zusätzliche Gedächtnispfade`},help:{"v1-ojqokq-7i":`Fügt dem Gedächtnisindex über die standardmäßigen Gedächtnisdateien hinaus zusätzliche Verzeichnisse oder .md-Dateien hinzu. Einträge können Pfadzeichenfolgen oder Objekte mit einem zum Stammverzeichnis relativen Glob-Muster sein. Wenn das multimodale Gedächtnis aktiviert ist, kommen auch passende Bild- und Audiodateien unter diesen Pfaden für die Indexierung infrage.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Zusätzlicher Gedächtnispfad`},help:{"v1-b9mbq8-3m":`Legt das zusätzliche Gedächtnisverzeichnis oder die zusätzliche Gedächtnisdatei fest. Relative Pfade werden ausgehend vom Arbeitsbereich des Agenten aufgelöst; bei direkten Dateieinträgen wird genau die angegebene Datei indexiert.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Muster für zusätzlichen Gedächtnispfad`},help:{"v1-j8br1v-4e":`Beschränkt einen Verzeichniseintrag auf unterstützte Dateien, die diesem zum Stammverzeichnis relativen Glob-Muster entsprechen, zum Beispiel "runbooks/**/*.md". Lassen Sie es weg, um alle unterstützten Dateien rekursiv zu durchsuchen.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Fallback für die Gedächtnissuche`},help:{"v1-1r6368w-6p":`Ersatzanbieter, der verwendet wird, wenn die primäre Embedding-Erstellung fehlschlägt: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" oder "none". Legen Sie für einen zuverlässigen Produktionsbetrieb einen tatsächlichen Ersatzanbieter fest. Verwenden Sie "none" nur, wenn Sie ausdrückliche Fehlermeldungen bevorzugen.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Eingabetyp für die Gedächtnissuche`},help:{"v1-26vbwe-5u":"Verwenden Sie diesen optionalen, anbieterspezifischen Wert für `input_type` nur, wenn dieselbe Kennzeichnung sowohl für Suchanfragen- als auch für Dokument-Embedding-Anfragen gelten soll. Verwenden Sie bei asymmetrischen Anbietern vorzugsweise queryInputType und documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Pfad zum lokalen Embedding-Modell`},help:{"v1-13ymbnt-5q":"Gibt die Quelle des lokalen Embedding-Modells für die lokale Gedächtnissuche an, beispielsweise einen GGUF-Dateipfad oder eine `hf:`-URI. Verwenden Sie dies nur, wenn provider auf `local` gesetzt ist, und prüfen Sie die Modellkompatibilität vor umfangreichen Indexneuerstellungen."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Modell für die Gedächtnissuche`},help:{"v1-11pohrl-59":`Abweichendes Embedding-Modell, das der ausgewählte Gedächtnisanbieter verwendet, wenn ein anderes als das Standardmodell benötigt wird. Legen Sie dies nur fest, wenn Sie die Trefferqualität oder die Kosten über die Anbietervorgaben hinaus gezielt anpassen müssen.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Multimodale Gedächtnissuche`},help:{"v1-1jn02s-9e":'Optionale multimodale Gedächtniseinstellungen zur Indexierung von Bild- und Audiodateien aus konfigurierten zusätzlichen Pfaden. Lassen Sie diese Funktion deaktiviert, sofern Ihr Embedding-Modell nicht ausdrücklich modalitätsübergreifende Embeddings unterstützt, und setzen Sie `memory.search.fallback` auf "none", solange sie aktiviert ist. Passende Dateien werden während der Indexierung zum konfigurierten Remote-Embedding-Anbieter hochgeladen.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Multimodale Gedächtnissuche aktivieren`},help:{"v1-1dk5d7o-7e":`Aktiviert die Indexierung von Bildern und Audiodateien aus extraPaths für das Gedächtnis. Dies erfordert derzeit Gemini embedding-2, beschränkt die standardmäßigen Gedächtnis-Stammverzeichnisse weiterhin auf Markdown, deaktiviert Ausweichanbieter für die Gedächtnissuche und lädt passende Binärinhalte zum konfigurierten Remote-Embedding-Anbieter hoch.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Maximale Dateigröße in Bytes für die multimodale Gedächtnissuche`},help:{"v1-1mmdrvk-5d":`Legt die maximal zulässige Größe in Bytes pro multimodaler Datei fest. Größere Dateien werden bei der Gedächtnisindexierung übersprungen. Begrenzen Sie damit Upload-Kosten und Indexierungslatenz oder erhöhen Sie den Wert für kurze Audioclips in hoher Qualität.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Modalitäten der multimodalen Gedächtnissuche`},help:{"v1-alp4vh-4l":`Legt fest, welche multimodalen Dateitypen aus extraPaths indexiert werden: "image", "audio" oder "all". Halten Sie die Auswahl eng, um nicht unbeabsichtigt große Binärdatenbestände zu indexieren.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Ausgabedimensionalität der Gedächtnissuche`},help:{"v1-1f7zu53-93":`Anbieterspezifische Überschreibung der Ausgabevektorgröße für Gedächtnis-Embeddings. Gemini-Modelle unterstützen 128–3072 Dimensionen; empfohlen werden 768, 1536 oder 3072. Bedrock-Modellfamilien wie Titan V2, Cohere V4 und Nova bieten jeweils eigene zulässige Größen. Rechnen Sie bei einer Änderung mit einer vollständigen Neuindexierung, da die gespeicherten Vektordimensionen konsistent bleiben müssen.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Anbieter für die Gedächtnissuche`},help:{"v1-5evseb-71":`Wählt das Embedding-Backend zum Erstellen und Abfragen von Gedächtnisvektoren aus. Standardmäßig wird "openai" verwendet; legen Sie "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" oder "local" fest, wenn Sie ein anderes Backend verwenden möchten.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Maximale Ergebnisanzahl der Gedächtnissuche`},help:{"v1-13ekath-4x":`Maximale Anzahl der Gedächtnistreffer, die die Suche vor der nachgelagerten Neusortierung und Einbindung in den Prompt zurückgibt. Erhöhen Sie den Wert für einen breiteren Abruf oder senken Sie ihn für kompaktere Prompts und schnellere Antworten.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Mindestbewertung der Gedächtnissuche`},help:{"v1-1ww231l-4v":`Mindestwert der Relevanzbewertung für die Aufnahme von Gedächtnisergebnissen in die endgültige Abrufausgabe. Erhöhen Sie den Wert, um schwache oder unpassende Treffer zu reduzieren, oder senken Sie ihn, wenn Sie weniger strenge Abrufkriterien benötigen.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Abfrage-Eingabetyp der Gedächtnissuche`},help:{"v1-831yrv-4q":"Optionaler anbieterspezifischer `input_type`-Wert für Gedächtnis-Embeddings zur Abfragezeit. Verwenden Sie diesen mit OpenAI-kompatiblen asymmetrischen Embedding-Endpunkten, die eine Abfragekennzeichnung erfordern."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Gesprächsübergreifend erinnern`},help:{"v1-k1itm8-7y":`Nutzt relevanten Kontext aus anderen privaten Gesprächen dieses Agenten durch geschützten Abruf von Gesprächsprotokollen. Standardmäßig nur aktiviert, wenn die globale Einstellung session.dmScope nicht gesetzt ist oder "main" lautet und keine Bindung den DM-Geltungsbereich überschreibt; bei jeder konfigurierten DM-Isolation standardmäßig deaktiviert. Ein explizites true oder false hat immer Vorrang.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`API-Schlüssel für Remote-Embeddings`},help:{"v1-nfuuu-62":`Stellt einen dedizierten API-Schlüssel für Remote-Embedding-Aufrufe bereit, die zur Gedächtnisindexierung und zur Erstellung von Embeddings bei Suchanfragen verwendet werden. Verwenden Sie diese Option, wenn Gedächtnis-Embeddings andere Zugangsdaten als die globalen Standardwerte oder Umgebungsvariablen verwenden sollen.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`Basis-URL für Remote-Embeddings`},help:{"v1-1ugvqgt-5p":`Überschreibt den Embedding-API-Endpunkt, beispielsweise mit einem OpenAI-kompatiblen Proxy oder einer benutzerdefinierten Gemini-Basis-URL. Verwenden Sie diese Option nur, wenn Sie Anfragen über Ihr eigenes Gateway oder einen Anbieter-Endpunkt weiterleiten; behalten Sie andernfalls die Standardeinstellungen des Anbieters bei.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Remote-Stapelverarbeitung für Embeddings aktiviert`},help:{"v1-1fehqi-5x":`Aktiviert die Stapelverarbeitungs-APIs des Anbieters für Embedding-Aufträge, sofern unterstützt (OpenAI/Gemini), und verbessert so den Durchsatz bei größeren Indexierungsläufen. Lassen Sie diese Option aktiviert, außer wenn Sie Fehler bei der Stapelverarbeitung des Anbieters untersuchen oder sehr kleine Arbeitslasten ausführen.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`HTTP-Header für Remote-Embeddings`},help:{"v1-1uic0kd-5i":`Fügt Remote-Embedding-Anfragen benutzerdefinierte HTTP-Header hinzu, die mit den Standardwerten des Anbieters zusammengeführt werden. Verwenden Sie diese Option für Header zur Proxy-Authentifizierung und Mandantenweiterleitung. Beschränken Sie die Werte auf das Nötigste, um die Offenlegung sensibler Metadaten zu vermeiden.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Quellen für die Gedächtnissuche`},help:{"v1-btxtzg-57":`Legt fest, welche Quellen indexiert werden: "memory" liest MEMORY.md und Gedächtnisdateien ein, "sessions" bezieht den Transkriptverlauf ein. Behalten Sie ["memory"] bei, sofern Sie keine Informationen aus früheren Chat-Transkripten abrufen müssen.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Vektorindex für die Gedächtnissuche`},help:{"v1-fbybkj-37":`Steuert den semantischen Index von sqlite-vec. Behalten Sie diese erweiterte Überschreibung bei, wenn sich die Vektorrichtlinien auf Stammebene und pro Agent unterscheiden.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Pfad zur Vektorerweiterung für die Speichersuche`},help:{"v1-1hysv5q-58":"Überschreibt den automatisch erkannten Bibliothekspfad der sqlite-vec-Erweiterung (`.dylib`, `.so` oder `.dll`). Verwenden Sie dies, wenn Ihre Laufzeitumgebung sqlite-vec nicht automatisch finden kann oder Sie einen nachweislich funktionierenden Build festlegen möchten."}},messages:{label:{"v1-1wwzqad-8":`Nachrichten`},help:{"v1-i5k0iw-5k":`Nachrichteninfrastruktur und agentenübergreifende Standardwerte. Gleichrangige Einträge auf Stammebene sind für Infrastruktur und agentenübergreifende Standardwerte zuständig; agents.defaults steuert das Verhalten der Agentenschleife; Agenteneinträge können beides überschreiben, sofern dies unterstützt wird.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Emoji für Bestätigungsreaktionen`},help:{"v1-1iip0zs-1x":`Emoji-Reaktion zur Bestätigung eingehender Nachrichten (leer lassen zum Deaktivieren).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Geltungsbereich für Bestätigungsreaktionen`},help:{"v1-1jvdg5n-7s":`Legt fest, wann Bestätigungsreaktionen gesendet werden ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" bestätigt Gruppennachrichten, die den Agenten erwähnen, unabhängig davon, ob die Gruppe Erwähnungen erfordert; "group-all" bestätigt jede Gruppennachricht. "off"/"none" deaktiviert Bestätigungsreaktionen vollständig.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Gruppenchat-Regeln`},help:{"v1-chqsvh-4l":`Steuert die Verarbeitung von Gruppennachrichten, einschließlich Auslösern durch Erwähnungen und der Größe des Verlaufsfensters. Grenzen Sie Erwähnungsmuster eng ein, damit nicht jede Nachricht in Gruppenkanälen eine Reaktion auslöst.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Limit für den Gruppenverlauf`},help:{"v1-1mkbpw-9k":`Maximale Anzahl früherer Gruppennachrichten, die pro Gesprächsrunde als Kontext für Gruppensitzungen geladen werden. Höhere Werte sorgen für mehr Kontinuität, niedrigere Werte für schnellere und kostengünstigere Antworten. Der automatische Prompt-Verlauf ist auf 200 Nachrichten begrenzt. Der maximale JSON-Ganzzahlwert wählt das Standardfenster des Kanals (50 für den gemeinsamen Gruppenverlauf), kein unbegrenztes Fenster.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Muster für Gruppenerwähnungen`},help:{"v1-i7h7qc-6f":`Sichere Regex-Muster ohne Unterscheidung zwischen Groß- und Kleinschreibung, mit denen explizite Erwähnungen und Auslösephrasen in Gruppenchats erkannt werden. Verwenden Sie präzise Muster, um Fehlalarme in Kanälen mit hohem Nachrichtenaufkommen zu reduzieren; ungültige oder unsichere Muster mit verschachtelten Wiederholungen werden ignoriert.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Eingehende Gruppennachrichten ohne Erwähnung`},help:{"v1-17wef8h-5f":`Steuert, wie laufend erfasste Gruppennachrichten ohne Erwähnung übermittelt werden. "user_request" behandelt sie als Benutzeranfrage; "room_event" übermittelt sie als stillen Kontext, bei dem sichtbare Ausgaben das Nachrichten-Tool erfordern.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Sichtbare Gruppenantworten`},help:{"v1-qa4z1s-aa":`Überschreibt vom Modell verfasste Antworten im Ursprungskanal für Gruppen- und Kanalunterhaltungen. Standardmäßig gilt "automatic", wenn keine globale Richtlinie für sichtbare Antworten festgelegt ist. "message_tool" erfordert message(action=send) für normale Assistentenausgaben und generische Tool-Medien; Laufzeitausgaben, die ausdrücklich dem Host zugeordnet sind, können weiterhin zugestellt werden, außer bei Hintergrundereignissen im Raum. "automatic" veröffentlicht normale Antworten wie bisher.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Entprellung eingehender Nachrichten`},help:{"v1-ebyu5x-4a":`Einstellungen zur Entprellung direkt eingehender Nachrichten, die vor Beginn der Warteschlangen- oder Rundenverarbeitung angewendet werden. Konfigurieren Sie diese für anbieterspezifische, schnell aufeinanderfolgende Nachrichten desselben Absenders.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Entprellung eingehender Nachrichten nach Kanal (ms)`},help:{"v1-wbz54j-4g":`Kanalspezifische Überschreibungen der Entprellzeit für eingehende Nachrichten in Millisekunden, zugeordnet nach Anbieter-ID. Verwenden Sie diese Option, wenn einige Anbieter Nachrichtenfragmente in schnellerer Folge senden als andere.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Entprellzeit für eingehende Nachrichten (ms)`},help:{"v1-1616yo2-7w":`Wartezeit ohne neue Nachrichten (ms), um schnell aufeinanderfolgende eingehende Nachrichten desselben Absenders zu bündeln. Telegram verwendet standardmäßig 300 ms, wenn weder eine globale noch eine kanalspezifische Überschreibung festgelegt ist; bei anderen Kanälen beträgt der Standardwert 0. Null deaktiviert die normale Bündelung schnell aufeinanderfolgender Nachrichten, aber Telegram setzt weiterhin Teilstücke langer Nachrichten zusammen, die nahe am Längenlimit liegen.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Eingangswarteschlange`},help:{"v1-hm2o31-48":`Warteschlangenstrategie für eingehende Nachrichten, die während eines aktiven Sitzungsdurchlaufs eintreffen. Hiermit können Sie die Steuerung, zurückgestellte Folgenachrichten, Bündelung oder Unterbrechung anpassen.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Warteschlangenmodus nach Kanal`},help:{"v1-4rf8z8-54":`Kanalspezifische Überschreibungen des Warteschlangenmodus, zugeordnet nach Anbieter-ID (zum Beispiel telegram, discord, slack). Verwenden Sie diese Option, wenn das Nachrichtenaufkommen eines Kanals ein anderes Verhalten als die globalen Standardeinstellungen erfordert.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Warteschlangenkapazität`},help:{"v1-16ql8c7-4j":`Maximale Anzahl eingehender Elemente, die in der Warteschlange verbleiben, bevor die Verwerfungsrichtlinie greift. Der Standardwert ist 20. Begrenzen Sie die Kapazität in Kanälen mit hohem Nachrichtenaufkommen, damit die Speichernutzung vorhersehbar bleibt.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Fallback-Entprellzeit der Warteschlange nach Kanal (ms)`},help:{"v1-4tpyt7-4e":`Kanalspezifische Überschreibungen der Entprellzeit für das Warteschlangenverhalten, zugeordnet nach Anbieter-ID. Hiermit können Sie die Verarbeitung von Nachrichtenschüben für Chat-Oberflächen mit unterschiedlichem Nachrichtentempo unabhängig voneinander anpassen.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Verwerfungsstrategie der Warteschlange`},help:{"v1-ydb2rw-6m":`Verwerfungsstrategie bei Überschreitung der Warteschlangenkapazität. "summarize" verwirft die ältesten Einträge, behält aber kompakte Zusammenfassungen bei; "old" verwirft die ältesten Einträge ohne Zusammenfassungen; "new" weist den neuesten Eintrag zurück. Verwenden Sie "summarize" für länger andauernde Chats, bei denen der Kontext wichtig ist.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Warteschlangenmodus`},help:{"v1-19k7gy1-67":`Warteschlangenmodus für aktive Ausführungen. Verwenden Sie "steer", um Prompts in die aktive Ausführung einzuspeisen, "followup", um sie später auszuführen, "collect", um kompatible Nachrichten später gebündelt zu verarbeiten, oder "interrupt", um die aktive Ausführung abzubrechen, bevor der neueste Prompt gestartet wird.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Präfix für ausgehende Antworten`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Standardmodus der Verbrauchsfußzeile`},help:{"v1-l3shsx-dv":`Standardmodus der Verbrauchsfußzeile pro Antwort ("off"|"tokens"|"full"), der für Sitzungen übernommen wird, in denen noch kein Modus über /usage gewählt wurde. Akzeptiert auch "on" als älteren Alias für "tokens". Akzeptiert einen einzelnen Modus oder eine Zuordnung pro Kanal mit "default" als Rückfallwert. Rangfolge: Sitzungswert -> Kanaleintrag -> default -> off; eine explizite Auswahl über /usage (einschließlich off) wird gespeichert und überschreibt den Standardwert. Verwenden Sie /usage reset (Aliase: inherit, clear, default), um eine sitzungsspezifische Überschreibung zu löschen und wieder diesen konfigurierten Standardwert zu übernehmen.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Statusreaktionen`},help:{"v1-193764l-3s":`Statusreaktionen im Verlauf der Verarbeitung, die das Emoji auf der auslösenden Nachricht entsprechend dem Fortschritt des Agenten aktualisieren (eingereiht → denkt nach → Tool → fertig/Fehler).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Statusreaktionen aktivieren`},help:{"v1-1qnmmnc-7x":`Aktiviert Reaktionen zum Lebenszyklusstatus auf unterstützten Kanälen. Discord behandelt einen nicht gesetzten Wert als aktiviert, wenn Bestätigungsreaktionen aktiv sind; bei Slack, Signal, Telegram und WhatsApp muss dieser Wert auf true gesetzt sein, bevor Lebenszyklusreaktionen verwendet werden. Slack verwendet standardmäßig den nativen Assistenten-Thread-Status zur Fortschrittsanzeige.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Vorlage für die Nutzungsfußzeile`},help:{"v1-1xibc23-47":`Benutzerdefinierte Fußzeilenvorlage für /usage full, entweder als Inline-Objekt oder als Pfad zu einer JSON-Datei. Bei ungültigen oder nicht verfügbaren Vorlagen wird die integrierte Nutzungszeile verwendet.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Sichtbare Antworten`},help:{"v1-7yfwc2-8t":`Steuert die vom Modell verfassten ursprünglichen Antworten in Direkt-, Gruppen- und Kanalunterhaltungen. "message_tool" erfordert message(action=send) für normale Assistentenausgaben und allgemeine Tool-Medien; explizit vom Host verantwortete Laufzeitausgaben bleiben zustellbar, mit Ausnahme von Hintergrundereignissen im Raum. "automatic" veröffentlicht normale Antworten wie bisher.`}},meta:{label:{"v1-1xpfxac-m":`Kompatibilitätsmetadaten`},help:{"v1-1owqhgn-2w":`Abwärtslesbare Kompatibilitätsmetadaten, die beibehalten werden, damit ältere Programmversionen unsichere Konfigurationsdowngrades ablehnen können.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Version der letzten Konfigurationsänderung`},help:{"v1-qykpv1-1i":`OpenClaw-Version, die diese Konfiguration zuletzt geschrieben hat.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Markierungen für Konfigurationsmigrationen`},help:{"v1-burt8q-1q":`Begrenzte Kompatibilitätsmarkierungen für abgeschlossene Konfigurationsmigrationen.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Migration der Zulassungsliste für Modellrichtlinien`},help:{"v1-5psop1-1z":`Hält fest, dass ältere Einschränkungen der Modellzuordnung beibehalten oder ausgewertet wurden.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Migration zur Trennung von Hilfsmodellen`},help:{"v1-vzdfqx-2t":`Dokumentiert, dass bisherige implizite Primärmodelle vor der Trennung der Hilfsmodellauswahl beibehalten wurden.`}},models:{label:{"v1-hzmwb-6":`Modelle`},help:{"v1-1h1niol-5q":`Stammverzeichnis des Modellkatalogs für Anbieterdefinitionen, das Zusammenführungs-/Ersetzungsverhalten und die optionale Integration der Bedrock-Erkennung. Halten Sie Anbieterdefinitionen explizit und validieren Sie sie, bevor Sie sich im Produktionsbetrieb auf Failover-Pfade verlassen.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Modellkatalog-Aktualisierung`},help:{"v1-1hess4t-40":`Steuert Hintergrundaktualisierungen des mitgelieferten Modellkatalogs. Remote-Einträge können Modellmetadaten aktualisieren, aber keine Anbieterendpunkte oder Header ändern.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Modellkatalog-Aktualisierung aktiviert`},help:{"v1-1fogpjj-3j":`Aktualisierungen des gehosteten Modellkatalogs im Hintergrund abrufen (Standard: true). Setzen Sie den Wert auf false, um den gesamten Remote-Datenverkehr des Modellkatalogs zu deaktivieren.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL für die Modellkatalog-Aktualisierung`},help:{"v1-e02ai2-44":`Überschreibt die URL des gehosteten Modellkatalogs mit der eines selbst gehosteten HTTPS-Spiegels (HTTP auf localhost ist zu Testzwecken erlaubt). Änderungen werden nach einem Neustart des Gateway wirksam.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Modellkatalog-Modus`},help:{"v1-1ofrnsp-es":`Steuert das Verhalten des Anbieterkatalogs: "merge" behält integrierte Anbieter bei und überlagert sie mit Ihren benutzerdefinierten Anbietern, während "replace" nur Ihre konfigurierten Anbieter verwendet. Bei "merge" bleiben für übereinstimmende Anbieter-IDs nicht leere baseUrl-Werte aus der models.json des Agenten erhalten. apiKey-Werte bleiben dagegen nur erhalten, wenn der Anbieter im aktuellen Konfigurations-/Authentifizierungsprofilkontext nicht über SecretRef verwaltet wird. Über SecretRef verwaltete Anbieter aktualisieren apiKey anhand der aktuellen Quellmarkierungen. Bei übereinstimmenden Modellen wird für contextWindow/maxTokens der jeweils höhere Wert aus expliziten und impliziten Einträgen verwendet.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Modellanbieter`},help:{"v1-1y5jg0v-8p":`Nach Anbieter-ID gegliederte Anbieterzuordnung mit Verbindungs- und Authentifizierungseinstellungen sowie konkreten Modelldefinitionen. Integrierte Anbieter können durch Überschreibungen auf Anbieterebene angepasst werden; benutzerdefinierte Anbieter müssen baseUrl und models enthalten. Verwenden Sie stabile Anbieterschlüssel, damit Verweise aus Agenten und Werkzeugen umgebungsübergreifend portabel bleiben.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Laufzeit des Modellanbieters`},help:{"v1-1luy4fb-5o":`Optionale systemnahe Agenten-Laufzeitrichtlinie für diesen Anbieter. Verwenden Sie eine Laufzeitrichtlinie auf Anbieter- oder Modellebene statt einer agentenweiten Laufzeitfestlegung; bei Auslassung oder Verwendung des Standardwerts wählt OpenClaw die Laufzeit für den ausgewählten Anbieter.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`Laufzeit-ID des Modellanbieters`},help:{"v1-1gusd9s-69":`ID der Agentenlaufzeit des Anbieters: "openclaw", "auto", eine registrierte Plugin-Harness-ID wie "codex" oder ein unterstützter CLI-Backend-Alias wie "claude-cli". Bei OpenAI am offiziellen Endpunkt wird standardmäßig das Codex-Harness verwendet, wenn die Angabe fehlt.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`API-Adapter des Modellanbieters`},help:{"v1-16c28rb-57":`Auswahl des API-Adapters für den Anbieter, der die Kompatibilitätsbehandlung von Anfragen und Antworten bei Modellaufrufen steuert. Verwenden Sie den Adapter, der zum Protokoll Ihres vorgelagerten Anbieters passt, um Funktionsinkompatibilitäten zu vermeiden.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`API-Schlüssel des Modellanbieters`},help:{"v1-1p84k96-54":`Zugangsdaten des Anbieters für die API-Schlüssel-basierte Authentifizierung, wenn der Anbieter eine direkte Schlüsselauthentifizierung erfordert. Verwenden Sie die Ersetzung durch Secrets oder Umgebungsvariablen und vermeiden Sie es, echte Schlüssel in versionierten Konfigurationsdateien zu speichern.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Authentifizierungsmodus des Modellanbieters`},help:{"v1-1l1lwxr-5p":`Legt die Authentifizierungsart des Anbieters fest: "api-key" für die Authentifizierung per API-Schlüssel, "token" für die Authentifizierung per Bearer-Token, "oauth" für OAuth-Zugangsdaten und "aws-sdk" für die Ermittlung von AWS-Zugangsdaten. Passen Sie diese Einstellung an die Anforderungen Ihres Anbieters an.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Authorization-Header des Modellanbieters`},help:{"v1-1gn3lt3-59":`Bei true werden Zugangsdaten über den HTTP-Header Authorization gesendet, auch wenn eine alternative Authentifizierung möglich ist. Verwenden Sie dies nur, wenn Ihr Anbieter oder Proxy die Weiterleitung von Authorization ausdrücklich erfordert.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`Basis-URL des Modellanbieters`},help:{"v1-1ku88v8-53":`Basis-URL des Anbieterendpunkts, über den Modellanfragen für diesen Anbietereintrag verarbeitet werden. Verwenden Sie HTTPS-Endpunkte und halten Sie URLs bei Bedarf mithilfe von Konfigurationsvorlagen umgebungsspezifisch.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Header des Modellanbieters`},help:{"v1-chg59u-4x":`Statische HTTP-Header, die Anbieteranfragen für Mandantenrouting, Proxy-Authentifizierung oder benutzerdefinierte Gateway-Anforderungen hinzugefügt werden. Verwenden Sie diese sparsam und speichern Sie sensible Header-Werte in Secrets.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`num_ctx beim Modellanbieter einfügen (OpenAI-kompatibel)`},help:{"v1-53rmcr-6n":"Steuert, ob OpenClaw `options.num_ctx` für Ollama-Anbieter einfügt, die mit dem OpenAI-kompatiblen Adapter (`openai-completions`) konfiguriert sind. Der Standardwert ist true. Setzen Sie den Wert nur dann auf false, wenn Ihr Proxy oder Upstream unbekannte `options`-Felder in den Nutzdaten ablehnt."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Lokaler Dienst des Modellanbieters`},help:{"v1-19zkcow-4y":`Optionaler lokaler Modellserverprozess, der bei Bedarf für diesen Anbieter gestartet wird. OpenClaw prüft healthUrl, startet bei Bedarf den Befehl, wartet auf Betriebsbereitschaft und sendet dann die Modellanfrage.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Argumente des lokalen Dienstes des Modellanbieters`},help:{"v1-t12wib-27":`Argumentliste, die ohne Shell-Expansion an den Befehl für den lokalen Modellserver übergeben wird.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Befehl des lokalen Dienstes des Modellanbieters`},help:{"v1-1x6hz64-4j":`Absoluter Pfad zur ausführbaren Datei für den lokalen Modellserverprozess. Geben Sie diesen Pfad explizit an, damit der Start des Anbieters deterministisch erfolgt und nicht von der PATH-Suche der Shell abhängt.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Arbeitsverzeichnis des lokalen Dienstes des Modellanbieters`},help:{"v1-fi3xlx-1h":`Arbeitsverzeichnis für den lokalen Modellserverprozess.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Umgebung des lokalen Dienstes des Modellanbieters`},help:{"v1-1lwb9k1-3k":`Zusätzliche Umgebungsvariablen für den lokalen Modellserverprozess. Werte, die wie Geheimnisse aussehen, werden in Konfigurations-Snapshots unkenntlich gemacht.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL zur Zustandsprüfung des lokalen Dienstes des Modellanbieters`},help:{"v1-jv7aw-35":`URL zur Prüfung der Betriebsbereitschaft vor Modellanfragen. Wenn sie nicht angegeben ist, verwendet OpenClaw die baseUrl des Anbieters mit angehängtem /models.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Stopp des lokalen Dienstes des Modellanbieters bei Inaktivität`},help:{"v1-1efg054-3z":`Zeit in Millisekunden, die ein von OpenClaw gestarteter lokaler Modellserver nach Abschluss der letzten Anfrage weiterläuft. Auf 0 setzen, damit er bis zum Beenden von OpenClaw weiterläuft.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Bereitschaftszeitlimit für den lokalen Dienst des Modellanbieters`},help:{"v1-4gp0f0-2r":`Maximale Wartezeit in Millisekunden nach dem Prozessstart, bis die Bereitschaftsprüfung des lokalen Modellservers erfolgreich ist.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Maximale Tokenanzahl des Modellanbieters`},help:{"v1-fnj50y-38":`Standardmäßiges maximales Budget für Ausgabetokens, das für Modelle dieses Anbieters gilt, wenn ein Modelleintrag maxTokens nicht festlegt.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Modellliste des Modellanbieters`},help:{"v1-1vbm0gt-63":`Deklarierte Modellliste für einen Anbieter mit Kennungen, Metadaten, anbieterspezifischen Parametern und optionalen Hinweisen zu Kompatibilität und Kosten. IDs müssen exakt den Katalogwerten des Anbieters entsprechen, damit Auswahl und Fallback korrekt aufgelöst werden.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Modelllaufzeit`},help:{"v1-1k70g2n-3g":`Optionale systemnahe Agentenlaufzeit-Richtlinie für dieses spezifische Modell. Die Modelllaufzeit-Richtlinie hat Vorrang vor der Laufzeit-Richtlinie des Anbieters.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`Modelllaufzeit-ID`},help:{"v1-1llzv33-42":`ID der Agentenlaufzeit des Modells: "openclaw", "auto", eine registrierte Plugin-Harness-ID wie "codex" oder ein unterstützter CLI-Backend-Alias wie "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Medieneingabe des Modells`},help:{"v1-wxtj8e-2x":`Optionale Metadaten zu den Medienfähigkeiten des Modells, anhand derer Werkzeuge konservative Standardwerte für die Bildkomprimierung wählen.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Bildeingabe des Modells`},help:{"v1-1nviirq-3c":`Optionale Grenzwerte für die Bildeingabe dieses Modells, etwa maximale Seitenlänge, maximale Pixelanzahl und bevorzugte Seitenlänge für die Komprimierung.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Maximale Bildgröße des Modells in Bytes`},help:{"v1-c2469j-23":`Maximale Größe der kodierten Bilddaten, die der Anbieter für dieses Modell akzeptiert.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Maximale Bildpixelanzahl des Modells`},help:{"v1-9d6yqp-1u":`Maximale Pixelanzahl eines Bildes, die der Anbieter für dieses Modell akzeptiert.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Maximale Bildseitenlänge des Modells`},help:{"v1-1gbci08-1y":`Maximale Bildbreite oder Bildhöhe, die der Anbieter für dieses Modell akzeptiert.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Bevorzugte Bildseitenlänge des Modells`},help:{"v1-1u1mpcg-2x":`Bevorzugte Seitenlänge bei der Bildskalierung für eine ausgewogene Komprimierung. Nicht festlegen, um den konservativen Standardwert von OpenClaw zu verwenden.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Bild-Token-Modus des Modells`},help:{"v1-1oy6z7v-1z":`Methode des Anbieters zur Berechnung von Bild-Tokens: "tile", "detail" oder "provider".`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Laufzeitparameter des Modellanbieters`},help:{"v1-464sgu-4t":`Anbieterspezifische Laufzeitparameter, die von Anbieter-Plugins interpretiert werden. Verwenden Sie nur vom Anbieter dokumentierte Schlüssel und bevorzugen Sie die ausdrückliche Dokumentation des Anbieters gegenüber spontan getroffenen, anbieterübergreifenden Annahmen.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Region des Modellanbieters`},help:{"v1-yq7rxk-5h":`Optionale Bereitstellungs-/API-Region des Anbieters, die von Anbietern mit regionalen Endpunkten interpretiert wird. Unterstützte Werte finden Sie in der Dokumentation des Anbieters; baseUrl-Überschreibungen haben in der Regel Vorrang, wenn beide festgelegt sind.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Anfrageüberschreibungen für den Modellanbieter`},help:{"v1-1lkxryk-87":`Optionale Überschreibungen für Anfragen an Modellanbieter, einschließlich zusätzlicher Header, Authentifizierungsüberschreibungen, Proxy-Routing, TLS-Clienteinstellungen und optionalem allowPrivateNetwork für vertrauenswürdige, selbst gehostete Endpunkte. Verwenden Sie diese nur, wenn Ihr Upstream-Dienst oder der Netzwerkpfad in Ihrem Unternehmen eine Anpassung der Transportschicht erfordert.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Privates Netzwerk für Modellanbieter-Anfragen zulassen`},help:{"v1-1nbtcjk-fo":`Wenn true, erlaubt der HTTP-Fetch-Schutz des Anbieters (fetchWithSsrFGuard) HTTP-Anfragen an Modellanbieter in privaten, CGNAT- oder ähnlichen Adressbereichen. Benutzerdefinierte/lokale Basis-URLs von Anbietern vertrauen bereits dem exakt konfigurierten Ursprung, ausgenommen Metadaten-, Link-Local- und NAT64-Ursprünge für lokale Nutzung (64:ff9b:1::/48); setzen Sie dies auf false, um dieses Vertrauen zu deaktivieren. OpenAI Responses WebSocket verwendet request für Header/TLS wieder, nutzt jedoch nicht diesen Fetch-SSRF-Pfad. Verwenden Sie true nur für selbst gehostete, vom Betreiber kontrollierte Endpunkte, die private Ursprünge außerhalb des konfigurierten baseUrl-Ursprungs erreichen müssen.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Authentifizierungsüberschreibung für Modellanbieter-Anfragen`},help:{"v1-ucdgnf-1w":`Überschreibt das Authentifizierungsverhalten bei Anfragen an diesen Anbieter.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Name des Authentifizierungs-Headers für Modellanbieter-Anfragen`},help:{"v1-1881nqr-1i":`Benutzerdefinierter Name des Authentifizierungs-Headers, der verwendet wird, wenn der Authentifizierungsmodus header ist.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Authentifizierungsmodus für Modellanbieter-Anfragen`},help:{"v1-1lhv8hs-24":`Modus zur Authentifizierungsüberschreibung: "provider-default", "authorization-bearer" oder "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Präfix des Authentifizierungs-Headers für Modellanbieter-Anfragen`},help:{"v1-1rbm9lz-21":`Optionales Präfix, das request.auth.value vorangestellt wird, wenn der Authentifizierungsmodus header ist.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Bearer-Token für Modellanbieter-Anfragen`},help:{"v1-6rcasw-1l":`Bearer-Token, das verwendet wird, wenn der Authentifizierungsmodus authorization-bearer ist.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Wert des Authentifizierungsheaders für Modellanbieter-Anfragen`},help:{"v1-1v69ej-1j":`Benutzerdefinierter Wert des Authentifizierungsheaders, der verwendet wird, wenn der Authentifizierungsmodus header ist.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Header für Modellanbieter-Anfragen`},help:{"v1-zj3orj-2i":`Zusätzliche Header, die nach der standardmäßigen Zuordnung und der Ermittlung der Authentifizierung in Anbieteranfragen eingefügt werden.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Proxy für Modellanbieter-Anfragen`},help:{"v1-md5uj8-4j":`Optionale abweichende Proxy-Einstellung für Modellanbieter-Anfragen. Verwenden Sie "env-proxy", um die Proxy-Einstellungen der Umgebung zu berücksichtigen, oder "explicit-proxy", um Anfragen über eine bestimmte Proxy-URL zu leiten.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Proxy-Modus für Modellanbieter-Anfragen`},help:{"v1-1dx0ozg-29":`Modus für die abweichende Proxy-Einstellung bei Modellanbieter-Anfragen: "env-proxy" oder "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`Proxy-TLS für Modellanbieter-Anfragen`},help:{"v1-rdx62w-1v":`Optionale TLS-Einstellungen, die beim Verbindungsaufbau zum konfigurierten Proxy verwendet werden.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`Proxy-TLS-CA für Modellanbieter-Anfragen`},help:{"v1-11pg2fd-1s":`Benutzerdefiniertes CA-Bündel zur Überprüfung der TLS-Zertifikatskette des Proxys.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`Proxy-TLS-Zertifikat für Modellanbieter-Anfragen`},help:{"v1-x8nk2q-22":`Client-TLS-Zertifikat, das dem Proxy vorgelegt wird, wenn gegenseitige TLS-Authentifizierung erforderlich ist.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`TLS-Prüfung des Proxys für Modellanbieter-Anfragen überspringen`},help:{"v1-12vjdm9-2j":`Überspringt die Prüfung des TLS-Zertifikats des Proxys. Nur in kontrollierten Entwicklungsumgebungen verwenden.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`TLS-Schlüssel des Proxys für Modellanbieter-Anfragen`},help:{"v1-1skyr56-1w":`Privater Schlüssel, der zu request.proxy.tls.cert gehört und für die gegenseitige TLS-Authentifizierung mit dem Proxy verwendet wird.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`TLS-Passphrase des Proxys für Modellanbieter-Anfragen`},help:{"v1-wjvoxd-1m":`Optionale Passphrase zum Entschlüsseln von request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`TLS-Servername des Proxys für Modellanbieter-Anfragen`},help:{"v1-b4oabu-22":`Optionaler abweichender SNI-/Servername, der beim Aufbau der TLS-Verbindung zum Proxy verwendet wird.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`Proxy-URL für Modellanbieter-Anfragen`},help:{"v1-kvbgou-48":`Explizite Proxy-URL, die verwendet wird, wenn request.proxy.mode auf explicit-proxy gesetzt ist. In die URL eingebettete Zugangsdaten werden als vertraulich behandelt und in Snapshots unkenntlich gemacht.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS für Modellanbieter-Anfragen`},help:{"v1-16u7v7h-2b":`Optionale TLS-Einstellungen für direkte Verbindungen zum vorgelagerten Modellendpunkt.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`TLS-CA für Anfragen an den Modellanbieter`},help:{"v1-ny8y3e-1v":`Benutzerdefiniertes CA-Bundle zur Überprüfung der TLS-Zertifikatskette des vorgelagerten Endpunkts.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`TLS-Zertifikat für Anfragen an den Modellanbieter`},help:{"v1-1lltmhw-2e":`TLS-Clientzertifikat, das dem vorgelagerten Endpunkt bei erforderlicher gegenseitiger TLS-Authentifizierung vorgelegt wird.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`TLS-Überprüfung für Anfragen an den Modellanbieter überspringen`},help:{"v1-1006cuy-2m":`Überspringt die Überprüfung des TLS-Zertifikats des vorgelagerten Endpunkts. Nur in kontrollierten Entwicklungsumgebungen verwenden.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`TLS-Schlüssel für Anfragen an den Modellanbieter`},help:{"v1-w2agir-1t":`Privater Schlüssel, der zu request.tls.cert gehört und für die gegenseitige TLS-Authentifizierung mit dem vorgelagerten Endpunkt verwendet wird.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`TLS-Passphrase für Anfragen an den Modellanbieter`},help:{"v1-10ds42f-1g":`Optionale Passphrase zum Entschlüsseln von request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`TLS-Servername für Anfragen an den Modellanbieter`},help:{"v1-18yt7x9-1y":`Optionaler abweichender SNI-/Servername beim Aufbau einer TLS-Verbindung zum vorgelagerten Endpunkt.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Zeitlimit für Anfragen an den Modellanbieter`},help:{"v1-t3yn8l-ih":`Optionales Zeitlimit für Modellanfragen pro Anbieter in Sekunden. Anfrageeinstellungen auf Anbieterebene wirken sich auf explizite Modelleinträge des jeweiligen Anbieters aus; sie erstellen keine impliziten Modelle. Legen Sie diesen Wert bei benutzerdefinierten Anbietern zusammen mit baseUrl und models des Anbieters fest. Gilt für HTTP-Anfragen an den Anbieter, einschließlich Verbindungsaufbau, Header, Antwortinhalt und Abbruchbehandlung für die gesamte Anfrage. Außerdem wird die Obergrenze der LLM-Inaktivitäts- und Stream-Überwachung für diesen Anbieter über den impliziten Standardwert von ca. 120 Sekunden angehoben. Verwenden Sie diese Einstellung für langsame lokale oder selbst gehostete Modellserver oder für Cloud-Anbieter, die Reasoning-Tokens ohne laufende Datenübertragung puffern (Gemini Preview, Claude/Opus mit großen Tool-Nutzdaten), anstatt globale Agenten-Zeitlimits zu ändern.`}},nodeHost:{label:{"v1-nb8lk1-9":`Knoten-Host`},help:{"v1-8recuz-4z":`Node-Host-Einstellungen für Funktionen, die dieser Gateway-Knoten anderen Knoten oder Clients bereitstellt. Behalten Sie die Standardwerte bei, sofern Sie lokale Funktionen nicht gezielt über Ihr Knotennetzwerk weiterleiten möchten.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Agentenausführungen auf dem Knoten`},help:{"v1-4uz5ur-2k":`Aktivieren Sie native Agentenschritte mit Genehmigungspflicht auf diesem Node-Host ohne Benutzeroberfläche. Standardmäßig deaktiviert.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Claude-Agentenausführungen auf dem Knoten`},help:{"v1-g8az5y-2l":`Legt fest, ob dieser Node-Host ohne Benutzeroberfläche dem Gateway Agentenschritte über die Claude CLI als verfügbar melden darf.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Claude-Agentenausführungen auf dem Knoten aktiviert`},help:{"v1-1ke804l-44":`Meldet die Fortsetzung von Claude-Sitzungen auf gekoppelten Knoten als verfügbar, wenn die lokale claude-Binärdatei vorhanden ist (Standard: false). Ausführungen erfordern weiterhin eine Genehmigung zur Befehlsausführung auf dem Knoten.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Automatische Knoten-Updates`},help:{"v1-16xjk4e-5n":`Steuert automatische Updates der separaten Laufzeitumgebung für paketierte Headless-Knotenhosts. Prüft stündlich auf Updates und wartet vor einem Neustart, bis alle Knotenaufgaben abgeschlossen sind; automatische Neustarts erfolgen im Abstand von mindestens 12 Stunden.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Automatische Knoten-Updates aktiviert`},help:{"v1-1sa0yeg-7w":`Aktiviert automatische Updates aus stable oder beta für dauerhaft laufende, paketierte Headless-Knoten (Standard: true). Zum Deaktivieren auf false setzen. Wird auch durch update.checkOnStart=false oder OPENCLAW_NO_AUTO_UPDATE=1 deaktiviert; bei Quellcode-Checkouts, nativen Apps, privaten Workern, dev und extended-stable werden Updates nicht automatisch angewendet.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Browser-Proxy des Knotens`},help:{"v1-2xrew7-4f":`Bündelt Browser-Proxy-Einstellungen, um die lokale Browsersteuerung über Knoten-Routing bereitzustellen. Nur aktivieren, wenn Workflows auf entfernten Knoten Ihre lokalen Browserprofile benötigen.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Zulässige Profile des Knoten-Browser-Proxys`},help:{"v1-1ew5dkm-8b":`Optionale Positivliste der Browserprofilnamen, die über das Knoten-Proxy-Routing bereitgestellt werden. Leer lassen, um den standardmäßigen vollständigen Profilzugriff einschließlich der Routen zum Erstellen und Löschen von Profilen beizubehalten. Wenn festgelegt, beschränkt OpenClaw den Profilzugriff auf die geringstmöglichen Berechtigungen und blockiert das Erstellen und Löschen persistenter Profile über den Proxy.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Knoten-Browser-Proxy aktiviert`},help:{"v1-pa04pd-5b":`Stellt den lokalen Browsersteuerungsserver über das Knoten-Proxy-Routing bereit, damit entfernte Clients die Browserfunktionen dieses Hosts nutzen können. Deaktiviert lassen, sofern die Remote-Automatisierung nicht ausdrücklich darauf angewiesen ist.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`MCP des Knoten-Hosts`},help:{"v1-1mdhrwl-48":`Verwendet MCP-Server, die vom Knoten-Host ohne grafische Oberfläche gestartet und für das gekoppelte Gateway bereitgestellt werden, als Agentenwerkzeuge. Starten Sie den Knoten-Host nach Änderungen an diesem Abschnitt neu.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`MCP-Server des Knoten-Hosts`},help:{"v1-19m002f-3x":`Benannte MCP-Serverdefinitionen, die lokal auf diesem Knoten vorliegen. Verwendet dieselbe Serverstruktur wie mcp.servers; OAuth-Server werden vom Knoten-Host nicht unterstützt.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Skills des Knoten-Hosts`},help:{"v1-v8txza-41":`Verwenden Sie diesen Abschnitt, um die unter ~/.openclaw/skills installierten Skills vom Knoten-Host ohne grafische Oberfläche bereitzustellen. Starten Sie den Knoten-Host nach Änderungen an Skill-Dateien neu.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Skills des Knoten-Hosts aktiviert`},help:{"v1-1ggpkqb-36":`Auf dem Knoten gehostete Skills nach dem Verbindungsaufbau suchen und veröffentlichen (Standard: true). Auf false setzen, um die Veröffentlichung von Skills des Knotens zu deaktivieren.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Worker-Ausführungen auf dem Knoten`},help:{"v1-1w83rox-2p":`Vollständiges Hosting von OpenClaw-Worker-Sitzungen aus vom Gateway verwalteten Bundles aktivieren. Standardmäßig deaktiviert.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Kapazität für Worker-Ausführungen auf dem Knoten`},help:{"v1-10nvk8f-3w":`Maximale Anzahl gleichzeitiger Worker-Sitzungen, die dieser Knoten hostet (Standard: Anzahl der verfügbaren CPU-Kerne). Muss eine ganze Zahl zwischen 1 und 1024 sein.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Container-Image für Worker-Ausführungen auf dem Knoten`},help:{"v1-1oqx50o-5t":`Optionales Image mit Node 24.16+ oder 26.1+ für in Containern isolierte Worker (Standard: "node:24.19.0-slim"). Bei Bedarf ein per Digest fixiertes Image, ein Image aus einer privaten Registry oder ein vorab geladenes Image verwenden; fehlende Images werden bei der ersten Verwendung heruntergeladen.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Worker-Ausführungen auf dem Knoten aktiviert`},help:{"v1-b3t0xp-2t":`Diesem gekoppelten Knoten erlauben, Sitzungen aus exakt den Bundles zu hosten, die sein Gateway installiert hat (Standard: false).`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Isolation der Worker-Ausführungen auf dem Knoten`},help:{"v1-19i6swo-58":`Prozessgrenze für Worker-Sitzungen auswählen: "none" führt sie direkt auf dem Knotenhost aus (Standard); "container" erfordert eine funktionsfähige Docker-kompatible Engine und fällt niemals auf die Ausführung auf dem Host zurück.`}},plugins:{label:{"v1-10renyj-7":`Plugins`},help:{"v1-1qbev2k-5c":`Steuerung des Plugin-Systems zum Aktivieren von Erweiterungen, Begrenzen des Ladeumfangs, Konfigurieren von Einträgen und Nachverfolgen von Installationen. Plugin-Richtlinien in Produktionsumgebungen explizit festlegen und Berechtigungen auf das erforderliche Minimum beschränken.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Plugin-Zulassungsliste`},help:{"v1-pupwbe-7z":`Optionale Zulassungsliste mit Plugin-IDs. Wenn sie festgelegt ist, können nur aufgeführte Plugins geladen werden. Konfigurierte integrierte Chatkanäle können ihr mitgeliefertes Plugin weiterhin aktivieren, wenn der Kanal in der Konfiguration ausdrücklich aktiviert ist. Verwenden Sie diese Option, um in kontrollierten Umgebungen ausschließlich genehmigte Erweiterungen zuzulassen.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Plugin-Sperrliste`},help:{"v1-4gyt4z-4i":`Optionale Sperrliste mit Plugin-IDs, die auch dann blockiert werden, wenn sie in Zulassungslisten oder Pfaden enthalten sind. Verwenden Sie Sperrregeln für Notfall-Rollbacks und die konsequente Sperrung riskanter Plugins.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Plugins aktivieren`},help:{"v1-pnygd7-50":`Aktiviert oder deaktiviert das Laden von Plugins und Erweiterungen global beim Start und beim erneuten Laden der Konfiguration (Standard: true). Lassen Sie diese Option nur aktiviert, wenn Ihre Bereitstellung Erweiterungsfunktionen benötigt.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Plugin-Einträge`},help:{"v1-cn74rf-54":`Einstellungen pro Plugin, zugeordnet nach Plugin-ID, einschließlich Aktivierung und Plugin-spezifischer Laufzeitkonfigurationsdaten. Verwenden Sie diese Option zur gezielten Anpassung einzelner Plugins, ohne die globale Laderichtlinie zu ändern.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Plugin-API-Schlüssel`},help:{"v1-ctytg2-53":`Optionales API-Schlüsselfeld für Plugins, die eine direkte Schlüsselkonfiguration in den Eintragseinstellungen unterstützen. Verwenden Sie die Ersetzung durch Secrets oder Umgebungsvariablen und vermeiden Sie es, echte Zugangsdaten in Konfigurationsdateien einzuchecken.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Plugin-Konfiguration`},help:{"v1-1he672p-51":`Vom Plugin definierte Konfigurationsdaten, die anhand des eigenen Schemas und der Validierungsregeln des Plugins interpretiert werden. Verwenden Sie nur dokumentierte Felder des Plugins, um ignorierte oder ungültige Einstellungen zu vermeiden.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Plugin aktiviert`},help:{"v1-12soc0h-9a":`Pluginspezifische Aktivierungseinstellung für einen bestimmten Eintrag, die Vorrang vor der globalen Plugin-Richtlinie hat. Im standardmäßigen hybriden Neulademodus wird die Plugin-Laufzeit bei Änderungen für neue Agentendurchläufe ohne Neustart des Gateway neu geladen, es sei denn, das Plugin erfordert für diesen Pfad einen Neustart. Damit können Sie Plugins schrittweise in verschiedenen Umgebungen einführen.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Plugin-Umgebungsvariablen`},help:{"v1-p39pu4-52":`Pluginspezifische Zuordnung von Umgebungsvariablen, die nur in den Laufzeitkontext dieses Plugins eingefügt wird. Damit können Sie Anbieter-Zugangsdaten auf ein einzelnes Plugin beschränken, statt die globale Prozessumgebung gemeinsam zu nutzen.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Plugin-Hook-Richtlinie`},help:{"v1-1oslnrf-4c":`Pluginspezifische Richtlinieneinstellungen für typisierte Hooks mit Sicherheitsprüfungen, die vom Kernsystem durchgesetzt werden. Damit können Sie Hook-Kategorien mit weitreichenden Auswirkungen einschränken, ohne das gesamte Plugin zu deaktivieren.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Hooks mit Gesprächszugriff zulassen`},help:{"v1-xqz31z-7e":"Legt fest, ob dieses Plugin unverarbeitete Gesprächsinhalte aus typisierten Hooks wie `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` und `agent_end` lesen darf. Bei nicht mitgelieferten Plugins muss dieser Zugriff ausdrücklich aktiviert werden."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`Hooks zur Prompt-Injektion zulassen`},help:{"v1-7y6cny-32":"Legt fest, ob dieses Plugin Prompts über typisierte Hooks verändern darf. Setzen Sie den Wert auf false, um `before_prompt_build` zu blockieren."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Zeitlimit für Plugin-Hooks (ms)`},help:{"v1-4ra6b7-74":`Standardzeitlimit in Millisekunden für die typisierten Hooks dieses Plugins, begrenzt auf 600000. Wenn kein Wert festgelegt ist, verwendet jeder Hook das vom Plugin deklarierte Zeitlimit oder die hookspezifische Richtlinie des Gateway; es gibt keinen einheitlichen festen Standardwert. Hookspezifische Werte in hooks.timeouts haben Vorrang.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Abweichende Zeitlimits für Plugin-Hooks`},help:{"v1-yphl9b-5s":`Hookspezifische Zeitlimits in Millisekunden, mit dem Namen des typisierten Hooks als Schlüssel, begrenzt auf 600000. Verwenden Sie gezielte Anpassungen für bekanntermaßen langsame Hooks wie before_prompt_build oder agent_end, statt alle Hook-Zeitlimits zu erhöhen.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`LLM-Richtlinie für Plugins`},help:{"v1-dlca6c-4j":`Pluginspezifische Steuerung von api.runtime.llm.complete für die Berechtigung zum Überschreiben von Modell und Agent. Lassen Sie diese Einstellung ungesetzt, sofern ein Plugin nicht ausdrücklich vom Host verwaltete Vervollständigungsaufrufe steuern muss.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`LLM-Agent-Überschreibung durch Plugin erlauben`},help:{"v1-k8c08b-4n":`Erlaubt diesem Plugin ausdrücklich, api.runtime.llm.complete mit einer vom Standard abweichenden Agent-ID aufzurufen. Behalten Sie false bei, sofern dem Plugin kein agentübergreifender Modellzugriff anvertraut wird.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`LLM-Authentifizierungsprofil-Überschreibung durch Plugin erlauben`},help:{"v1-9ityw9-4x":`Erlaubt diesem Plugin, für isolierte Vervollständigungen in der Agent-Laufzeit ein vom Standard abweichendes Authentifizierungsprofil auszuwählen. Behalten Sie false bei, sofern dem Plugin keine explizite, isolierte Weiterleitung von Zugangsdaten anvertraut wird.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Zulässige LLM-Vervollständigungsmodelle für Plugins`},help:{"v1-1ul08he-54":`Zulässige Ziele für jede LLM-Vervollständigung des Plugins als kanonische "provider/model"-Referenzen, einschließlich der vom Host aufgelösten Standardwerte und Überschreibungen. Verwenden Sie "*" nur, wenn Sie bewusst jedes Modell zulassen möchten.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Zulässige LLM-Modelle für das Plugin`},help:{"v1-154sk45-47":`Zulässige Überschreibungsziele für vertrauenswürdige LLM-Aufrufe des Plugins als kanonische "provider/model"-Referenzen. Verwenden Sie "*" nur, wenn Sie bewusst jede Modellüberschreibung zulassen möchten.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`LLM-Modellüberschreibung durch das Plugin zulassen`},help:{"v1-uw4jmc-47":`Erlaubt diesem Plugin ausdrücklich, Modellüberschreibungen in api.runtime.llm.complete anzufordern. Behalten Sie false bei, sofern dem Plugin nicht die Steuerung der Modellauswahl anvertraut wird.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Subagentenrichtlinie für das Plugin`},help:{"v1-wbf4m1-4d":`Pluginspezifische Laufzeiteinstellungen für Subagenten zur Vertrauenswürdigkeit von Modellüberschreibungen und zu Zulassungslisten. Lassen Sie dies ungesetzt, sofern ein Plugin die Modellauswahl für Subagenten nicht ausdrücklich steuern muss.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Zulässige Subagentenmodelle für das Plugin`},help:{"v1-2pvkow-42":`Zulässige Überschreibungsziele für vertrauenswürdige Subagentenausführungen des Plugins als kanonische "provider/model"-Referenzen. Verwenden Sie "*" nur, wenn Sie bewusst jedes Modell zulassen möchten.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Subagenten-Modellüberschreibung durch das Plugin zulassen`},help:{"v1-1r5tzm1-4g":`Erlaubt diesem Plugin ausdrücklich, Anbieter- und Modellüberschreibungen für Subagent-Ausführungen im Hintergrund anzufordern. Behalten Sie false bei, sofern dem Plugin nicht die Steuerung der Modellauswahl anvertraut wird.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Plugin-Lader`},help:{"v1-1myjwbi-52":`Konfigurationsgruppe des Plugin-Laders zur Angabe von Dateisystempfaden, in denen nach Plugins gesucht wird. Geben Sie Ladepfade explizit an und überprüfen Sie diese, um das versehentliche Laden nicht vertrauenswürdiger Erweiterungen zu vermeiden.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Plugin-Ladepfade`},help:{"v1-o689p1-4z":`Zusätzliche Plugin-Dateien oder Verzeichnisse, die der Lader neben den integrierten Standardpfaden durchsucht. Verwenden Sie dedizierte Erweiterungsverzeichnisse und vermeiden Sie weit gefasste Pfade mit nicht zugehörigen ausführbaren Inhalten.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Plugin-Slots`},help:{"v1-zx6crl-5f":`Legt fest, welche Plugins exklusive Laufzeit-Slots wie etwa für das Gedächtnis belegen, sodass nur ein Plugin die jeweilige Funktion bereitstellt. Weisen Sie Slots explizit zu, um sich überschneidende Anbieter mit widersprüchlichem Verhalten zu vermeiden.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`Kontext-Engine-Plugin`},help:{"v1-4v13iw-2t":`Wählt das aktive Kontext-Engine-Plugin anhand seiner ID aus, sodass ein einziges Plugin die Kontextorchestrierung übernimmt.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Gedächtnis-Plugin`},help:{"v1-80ngcl-23":`Wählen Sie das aktive Gedächtnis-Plugin anhand seiner ID aus oder verwenden Sie "none", um Gedächtnis-Plugins zu deaktivieren.`}},presence:{label:{"v1-10fdwo4-8":`Präsenz`}},proxy:{label:{"v1-ji57pa-d":`Verwalteter Proxy`},help:{"v1-vui6bx-58":`Vom Betreiber verwaltetes Forward-Proxy-Routing für HTTP-, HTTPS- und WebSocket-Verbindungen sowie unterstützte direkte ausgehende Verbindungen der OpenClaw-Laufzeit. Verwenden Sie dies, wenn eine zentrale Kontrolle des ausgehenden Datenverkehrs Teil der Bereitstellungsgrenze ist.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Verwalteter Proxy aktiviert`},help:{"v1-1456xdw-49":`Explizite Überschreibung für den verwalteten Proxy. Eine vorhandene URL aktiviert standardmäßig das Routing; setzen Sie den Wert auf false, um konfigurierte oder über Umgebungsvariablen festgelegte Proxy-URLs zu ignorieren, ohne sie zu löschen.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Loopback-Modus des verwalteten Proxys`},help:{"v1-1kaiuh0-3c":`Steuert das Loopback-Routing der Gateway-Steuerungsebene, während der Modus für den verwalteten Proxy aktiv ist: "gateway-only", "proxy" oder "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL des verwalteten Proxys`},help:{"v1-p36b5l-3v":`URL des verwalteten Forward-Proxys. Verwenden Sie http:// für einen unverschlüsselten CONNECT-Proxy oder https://, wenn die Verbindung zum Proxy-Endpunkt selbst TLS verwenden muss.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS des verwalteten Proxys`},help:{"v1-6i0vu-3q":`TLS-Einstellungen für die Verbindung zum verwalteten Proxy-Endpunkt. Diese Einstellungen gelten für Proxy-TLS, nicht für das TLS der Zielverbindung nach CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`TLS-CA-Datei des verwalteten Proxys`},help:{"v1-1ntzjia-2p":`Dateisystempfad zu einem benutzerdefinierten CA-Bundle, das zur Überprüfung des Zertifikats eines verwalteten HTTPS-Proxy-Endpunkts verwendet wird.`}},secrets:{label:{"v1-1sihgpy-7":`Geheimnisse`},help:{"v1-jgn0o9-2l":`Anbieter für Geheimnisreferenzen, Verhalten des gemeinsamen Speichers und optionaler Schutz für ausgehenden Datenverkehr von Unterprozessen.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Ausgangsproxy für Geheimnisse`},help:{"v1-1qfgid-4n":`Vom Gateway verwalteter Loopback-Proxy, der Geheimnisplatzhalter aus dem gemeinsamen Speicher erst beim Senden ausgehender Anfragen ersetzt. Starten Sie das Gateway neu, nachdem Sie diesen nur beim Start eingelesenen Abschnitt geändert haben.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Zulässige Hosts für den Ausgangsproxy für Geheimnisse`},help:{"v1-9ypodl-6t":`Optionale Zulassungsliste für Anfragen und CONNECT-Tunnel. Wenn sie vorhanden ist, müssen Ziele in dieser Liste, in einer Hostbindung für ein einzelnes Geheimnis oder in bypassHosts aufgeführt sein. Eine leere Liste erlaubt nur gebundene oder von der Verarbeitung ausgenommene Hosts. Starten Sie den Gateway nach Änderungen neu.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Ausnahmehosts des Egress-Proxys für Geheimnisse`},help:{"v1-1oiiomv-57":`Exakte Hostnamen, die authentifizierte blinde CONNECT-Tunnel für Clients mit Zertifikats-Pinning verwenden. Sentinel-Werte bleiben verschlüsselt und führen zu einem Fehler bei der Anbieterauthentifizierung, statt Klartext offenzulegen.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Egress-Proxy für Geheimnisse aktiviert`},help:{"v1-u99b1i-2h":`Aktiviert die Ersetzung von Geheimnissen im ausgehenden Datenverkehr für Agenten-Unterprozesse, die vom Gateway gehostet werden. Standard: false.`}},session:{label:{"v1-8yh9jr-7":`Sitzung`},help:{"v1-j86s32-5d":`Globale Einstellungen für Sitzungsrouting, Zurücksetzen, Zustellungsrichtlinien und Wartung zur Steuerung des Gesprächsverlaufs. Behalten Sie die Standardwerte bei, sofern Sie keine strengeren Vorgaben für Isolation, Aufbewahrung oder Zustellung benötigen.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Sitzungsumfang für Direktnachrichten`},help:{"v1-ql362c-5l":`Sitzungsumfang für Direktnachrichten: "main" bewahrt die Kontinuität, während "per-peer", "per-channel-peer" und "per-account-channel-peer" die Isolation erhöhen. Verwenden Sie isolierte Modi für gemeinsam genutzte Posteingänge oder Bereitstellungen mit mehreren Konten.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Sitzungsumfang für Gruppen`},help:{"v1-1fdezx2-6i":`Sitzungsumfang für Gruppen/Kanäle: "per-group" hält Räume getrennt, während die Hauptsitzung des Agenten sie unabhängig von dmScope im Hintergrund beobachtet; "main" führt den Raumkontext in der Hauptsitzung zusammen und benötigt keine Beobachtung. Verwenden Sie "main" nur für vertrauenswürdige Räume.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Identitätsverknüpfungen für Sitzungen`},help:{"v1-1y5jnsm-5n":`Ordnet kanonischen Identitäten Peer-IDs mit Anbieterpräfix zu, damit dieselben Benutzer einem einzigen Direktnachrichten-Thread zugeordnet werden (Beispiel: telegram:123456). Verwenden Sie dies, wenn dieselbe Person über mehrere Kanäle oder Konten auftritt.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Hauptschlüssel der Sitzung`},help:{"v1-18p638h-3q":`Wird akzeptiert, aber ignoriert: Das Suffix der Hauptsitzung pro Agent lautet immer "main". Lassen Sie dieses Feld weg; der globale Sitzungsbereich verwendet stattdessen "global".`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Sitzungswartung`},help:{"v1-imr441-66":`Einstellungen für die automatische Wartung des Sitzungsspeichers: Dashboard-Archivierung, Altersgrenze für die Bereinigung, maximale Eintragszahl, Aufbewahrung von Archiven nach dem Zurücksetzen und Bereinigung bei Überschreitung des Speicherplatzbudgets. Beginnen Sie im Modus warn, um die Auswirkungen zu beobachten, und wechseln Sie nach Anpassung der Schwellenwerte zu enforce.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Inaktive Dashboard-Sitzungen archivieren nach`},help:{"v1-1frdtub-5n":"Archiviert inaktive Dashboard-Sitzungen nach dieser Dauer (zum Beispiel `7d`), damit sie verfügbar bleiben, ohne die Liste der aktiven Sitzungen zu überladen. Setzen Sie den Wert auf `false` oder `0`, um die automatische Dashboard-Archivierung zu deaktivieren."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`Langzeitarchivierung von Transkripten`},help:{"v1-1kp9s9h-5s":`Verschiebt inaktive Transkripte in komprimierte JSONL-Archive und behält dabei die Sitzungsmetadaten bei. Archivdateien werden zu einem erforderlichen Bestandteil des Verlaufs und müssen in Sicherungen enthalten sein. Änderungen werden ohne Neustart des Gateway wirksam.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Nach inaktiven Tagen archivieren`},help:{"v1-zay1q3-5b":`Transkripte nach dieser Anzahl inaktiver Tage archivieren (positive Ganzzahl, Standardwert 30). Aktive Arbeit bleibt geschützt; Änderungen am Schwellenwert werden beim nächsten Worker-Durchlauf ohne Neustart des Gateway wirksam.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`Alte Transkripte automatisch archivieren`},help:{"v1-6p6vmb-5a":`Aktiviert die Archivierung von Transkripten im Hintergrund (Standard: false). Ein Hintergrundprozess prüft jede Minute, welche Transkripte dafür infrage kommen. Diese explizite Archivierungsrichtlinie ist unabhängig von der Löschung und der Bereinigung zur Einhaltung des Speicherplatzbudgets.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Zielwert für die Sitzungsspeicherbelegung`},help:{"v1-143vh09-7z":`Zielgröße nach der Bereinigung zur Einhaltung des Speicherplatzbudgets (obere Grenze). Standardmäßig 80 % von maxDiskBytes; legen Sie den Wert explizit fest, um bei begrenztem Speicherplatz mehr Platz freizugeben. Ein Wert, der null ergibt, fällt auf den Standardwert zurück; negative Werte sind ungültig. Deaktivieren Sie das Budget stattdessen mit maxDiskBytes.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Maximales Speicherplatzbudget für Sitzungen`},help:{"v1-147lxk3-cj":'Physisches Speicherplatzbudget pro Agent für SQLite-Hauptdatei/WAL und berücksichtigte Artefakte im Sitzungsverzeichnis (zum Beispiel `500mb`). Standardwert ist `10gb`; geschützte Daten können dazu führen, dass die Nutzung über dem Zielwert bleibt. Bei Überschreitung meldet der Modus "warn" den Speicherplatzdruck, während der Modus "enforce" zuerst alte Zurücksetzungs-/Lösch-Artefakte, dann nicht referenzierte Verläufe und anschließend durch die Eintragsbegrenzung erstellte Archive entfernt. Manuelle, altersbedingt aufbewahrte, Dashboard-, Wiederherstellungs- und Legacy-Archive bleiben geschützt. Zum Deaktivieren `false`, `0` oder `"0"` festlegen.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Maximale Sitzungseinträge`},help:{"v1-1w2egrh-7u":`Begrenzt nicht archivierte Sitzungseinträge (Standardwert: 5000). Geeignete, dauerhaft aufzubewahrende Unterhaltungen oberhalb der Grenze werden mit ihrem Verlauf archiviert; entbehrliche Automatisierungseinträge werden entfernt. Vorhandene Archive werden nicht auf die Grenze angerechnet. Geschützte aktive Einträge zählen weiterhin mit und können dazu führen, dass der Bestand über der Grenze bleibt.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Sitzungswartungsmodus`},help:{"v1-bq39hk-6v":`Legt fest, ob Richtlinien zur Bereinigung und zum Speicherplatzbudget nur gemeldet ("warn") oder aktiv angewendet ("enforce") werden. Behalten Sie während der Einführung "warn" bei und wechseln Sie nach der Überprüfung sicherer Schwellenwerte zu "enforce". Die Langzeitarchivierung verfügt über eine eigene explizite enabled-Einstellung.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Kürzlich aktive Sitzungen beibehalten`},help:{"v1-138q5wx-89":"Schützt interaktive Sitzungen, die innerhalb dieses Zeitraums (zum Beispiel `7d`) aktiv waren, vor der automatischen Entfernung ihres Verlaufs aufgrund von Alter, Anzahl oder Speicherplatzbudget. Wenn nicht gesetzt oder auf `false` gesetzt, gilt weiterhin die normale Richtlinie „Älteste zuerst“. Synthetische Einträge für Modellläufe, cron, Hooks, Heartbeats, ACP und Unteragenten kommen weiterhin für eine begrenzte Bereinigung infrage."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Sitzungen bereinigen nach`},help:{"v1-1xn50w7-76":"Archiviert geeignete dauerhafte Unterhaltungen und entfernt temporäre Automatisierungseinträge, die älter als diese Zeitspanne sind (Standard: `30d`; zum Beispiel `12h`). Archivierte Unterhaltungen behalten ihren Verlauf und können wiederhergestellt werden; geschützte oder routbare Unterhaltungen bleiben aktiv."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Archivaufbewahrung bei Sitzungszurücksetzung`},help:{"v1-16amrs1-7r":"Altersbasierte Aufbewahrung archivierter Transkripte (`*.reset.<timestamp>` und `*.deleted.<timestamp>`). Standardmäßig werden Archive aufbewahrt, bis das Speicherplatzlimit ihre Entfernung erfordert, beginnend mit den ältesten. Legen Sie eine Zeitspanne fest (zum Beispiel `30d`), um die Löschung nach Ablauf dieser Zeit zu aktivieren, oder setzen Sie `false`, um sie ausdrücklich zu deaktivieren."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Home bei Sitzungserstellung benachrichtigen`},help:{"v1-c4prn5-8b":`Bei der Erstellung einer Sitzung eine Systembenachrichtigung in die Warteschlange der Home-Sitzung des zuständigen Agenten stellen (Standard: true). Benachrichtigungen enthalten verfügbare Metadaten zu Titel und Ersteller und werden beim nächsten Home-Durchlauf oder Heartbeat gelesen. Zum Deaktivieren auf false setzen; Entwürfe, Inkognito-Sitzungen, interne Sitzungen und geplante Cron-Ausführungen sind ausgeschlossen.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Richtlinie zur Sitzungszurücksetzung`},help:{"v1-1hmt7n3-6r":`Definiert das Standardobjekt für die Zurücksetzungsrichtlinie, das verwendet wird, wenn keine typ- oder kanalspezifische Überschreibung greift. Standardmäßig werden Sitzungen nicht automatisch zurückgesetzt. Aktivieren Sie dies über tägliche oder inaktivitätsbasierte Zeitpläne; /new und /reset bleiben jederzeit verfügbar.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Uhrzeit der täglichen Sitzungszurücksetzung`},help:{"v1-wry8cv-59":`Legt die lokale Stunde (0–23) für den täglichen Zurücksetzungsmodus fest, damit Sitzungen zu vorhersehbaren Zeiten neu beginnen. Verwenden Sie dies mit mode=daily und richten Sie die Uhrzeit an der vom Betreiber erwarteten Zeitzone aus, um ein nachvollziehbares Verhalten zu gewährleisten.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Inaktivitätsminuten bis zur Sitzungszurücksetzung`},help:{"v1-1kzj0id-5e":`Legt die Inaktivitätsdauer vor einer Zurücksetzung im Inaktivitätsmodus fest und kann im täglichen Modus auch als zusätzliche Absicherung dienen. Verwenden Sie größere Werte, um die Kontinuität zu bewahren, oder kleinere Werte für aktuellere, kurzlebige Gesprächsverläufe.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Modus der Sitzungszurücksetzung`},help:{"v1-e5ie4w-5b":`Legt die Zurücksetzungsstrategie fest: "none" deaktiviert das automatische Zurücksetzen (Standard), "daily" setzt zu einer konfigurierten Uhrzeit zurück und "idle" setzt nach Inaktivität zurück. /new und /reset bleiben in jedem Modus verfügbar.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Sitzungszurücksetzung nach Kanal`},help:{"v1-1uxsulx-5h":`Ermöglicht kanalspezifische Ausnahmen für das Zurücksetzen, zugeordnet nach Anbieter-/Kanal-ID, um das Verhalten gezielt zu steuern. Verwenden Sie dies nur, wenn ein Kanal ein besonderes Zurücksetzungsverhalten benötigt, das über die Richtlinien auf Typebene hinausgeht.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Sitzungszurücksetzung nach Chattyp`},help:{"v1-ypdr7u-52":`Überschreibt das Zurücksetzungsverhalten nach Chattyp (direct, group, thread), wenn die Standardeinstellungen nicht ausreichen. Verwenden Sie dies, wenn Gruppen- oder Thread-Unterhaltungen einen anderen Zurücksetzungsrhythmus als Direktnachrichten benötigen.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Sitzungszurücksetzung (Direktchat)`},help:{"v1-fjnlp5-56":`Definiert die Zurücksetzungsrichtlinie für Direktchats und ersetzt für diesen Typ die Basiskonfiguration session.reset. Verwenden Sie dies als maßgebliche Einstellung für Direktnachrichten anstelle des veralteten Alias dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Sitzungszurücksetzung (Gruppe)`},help:{"v1-hl1200-4u":`Definiert die Zurücksetzungsrichtlinie für Gruppenchat-Sitzungen, bei denen sich Kontinuität und das Aufkommen irrelevanter Nachrichten von Direktnachrichten unterscheiden. Verwenden Sie für aktive Gruppen kürzere Inaktivitätszeiträume, wenn das Abdriften des Kontexts zum Problem wird.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Sitzungszurücksetzung (Thread)`},help:{"v1-1hgpeke-4w":`Definiert die Zurücksetzungsrichtlinie für auf Threads beschränkte Sitzungen, einschließlich gezielter Arbeitsabläufe in Kanal-Threads. Verwenden Sie dies, wenn Thread-Sitzungen schneller oder langsamer als andere Chattypen ablaufen sollen.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Auslöser zum Zurücksetzen von Sitzungen`},help:{"v1-rcabsw-5a":`Listet Nachrichtenauslöser auf, die beim Erkennen in eingehenden Inhalten eine Sitzung zurücksetzen. Verwenden Sie diese sparsam für eindeutige Formulierungen zum Zurücksetzen, damit der Kontext während normaler Gespräche nicht unerwartet verloren geht.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Sitzungsumfang`},help:{"v1-axt4ds-5z":`Legt die grundlegende Strategie zur Gruppierung von Sitzungen fest: "per-sender" trennt nach Absender, während "global" eine gemeinsame Sitzung pro Kanalkontext verwendet. Behalten Sie "per-sender" für einen sichereren Mehrbenutzerbetrieb bei, sofern nicht ausdrücklich ein gemeinsamer Kontext erforderlich ist.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Senderichtlinie für Sitzungen`},help:{"v1-17qpipb-5l":`Steuert sitzungsübergreifende Sendeberechtigungen anhand von Erlaubnis- und Verbotsregeln, die nach Kanal, chatType und Schlüsselpräfixen ausgewertet werden. Damit können Sie in komplexen Umgebungen einschränken, wohin Sitzungswerkzeuge Nachrichten senden dürfen.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Standardaktion der Senderichtlinie für Sitzungen`},help:{"v1-15plhut-53":`Legt die Ausweichaktion fest, wenn keine sendPolicy-Regel zutrifft: "allow" oder "deny". Behalten Sie "allow" für einfachere Konfigurationen bei oder wählen Sie "deny", wenn Sie für jedes Ziel eine ausdrückliche Erlaubnisregel benötigen.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Regeln der Senderichtlinie für Sitzungen`},help:{"v1-o217za-5h":'Geordnete Erlaubnis- und Verbotsregeln, die vor der Standardaktion ausgewertet werden, zum Beispiel `{ action: "deny", match: { channel: "discord" } }`. Platzieren Sie die spezifischsten Regeln zuerst, damit allgemeine Regeln keine Ausnahmen überlagern.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Aktion der Senderegel für Sitzungen`},help:{"v1-178vm80-54":`Legt die Regelentscheidung als "allow" oder "deny" fest, wenn die entsprechenden Abgleichkriterien erfüllt sind. Ordnen Sie deny-Regeln zuerst an, wenn strikte Grenzen mit expliziten allow-Ausnahmen durchgesetzt werden sollen.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Abgleichbedingungen der Sitzungs-Senderegel`},help:{"v1-18qh5qg-5d":`Definiert optionale Abgleichbedingungen für Regeln, die Einschränkungen für channel, chatType und Schlüsselpräfixe kombinieren können. Halten Sie die Bedingungen eng gefasst, damit die Absicht der Richtlinie nachvollziehbar und die Fehlersuche unkompliziert bleibt.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Kanal der Sitzungs-Senderegel`},help:{"v1-u5erwx-50":`Beschränkt die Anwendung der Regel auf eine bestimmte Kanal-/Anbieter-ID (zum Beispiel discord, telegram, slack). Verwenden Sie dies, wenn ein Kanal die Zustellung unabhängig von anderen erlauben oder verweigern soll.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Chattyp der Sitzungs-Senderegel`},help:{"v1-7cv4f9-4z":`Beschränkt die Anwendung der Regel auf den Chattyp (direct, group, thread), sodass das Verhalten je nach Gesprächsform variiert. Verwenden Sie dies, wenn Direktnachrichten und Gruppenziele unterschiedliche Sicherheitsgrenzen erfordern.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Schlüsselpräfix der Sitzungs-Senderegel`},help:{"v1-ac4dee-5n":`Gleicht ein normalisiertes Sitzungsschlüsselpräfix nach den internen Schlüsselnormalisierungsschritten in richtlinienanwendenden Komponenten ab. Verwenden Sie dies für allgemeine Präfixprüfungen und bevorzugen Sie rawKeyPrefix, wenn ein exakter Abgleich des vollständigen Schlüssels erforderlich ist.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Rohschlüsselpräfix der Sitzungs-Senderegel`},help:{"v1-1g9w044-5e":`Gleicht das rohe, nicht normalisierte Sitzungsschlüsselpräfix ab, um Richtlinien exakt auf vollständige Schlüssel anzuwenden. Verwenden Sie dies, wenn das normalisierte keyPrefix zu weit gefasst ist und Sie Präzision mit Agentenpräfix oder für einen bestimmten Transport benötigen.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Freigabemodi für Sitzungen`},help:{"v1-xbh52d-5a":`Steuert, welche Zusammenarbeitsmodi Sitzungseigentümer und Administratoren auswählen dürfen. Nicht angegebene boolesche Werte gelten standardmäßig als aktiviert. Setzen Sie einen Modus auf false, um ihn aus der Auswahl zu entfernen und neue Auswahlen abzulehnen.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Entwurfssitzungen zulassen`},help:{"v1-1lzap27-2p":`Erlaubt die Sichtbarkeit als Entwurf. Dabei werden Sitzungen vor Bedienern verborgen, die weder Eigentümer noch Administratoren sind. Standard: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Schreibgeschützte Sitzungen zulassen`},help:{"v1-upl3nu-21":`Erlaubt es, Sitzungen für Nichtteilnehmer schreibgeschützt zu machen. Standard: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Sitzungen im Vorschlagsmodus zulassen`},help:{"v1-4i8owu-4g":`Erlaubt die Sichtbarkeit im Vorschlagsmodus. In dieser Phase wird dieselbe Zugangsrichtlinie wie beim schreibgeschützten Modus durchgesetzt. Vorschlagswarteschlangen werden durch eine spätere Funktion konfiguriert. Standard: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Pfad zum Sitzungsspeicher`},help:{"v1-hreznz-56":`Legt den Dateipfad für den Sitzungsspeicher fest, der Sitzungsdatensätze über Neustarts hinweg erhält. Verwenden Sie einen expliziten Pfad nur, wenn Sie eine benutzerdefinierte Datenträgerstruktur, eine gesonderte Sicherungsablage oder die Speicherung auf einem eingebundenen Volume benötigen.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Thread-Zuordnungen für Sitzungen`},help:{"v1-zbzihu-4s":`Gemeinsame Standardeinstellungen für das Erstellen und Routing threadgebundener Sitzungen über unterstützte Kanäle hinweg. Konfigurieren Sie hier globale Standardeinstellungen und überschreiben Sie diese pro Kanal nur bei abweichendem Verhalten.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Kontext für die Thread-Erstellung`},help:{"v1-1set6nw-4c":`Standardmäßiger nativer Subagent-Kontext für threadgebundene Erstellungen. Verwenden Sie "fork", um mit dem Gesprächsverlauf des Anfragenden zu beginnen, oder "isolated" für eine neue untergeordnete Sitzung ohne bisherigen Kontext. Standard: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Thread-Bindung aktiviert`},help:{"v1-foomtc-3f":`Globaler Hauptschalter für das Erstellen, Routing und die Zustellung threadgebundener Sitzungen. Deaktivieren Sie ihn, um die Thread-Bindung global auszuschalten.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Inaktivitätszeitlimit der Thread-Bindung (Stunden)`},help:{"v1-gffnx3-3h":`Standardmäßiges Inaktivitätszeitfenster in Stunden für threadgebundene Sitzungen über Anbieter und Kanäle hinweg (0 deaktiviert den Ablauf bei Inaktivität). Standard: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Maximale Laufzeit der Thread-Bindung (Stunden)`},help:{"v1-1xfcyhw-39":`Optionale feste maximale Laufzeit in Stunden für threadgebundene Sitzungen über Anbieter und Kanäle hinweg (0 deaktiviert die feste Obergrenze). Standard: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Erstellung threadgebundener Sitzungen`},help:{"v1-1lqwbdl-46":`Globale Standardfreigabe für das Erstellen threadgebundener Arbeitssitzungen über sessions_spawn und ACP-Thread-Erstellungen. Standard: true, wenn Thread-Bindungen aktiviert sind.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Zulässige Ziele für symbolische Skill-Verknüpfungen`},help:{"v1-xzybiq-4t":`Vertrauenswürdige reale Zielverzeichnisse, auf die symbolische Links für Skills verweisen dürfen, wenn die Ziele außerhalb ihres konfigurierten Quellverzeichnisses liegen. Halten Sie diesen Bereich eng begrenzt, etwa auf ein Skills-Verzeichnis in einem benachbarten Repository.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Zusätzliche Skill-Verzeichnisse`},help:{"v1-11o7opu-53":`Zusätzliche gemeinsame Stammverzeichnisse für Skills, die mit der niedrigsten Priorität durchsucht werden. Verwenden Sie diese für benachbarte Repositorys oder gemeinsame Skill-Pakete, die verfügbar sein sollen, ohne sie in den OpenClaw-Arbeitsbereich zu kopieren.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Skills überwachen`},help:{"v1-1ckr2l5-5d":`Aktiviert die Dateisystemüberwachung für Änderungen an Skill-Definitionen, damit Aktualisierungen ohne vollständigen Neustart des Prozesses übernommen werden können. Lassen Sie diese Option in Entwicklungsabläufen aktiviert und deaktivieren Sie sie in unveränderlichen Produktions-Images.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Autonomer Modus des Skill Workshop`},help:{"v1-1s3kgit-6j":`Steuert das Lernen im Hintergrund: "off" behält nur den Vorschlagshinweis bei, "propose" erstellt ausstehende Vorschläge und "auto" wendet erfasste Vorschläge an und führt eine wöchentliche Überprüfung der vom Workshop verwalteten Skills durch gewöhnliche Dateibearbeitungen durch. Standard: "auto".`}},surfaces:{label:{"v1-exl2ye-g":`Richtlinien für Zustelloberflächen`},help:{"v1-vgtjbs-50":`Oberflächenspezifische Überschreibungen der Nachrichtenrichtlinien, zugeordnet anhand der aufgelösten ID der Zustelloberfläche. Verwenden Sie diese nur, wenn eine bereitgestellte Oberfläche eine strengere Behandlung stiller Antworten als die Standardeinstellung des Agenten benötigt.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Richtlinie für stille Antworten der Zustelloberfläche`},help:{"v1-12zgc3n-60":`Überschreibt die Richtlinie für stille Antworten für eine aufgelöste Zustelloberfläche. Nicht gesetzte Felder übernehmen agents.defaults.silentReply; verwenden Sie eng gefasste Oberflächen-IDs, damit internes oder gruppenspezifisches Verhalten nicht auf andere Ziele übergreift.`}},talk:{label:{"v1-15ukbjj-4":`Gespräch`},help:{"v1-1gx10xa-5g":`Einstellungen zur Sprachsynthese im Talk-Modus für Stimmidentität, Modellauswahl, Ausgabeformat und Unterbrechungsverhalten. Hier können Sie das Spracherlebnis für Nutzer optimieren und dabei Latenz und Kosten im Blick behalten.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Talk-Agent`},help:{"v1-iee5l9-2b":`Agent, dem Talk-Sitzungen zugeordnet werden, die ohne expliziten agentenspezifischen Sitzungsschlüssel erstellt wurden.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Schnellmodus für Talk-Konsultationen`},help:{"v1-syf3xk-2o":`Setzen Sie hier den Schnellmodus für den regulären Agentenlauf hinter Talk-Echtzeitkonsultationen auf true oder false.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Denkniveau für Talk-Konsultationen`},help:{"v1-1ft5njw-2o":`Überschreiben Sie hier das Denkniveau für den regulären Agentenlauf hinter Talk-Echtzeitkonsultationen.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Talk bei Spracheingabe unterbrechen`},help:{"v1-8n9q4o-3l":`Bei true (Standard) wird die Sprachausgabe des Assistenten gestoppt, sobald der Nutzer im Talk-Modus zu sprechen beginnt. Lassen Sie diese Option für einen natürlichen Sprecherwechsel aktiviert.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Aktiver Talk-Anbieter`},help:{"v1-wgnxhg-1g":`ID des aktiven Talk-Anbieters (zum Beispiel "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Talk-Anbietereinstellungen`},help:{"v1-oh0yuv-30":`Anbieterspezifische Talk-Einstellungen mit der Anbieter-ID als Schlüssel. Verwenden Sie bei der Migration vorzugsweise diese Einstellungen statt der veralteten talk.*-Schlüssel.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Talk-Anbieterkonfiguration`},help:{"v1-36pblg-1r":`Vom Anbieter definierte Talk-Konfigurationsfelder für die jeweilige Anbieter-ID.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`API-Schlüssel des Talk-Anbieters`},help:{"v1-1a1p9wp-v":`API-Schlüssel des Anbieters für den Talk-Modus.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk in Echtzeit`},help:{"v1-c2re7j-3z":`Anbieter, Modell, Stimme, Modus, Transport und Denkstrategie für Talk in Echtzeit. Belassen Sie die Sprach-/TTS-Anbieterkonfiguration in talk.provider und talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Denkstrategie für Talk in Echtzeit`},help:{"v1-opsatw-37":`Denkstrategie für Talk: agent-consult für durch das Gateway vermittelte Agentenhilfe, direct-tools für lokale Tool-Aufrufe oder none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Weiterleitung von Konsultationen für Talk in Echtzeit`},help:{"v1-10qjcvk-5f":`Ersatzweise Weiterleitung über das Gateway für endgültige Benutzertranskripte, wenn der Echtzeitanbieter openclaw_agent_consult überspringt. provider-direct behält die Antworten des Anbieters bei; force-agent-consult leitet über OpenClaw weiter.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Anweisungen für Talk in Echtzeit`},help:{"v1-1jaaj84-5p":`Zusätzliche Systemanweisungen, die an den integrierten Echtzeit-Talk-Prompt von OpenClaw angehängt werden. Verwenden Sie diese für Sprechstil, Tonfall und anderes anbieterseitiges Echtzeitverhalten, ohne die Vorgaben für agent-consult zu verändern.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Modus für Talk in Echtzeit`},help:{"v1-1u2xui1-1l":`Ausführungsmodus für Talk: realtime, stt-tts oder transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Modell für Talk in Echtzeit`},help:{"v1-amou5a-27":`Abweichende Modell-ID des Echtzeitanbieters für Talk-Sitzungen im Browser oder unter Verwaltung des Gateways.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Audiovorlauf für Talk in Echtzeit (ms)`},help:{"v1-1cwg07n-22":`Millisekunden an Audio, die vor der Erkennung von Sprachaktivität in Echtzeit beibehalten werden.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Anbieter für Talk in Echtzeit`},help:{"v1-wwsmpt-1o":`ID des aktiven Echtzeit-Sprachanbieters, etwa openai oder google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Talk: Einstellungen für Echtzeitanbieter`},help:{"v1-ruagcu-1r":`Anbieterspezifische Echtzeit-Spracheinstellungen, nach Anbieter-ID zugeordnet.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Talk: Konfiguration des Echtzeitanbieters`},help:{"v1-edfpxm-1u":`Anbieterspezifische Echtzeit-Sprachkonfiguration für die zugehörige Anbieter-ID.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Talk: API-Schlüssel des Echtzeitanbieters`},help:{"v1-1fbmgpx-z":`API-Schlüssel des Anbieters für Talk in Echtzeit.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Talk: Denkaufwand in Echtzeit`},help:{"v1-157xd3e-2t":`Anbieterspezifischer Denkaufwand für Talk-Sitzungen in Echtzeit, etwa minimal, low, medium oder high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Talk: Stilledauer in Echtzeit (ms)`},help:{"v1-1grnu06-1y":`Dauer der Stille in Millisekunden, bevor ein Nutzerbeitrag in Talk in Echtzeit als abgeschlossen übernommen wird.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Talk: Sprecherstimme in Echtzeit`},help:{"v1-1kgb166-2h":`Überschreibt den Namen der Sprecherstimme des Echtzeitanbieters für Talk-Sitzungen im Browser oder unter Verwaltung des Gateway.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Talk: Sprecherstimmen-ID in Echtzeit`},help:{"v1-1k8w6vk-2f":`Überschreibt die ID der Sprecherstimme des Echtzeitanbieters für Talk-Sitzungen im Browser oder unter Verwaltung des Gateway.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Talk: Echtzeittransport`},help:{"v1-2otjgn-2g":`Byte-/Sitzungstransport für Talk: webrtc, provider-websocket, gateway-relay oder managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`VAD-Schwellenwert für Talk in Echtzeit`},help:{"v1-nf5l2t-2j":`Schwellenwert für die Echtzeit-Sprachaktivitätserkennung von 0 (am empfindlichsten) bis 1 (am wenigsten empfindlich).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Zeitlimit bei Stille für Talk (ms)`},help:{"v1-1kim32f-59":`Dauer der Sprechpause des Benutzers in Millisekunden, bevor der Talk-Modus das aktuelle Transkript abschließt und sendet. Nicht festlegen, um das standardmäßige Pausenfenster der Plattform beizubehalten (700 ms unter macOS und Android, 900 ms unter iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Gebietsschema für Talk-Spracherkennung`},help:{"v1-1un3x4l-4c":`BCP-47-Gebietsschema-ID für die Talk-Spracherkennung auf Geräteknoten und die iOS-Systemstimme als Ausweichlösung, zum Beispiel "ru-RU". Nicht festlegen, um die Standardeinstellung des jeweiligen Geräts zu verwenden.`}},telemetry:{label:{"v1-sqprmo-9":`Telemetrie`},help:{"v1-1o5tru3-55":`Ausdrückliche Einwilligung in anonyme Funktionsstatistiken, die bei der täglichen Update-Prüfung mitgesendet werden. Funktionsstatistiken sind standardmäßig deaktiviert und enthalten niemals Nachrichten, Zugangsdaten oder Kennungen.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Zeitstempel der Einwilligung in Funktionsstatistiken`},help:{"v1-1t051az-3t":`ISO-Zeitstempel, der festhält, wann der Betreiber anonyme Funktionsstatistiken akzeptiert oder abgelehnt hat. Verhindert, dass der Einrichtungsassistent erneut danach fragt.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Anonyme Funktionsstatistiken`},help:{"v1-1ptrwuq-4r":`Übermittelt bei der täglichen Update-Prüfung die Namen aktivierter Kanäle und Anbieter, die Anzahl der Plugins sowie die Anzahl der letzten Sitzungen. Standardmäßig deaktiviert und bei DO_NOT_TRACK=1 immer deaktiviert.`}},tools:{label:{"v1-15cdqf0-5":`Werkzeuge`},help:{"v1-1el54kl-5h":`Tool-Infrastruktur und agentenübergreifende Standardwerte. Gleichrangige Einträge auf der Stammebene steuern die Infrastruktur und agentenübergreifenden Standardwerte; agents.defaults steuert das Verhalten der Agentenschleife; Agenteneinträge können beides überschreiben, sofern dies unterstützt wird.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Agentenübergreifender Tool-Zugriff`},help:{"v1-1ynpa5f-cf":`Richtlinie für agentenübergreifende Sitzungstool-Aufrufe: Senden, Auflisten, Verlauf, Suche und Statusabfragen (Standard: aktiviert). Verwenden Sie allow, um Agentenpaare einzuschränken; enabled=false blockiert den regulären agentenübergreifenden Zugriff. Native Subagenten-Sitzungen und untergeordnete ACP-Sitzungen, die dem anfragenden Agenten gehören, bleiben bei der Sichtbarkeit tree oder all erreichbar. Für eine strikte Trennung setzen Sie tools.sessions.visibility auf agent oder self (tree lässt weiterhin native/ACP-Untersitzungen des anfragenden Agenten zu), oder verwenden Sie separate Gateways.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Zulassungsliste für agentenübergreifende Ziele`},help:{"v1-1jt2ari-76":`Agenten-IDs oder *-Muster, die an agentenübergreifenden Aufrufen beteiligt sein dürfen; sowohl der anfragende als auch der Zielagent müssen übereinstimmen. Agentenübergreifender Zugriff ist standardmäßig aktiviert. Ein fehlender oder leerer allow-Eintrag erlaubt jedes Paar. Legen Sie eine explizite Liste fest, um den Zugriff einzuschränken; leere Listeneinträge verweigern den Zugriff.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Agentenübergreifendes Tool aktivieren`},help:{"v1-w950oq-ba":`Aktiviert den agentenübergreifenden Zugriff auf Sitzungstools (Standard: true); ein fehlender oder leerer allow-Eintrag erlaubt jedes Agentenpaar. Setzen Sie den Wert auf false, um den regulären agentenübergreifenden Zugriff zu blockieren; native Subagenten-Sitzungen und untergeordnete ACP-Sitzungen, die dem anfragenden Agenten gehören, bleiben bei der Sichtbarkeit tree oder all erreichbar. Für eine strikte Trennung setzen Sie tools.sessions.visibility auf agent oder self (tree lässt weiterhin native/ACP-Untersitzungen des anfragenden Agenten zu), oder verwenden Sie separate Gateways.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Tool-Zulassungsliste`},help:{"v1-1is3eaq-4v":`Absolute Tool-Zulassungsliste, die in streng kontrollierten Umgebungen die profilbasierten Standardwerte ersetzt. Verwenden Sie diese nur, wenn Sie bewusst eine eng begrenzte Auswahl an Tool-Funktionen nutzen.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Ergänzungen zur Tool-Zulassungsliste`},help:{"v1-1xw9zp8-57":`Zusätzliche Einträge der Tool-Zulassungsliste, die das ausgewählte Tool-Profil und die Standardrichtlinie ergänzen. Halten Sie diese Liste kurz und eindeutig, damit bei Audits beabsichtigte Richtlinienausnahmen schnell erkannt werden können.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Tool-Richtlinie nach Anbieter`},help:{"v1-1ecljob-4y":`Anbieterspezifische Überschreibungen für das Zulassen oder Sperren von Tools, zugeordnet anhand der Kanal-/Anbieter-ID, um Funktionen je nach Schnittstelle anzupassen. Verwenden Sie diese, wenn ein Anbieter strengere Kontrollen als die globale Tool-Richtlinie benötigt.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Code-Modus`},help:{"v1-1ecc39k-6k":'Allgemeiner OpenClaw Code Mode. Wenn global nicht angegeben, gilt standardmäßig `"auto"`; ein explizit angelegtes Objekt ohne `enabled` bleibt deaktiviert. Bei aktivem Code Mode stellen Agentenläufe dem Modell nur `exec` und `wait` bereit und greifen über die Katalogbrücke auf reguläre Tools zu.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Codemodus aktivieren`},help:{"v1-rgstxz-aj":'Globale Aktivierung von OpenClaw Code Mode. Fehlt die globale Einstellung vollständig, gilt standardmäßig `"auto"`; ein explizit angelegtes Objekt ohne `enabled` bleibt deaktiviert. `"auto"` aktiviert den Modus für Modelle, die den Katalog bevorzugen, während `true` ihn für Läufe mit Tool-Unterstützung aktiviert. Abweichende Aktivierungseinstellungen für Agenten und Modelle haben Vorrang. Ein Lauf mit aktivem Code Mode wird bei nicht verfügbarer Laufzeit sicherheitshalber abgebrochen, statt die vollständige Tool-Liste bereitzustellen.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Code Mode-Ausführungsmodul`},help:{"v1-l8nlk2-6x":`JavaScript-Ausführungsmodul: "node" (Standard) verwendet Node vm für vertrauenswürdigen Code und ist keine Sicherheits-Sandbox; "quickjs" verwendet das mitgelieferte QuickJS WASM-Plugin für eine gehärtete Gastausführung. Tool-Berechtigungen gelten für beide. Fehlt das ausgewählte Ausführungsmodul, wird die Ausführung aus Sicherheitsgründen verweigert.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Ausgabelimit des Codemodus`},help:{"v1-1hmij9q-1n":`Maximale Anzahl serialisierter Bytes, die über die Ausgabe des Codemodus zurückgegeben werden.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Code-Modus: Limit ausstehender Tool-Aufrufe`},help:{"v1-3b5tyd-2i":`Maximale Anzahl gleichzeitiger verschachtelter Tool-Aufrufe, die eine Code-Modus-VM starten kann, bevor sie die Ausführung später fortsetzen muss.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Code-Modus: Maximale Suchergebnisse`},help:{"v1-1gpue5r-28":`Maximale Anzahl von Suchergebnissen aus dem verborgenen Katalog, die ein Code-Modus-Programm anfordern kann.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Code-Modus: Snapshot-Limit`},help:{"v1-1mmgkqy-1x":`Maximale Anzahl serialisierter Bytes, die für einen Snapshot einer angehaltenen QuickJS-VM gespeichert werden.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Code-Modus: Speicherlimit`},help:{"v1-xetora-6n":`Heap-Limit für QuickJS-Gastinstanzen oder nach bestem Bemühen eingehaltenes V8-Heap-Budget für Node-Worker in Bytes. Der Laufzeit-Overhead von Node und die Mindestallokationen der Engine beeinflussen das effektive Budget; externe Puffer und der Prozess-RSS sind ausgeschlossen. Dies ist keine Sicherheitsgarantie.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Code-Modus: Schnittstelle`},help:{"v1-dsp2b9-2x":'Dem Modell bereitgestellte Schnittstelle. Nur "only" wird unterstützt: `exec` und `wait` des Code-Modus bereitstellen und normale Tools ausblenden.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Code-Modus: Standardanzahl der Suchergebnisse`},help:{"v1-1io42lu-2m":"Standardanzahl von Suchergebnissen aus dem verborgenen Katalog, die `catalog.search` im Code-Modus zurückgibt."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`Code-Modus: Snapshot-TTL`},help:{"v1-1nxfczz-28":"Wie lange angehaltene Code Mode-Ausführungen mit `wait` fortgesetzt werden können, bevor sie ablaufen."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Zeitlimit für den Codemodus`},help:{"v1-8csycm-1p":"Maximale Dauer in Millisekunden für einen einzelnen `exec`- oder `wait`-Aufruf im Codemodus."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Tool-Sperrliste`},help:{"v1-wilr1b-4p":`Globale Tool-Sperrliste, die aufgeführte Tools blockiert, selbst wenn Profil- oder Anbieterregeln sie zulassen würden. Verwenden Sie Sperrregeln für Notfallsperren und eine langfristige, mehrschichtige Absicherung.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Tool-Zugriff mit erhöhten Rechten`},help:{"v1-ehcm0r-5a":`Zugriffskontrollen für Tools mit erhöhten Rechten an privilegierten Befehlsschnittstellen, die nur vertrauenswürdigen Absendern zugänglich sein sollten. Lassen Sie diese Funktion deaktiviert, sofern die Arbeitsabläufe der Betreiber nicht ausdrücklich Aktionen mit erhöhten Rechten erfordern.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Zulassungsregeln für Tools mit erhöhten Rechten`},help:{"v1-1u9bhih-54":`Absender-Zulassungsregeln für Tools mit erhöhten Rechten, üblicherweise nach Identitätsformaten des Kanals oder Anbieters zugeordnet. Verwenden Sie eng eingegrenzte, explizite Identitäten, damit Befehle mit erhöhten Rechten nicht von unbeabsichtigten Benutzern ausgelöst werden können.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Tool-Zugriff mit erhöhten Rechten aktivieren`},help:{"v1-1n8oyal-4l":`Aktiviert die Tool-Ausführung mit erhöhten Rechten, wenn Absender- und Richtlinienprüfungen erfolgreich sind. Lassen Sie diese Funktion in öffentlichen oder gemeinsam genutzten Kanälen deaktiviert und aktivieren Sie sie nur in vertrauenswürdigen, vom Eigentümer betriebenen Umgebungen.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Exec-Tool`},help:{"v1-p5piic-56":`Richtliniengruppe des Exec-Tools für den Host der Shell-Ausführung, den Sicherheitsmodus, das Genehmigungsverhalten und Laufzeitbindungen. Behalten Sie im Produktivbetrieb konservative Standardeinstellungen bei und schränken Sie Ausführungspfade mit erhöhten Rechten stärker ein.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Modell-Zulassungsliste für apply_patch`},help:{"v1-4q5ovf-1x":`Optionale Zulassungsliste für Modell-IDs (z. B. "gpt-5.4" oder "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`apply_patch aktivieren`},help:{"v1-1erkir4-31":`apply_patch für OpenAI- und OpenAI Codex-Modelle aktivieren oder deaktivieren, sofern die Tool-Richtlinie dies erlaubt (Standard: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch nur im Arbeitsbereich`},help:{"v1-x2z207-3o":`Pfade für apply_patch auf das Arbeitsbereichsverzeichnis beschränken (Standard: true). Auf false setzen, um das Schreiben außerhalb des Arbeitsbereichs zu erlauben (gefährlich).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Hinweis zur laufenden Ausführung nach Exec-Genehmigung (ms)`},help:{"v1-1gwwann-4z":`Verzögerung in Millisekunden, bevor nach einer erteilten Exec-Genehmigung ein Hinweis zur laufenden Ausführung angezeigt wird. Erhöhen, um Flackern bei schnellen Befehlen zu reduzieren, oder verringern, um Bedienpersonen schneller Rückmeldung zu geben.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Exec-Rückfrage`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Exec-Befehlshervorhebung`},help:{"v1-kyxd4o-4n":`Vom Parser ermittelte Befehlshervorhebungen in Exec-Genehmigungsabfragen anzeigen (Standard: false). Aktivieren, um hervorgehobenen Befehlstext darzustellen, ohne die Exec-Genehmigungsrichtlinie zu ändern.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Gültigkeitsdauer dauerhafter Berechtigungen (Tage)`},help:{"v1-5uxe2j-6r":`Standardgültigkeitsdauer in Tagen (1–3650) für dauerhafte Berechtigungen, die durch allow-always bei Automatisierungsgenehmigungen erstellt werden. Ohne Festlegung bleiben Berechtigungen gültig, bis sie widerrufen werden oder sich die zugehörige Automatisierung ändert. Die Bedingungen werden bei der Erstellung festgeschrieben; Änderungen hier wirken sich daher nur auf zukünftige Berechtigungen aus.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Exec-Ziel`},help:{"v1-rno1mf-5q":`Wählt die Strategie für das Ausführungsziel von Shell-Befehlen. Verwenden Sie "auto" für laufzeitabhängiges Verhalten (sandbox, falls verfügbar, andernfalls gateway), oder legen Sie sandbox/gateway/node explizit fest, wenn Sie eine feste Ausführungsumgebung benötigen.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Ausführungsmodus`},help:{"v1-1wi6t4l-5q":`Auswahl der normalisierten Ausführungsrichtlinie. Verwenden Sie "auto", um Fälle ohne passende Freigabe durch einen Klassifikator prüfen zu lassen, "ask" für die Prüfung durch einen Menschen, "allowlist" ausschließlich für deterministisch sichere Befehle oder "full" für den vertrauenswürdigen lokalen Betrieb.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Knotenbindung für die Ausführung`},help:{"v1-rfnz54-4s":`Konfiguration der Knotenbindung für Ausführungswerkzeuge, wenn die Befehlsausführung an verbundene Knoten delegiert wird. Verwenden Sie eine explizite Knotenbindung nur, wenn Routing über mehrere Knoten erforderlich ist.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Bei Ausführungsende benachrichtigen`},help:{"v1-1ounlvx-3q":`Bei true (Standard) reihen im Hintergrund laufende Ausführungssitzungen beim Beenden sowie Lebenszyklusereignisse der Knotenausführung ein Systemereignis in die Warteschlange ein und fordern einen Heartbeat an.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Bei erfolgreicher Ausführung ohne Ausgabe benachrichtigen`},help:{"v1-1wx4xxd-3d":`Bei true wird auch beim erfolgreichen Beenden von Hintergrundausführungen ohne Ausgabe ein Abschluss-Systemereignis in die Warteschlange eingereiht (Standard: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`PATH für die Ausführung voranstellen`},help:{"v1-s1aimc-1r":`Verzeichnisse, die PATH bei Ausführungen (gateway/sandbox) vorangestellt werden.`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Ausführungsprüfer`},help:{"v1-12y548k-4x":`Modellgestützte exec-Prüfinstanz, die im automatischen Modus verwendet wird, bevor auf eine menschliche Genehmigung zurückgegriffen wird. Konfigurieren Sie hier eine gezielte Modellüberschreibung, wenn die exec-Prüfung getrennt vom Hauptmodell des Agenten erfolgen soll.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Schnellmodus für die Exec-Prüfung`},help:{"v1-175bx14-8u":`Optionaler Schnellmodus für Genehmigungsprüfungen in OpenClaw: true fordert eine priorisierte Verarbeitung auf unterstützten OpenAI Responses- und ChatGPT/OAuth-Routen an; false fordert eine Standardverarbeitung an. Nicht angeben, um die Standardeinstellungen des Anbieters beizubehalten. Der Schnellmodus kann höhere Kosten verursachen und hängt von der Verfügbarkeit beim Anbieter ab. Konfiguriert nicht den nativen Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Modell für die exec-Prüfung`},help:{"v1-1lltiy5-3i":`Optionale Anbieter-/Modellüberschreibung für den exec-Prüfagenten. Weglassen, um das konfigurierte primäre Modell des Zielagenten wiederzuverwenden.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Denkaufwand für die Exec-Prüfung`},help:{"v1-yg2gby-6u":`Optionaler Denkaufwand für modellgestützte Genehmigungsprüfungen in OpenClaw: minimal, low, medium, high, xhigh oder max. Nicht angeben, um die Standardeinstellungen des Anbieters beizubehalten. Unterstützte Stufen werden für das ausgewählte Modell normalisiert. Konfiguriert nicht den nativen Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Zeitlimit für die exec-Prüfung (ms)`},help:{"v1-1o30chi-3w":`Zeitlimit der exec-Prüfung pro Phase in Millisekunden für die Modellvorbereitung und Antwortgenerierung, bevor auf eine menschliche Genehmigung zurückgegriffen wird (Standard: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Profile sicherer Programme für exec`},help:{"v1-4cdcwe-29":`Optionale Sicherheitsprofile pro ausführbarem Programm (Beschränkungen für Positionsargumente + erlaubte/gesperrte Flags).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Sichere Programme für exec`},help:{"v1-1of1m2s-21":`Sicheren ausführbaren Programmen, die ausschließlich stdin verwenden, die Ausführung ohne explizite Einträge in der Zulassungsliste erlauben.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Vertrauenswürdige Verzeichnisse für sichere exec-Programme`},help:{"v1-zljbcn-2v":`Zusätzliche explizite Verzeichnisse, denen bei Pfadprüfungen für sichere Programme vertraut wird (PATH-Einträge gelten niemals automatisch als vertrauenswürdig).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`exec-Sicherheit`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Genehmigung für Inline-Auswertung verlangen`},help:{"v1-jkmgo7-5z":"Explizite Genehmigung für Interpreteraufrufe mit Inline-Auswertung wie `python -c`, `node -e`, `ruby -e` oder `osascript -e` verlangen. Verhindert die stillschweigende Wiederverwendung der Zulassungsliste und schränkt für diese Aufrufformen „immer erlauben“ auf „jedes Mal nachfragen“ ein."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Zeitlimit für die Ausführung (Sekunden)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Dateisystem-Tools auf den Arbeitsbereich beschränken`},help:{"v1-1mhuvka-2s":`Dateisystem-Tools (read/write/edit/apply_patch) auf das Arbeitsbereichsverzeichnis beschränken (Standard: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`GitHub CLI-Identität und Git-Autor`},help:{"v1-1fl77im-5s":`Verwaltetes lokales GitHub CLI-Profil und optionaler Git-Autor für Agenten-Tools. Lassen Sie dieses Objekt weg, um das native Konto und den Autor des Benutzers beizubehalten, unter dem der Gateway ausgeführt wird; Zugangsdaten für Repository-Remotes werden niemals überschrieben.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`E-Mail-Adresse des Git-Autors`},help:{"v1-kol5g6-1i":`Optionale, prozesslokale E-Mail-Adresse für Git-Autor und Committer.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Name des Git-Autors`},help:{"v1-z5bl1f-1h":`Optionaler, prozesslokaler Name für Git-Autor und Committer.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Art der GitHub-Zugangsdaten`},help:{"v1-qi3qun-3q":`Kennzeichnet ein verwaltetes OAuth-Profil, dessen rotierende Aktualisierungszugangsdaten dem Gateway gehören. Profile ohne diese Angabe verwenden ein persönliches Zugriffstoken.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`GitHub-Profilversion`},help:{"v1-4lzl0-27":`Generierte Profilversion ohne interpretierbare Bedeutung, die zum atomaren Wechsel verwalteter Zugangsdaten verwendet wird.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Link-Verständnis aktivieren`},help:{"v1-23t2io-59":`Automatische Vorverarbeitung für das Link-Verständnis aktivieren, damit URL-Inhalte vor den Schlussfolgerungen des Agenten zusammengefasst werden können. Für einen umfassenderen Kontext aktiviert lassen; deaktivieren, wenn die Verarbeitung strikt auf ein Minimum beschränkt werden muss.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Maximale Linkanzahl für die Linkanalyse`},help:{"v1-ksxmcv-52":`Maximale Anzahl der Links, deren Inhalte pro Gesprächsrunde bei der Linkanalyse abgerufen werden. Verwenden Sie niedrigere Werte, um Latenz und Kosten in aktiven Unterhaltungen zu begrenzen, und höhere Werte, wenn der Kontext mehrerer Links entscheidend ist.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Modelle für die Linkanalyse`},help:{"v1-6j3mnw-5a":`Liste bevorzugter Modelle für die Linkanalyse, die bei entsprechender Unterstützung der Reihe nach als Ausweichoptionen geprüft werden. Verwenden Sie für routinemäßige Zusammenfassungen zuerst ressourcenschonende Modelle und aufwendigere Modelle nur bei Bedarf.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Geltungsbereich der Linkanalyse`},help:{"v1-183cwpa-55":`Steuert, wann die Linkanalyse abhängig vom Gesprächskontext und Nachrichtentyp ausgeführt wird. Halten Sie den Geltungsbereich eng, um unnötige Abrufe bei Nachrichten zu vermeiden, deren Links nicht relevant sind.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Zeitlimit für die Linkanalyse (Sek.)`},help:{"v1-61v30o-4p":`Zeitlimit in Sekunden für die Analyse jedes Links, nach dessen Ablauf nicht aufgelöste Links übersprungen werden. Begrenzen Sie diesen Wert, um lange Wartezeiten zu vermeiden, wenn externe Websites langsam oder nicht erreichbar sind.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`Erkennung von Tool-Schleifen`},help:{"v1-1e3rls8-5g":`Steuert die Erkennung von Tool-Schleifen anhand des gleitenden Verlaufs und den Schutz nach der Komprimierung. Lassen Sie die Einstellung weg, um die Erkennung anhand des gleitenden Verlaufs deaktiviert und den Schutz nach der Komprimierung aktiviert zu lassen. Setzen Sie den Wert auf true, um beides zu aktivieren, oder auf false, um beides zu deaktivieren.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Anhangsrichtlinie für die Audioanalyse`},help:{"v1-1s3t9s5-3o":`Wählen Sie aus, welche passenden Audioanhänge verarbeitet werden. Verarbeiten Sie nur den ersten Anhang, sofern die Transkription mehrerer Anhänge nicht ausdrücklich gewünscht ist.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Format der Transkriptwiedergabe`},help:{"v1-glpdzh-3i":`Formatieren Sie das zurückgesendete Transkript mit einem {transcript}-Platzhalter. Lassen Sie den Platzhalter unverändert, damit das Transkript bei der Zustellung enthalten ist.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Transkript an den Chat zurücksenden`},help:{"v1-1dedp8c-3r":`Senden Sie das Audiotranskript vor der Verarbeitung durch den Agenten an den ursprünglichen Chat zurück. Aktivieren Sie dies, wenn Benutzer überprüfen müssen, was das System gehört hat.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Audioverständnis aktivieren`},help:{"v1-1v0x7te-2m":`Aktivieren Sie das Audioverständnis, damit Sprachnachrichten oder Audioclips für den Agentenkontext transkribiert werden können.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Sprache für das Audioverständnis`},help:{"v1-1ruqt97-3z":`Standardmäßiger Sprachhinweis für Anbieter von Audiotranskription. Legen Sie ihn fest, wenn die hauptsächlich gesprochene Sprache bekannt ist und die Erkennung durch den Anbieter unzuverlässig ist.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Maximale Byteanzahl für das Audioverständnis`},help:{"v1-1mcckc8-43":`Standardmäßige Größenbegrenzung für Audioeingaben bei konfigurierten und automatisch erkannten Modellen. Legen Sie diesen Wert auf die Größe der größten Aufnahme fest, die Ihre Anbieter und Ihr Netzwerk akzeptieren sollen.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Maximale Zeichenanzahl für das Audioverständnis`},help:{"v1-eo1dp-43":`Standardmäßige maximale Transkriptlänge für konfigurierte und automatisch erkannte Modelle. Verwenden Sie einen niedrigeren Wert, damit lange Sprachnachrichten den Agentenkontext nicht vergrößern.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Bevorzugtes Modell für das Audioverständnis`},help:{"v1-1n5zya1-3c":`Bevorzuge für die Audiotranskription einen mit einer Fähigkeitskennzeichnung versehenen Eintrag in tools.media.models vor den übrigen kompatiblen Ausweichoptionen.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Prompt für das Audioverständnis`},help:{"v1-1v5jtay-4b":`Standardprompt für die Audiotranskription, wenn ein Modelleintrag ihn nicht überschreibt. Halte die Anweisung unverändert, wenn nachgelagerte Arbeitsabläufe auf den Transkriptionsstil angewiesen sind.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Geltungsbereich des Audioverständnisses`},help:{"v1-1pptfg0-3w":`Beschränke das Audioverständnis nach Kanal, Chattyp oder Quellschlüssel. Halte den Geltungsbereich eng, wenn die automatische Transkription sensibel oder kostspielig ist.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Zeitlimit für das Audioverständnis (Sek.)`},help:{"v1-n8wc6c-3b":`Standardzeitlimit für Anfragen zum Audioverständnis. Erhöhe es für lange Aufnahmen oder langsamere lokale Transkriptionsmodelle.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Parallelität beim Medienverständnis`},help:{"v1-13kr9np-58":`Maximale Anzahl gleichzeitiger Medienverständnisvorgänge pro Durchgang über Bild-, Audio- und Videoaufgaben hinweg. Verringere diesen Wert in Bereitstellungen mit begrenzten Ressourcen, um eine Überlastung von CPU und Netzwerk zu vermeiden.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Anhangsrichtlinie für das Bildverständnis`},help:{"v1-11hofbw-3e":`Wähle aus, welche passenden Bildanhänge verarbeitet werden. Verarbeite nur den ersten Anhang, sofern keine Analyse mehrerer Bilder beabsichtigt ist.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Bildverständnis aktivieren`},help:{"v1-1b2zw34-50":`Aktivieren Sie die Bildanalyse, damit angehängte oder referenzierte Bilder in Textkontext umgewandelt werden können. Deaktivieren Sie sie, wenn Sie einen reinen Textbetrieb benötigen oder Kosten für die Bildverarbeitung vermeiden möchten.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Maximale Byteanzahl für die Bildanalyse`},help:{"v1-jwwpd1-3v":`Standardmäßige Größenbegrenzung für Bildeingaben bei konfigurierten und automatisch erkannten Modellen. Passen Sie diesen Wert an die Nutzlastgrenzen des Anbieters und die Bandbreite der Bereitstellungsumgebung an.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Maximale Zeichenanzahl für die Bildanalyse`},help:{"v1-ebnxhk-3q":`Standardmäßige maximale Länge der Bildbeschreibung. Verwenden Sie einen niedrigeren Wert für kompakten Kontext oder einen höheren Wert für detaillierte OCR und Szenenanalyse.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Bevorzugtes Modell für die Bildanalyse`},help:{"v1-1o2uwo6-3c":`Bevorzugen Sie für die Bildanalyse einen mit Fähigkeitskennzeichnungen versehenen Eintrag aus tools.media.models gegenüber den übrigen kompatiblen Ausweichoptionen.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Prompt für die Bildanalyse`},help:{"v1-1jdcu8b-3u":`Standard-Prompt für die Bildanalyse, wenn ein Eintrag ihn nicht überschreibt. Halten Sie diesen deterministisch, wenn nachgelagerte Anwendungen auf stabile Beschreibungen angewiesen sind.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Geltungsbereich der Bildanalyse`},help:{"v1-tievo1-3s":`Schränken Sie die Bildanalyse nach Kanal, Chattyp oder Quellschlüssel ein. Halten Sie den Geltungsbereich in stark frequentierten oder nicht vertrauenswürdigen Kanälen eng, um die Verarbeitung zu kontrollieren.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Zeitlimit für die Bildanalyse (Sek.)`},help:{"v1-1wcm84x-31":`Standardzeitlimit für Anfragen zur Bildanalyse. Erhöhen Sie es für große Bilder oder langsamere lokale Bildmodelle.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Gemeinsame Modelle für die Medienanalyse`},help:{"v1-f34u65-47":`Maßgebliche Modellliste für die Medienanalyse. Versehen Sie jeden Eintrag mit Funktions-Tags für Bild, Audio oder Video, damit jede Pipeline nur kompatible Ausweichmodelle auswählt.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Anhangsrichtlinie für die Videoanalyse`},help:{"v1-1qm1qrc-3e":`Wählen Sie aus, welche passenden Videoanhänge verarbeitet werden. Verarbeiten Sie nur den ersten Anhang, sofern nicht ausdrücklich mehrere Videos analysiert werden sollen.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Videoanalyse aktivieren`},help:{"v1-1ltx5gl-58":`Aktivieren Sie die Videoanalyse, damit Clips für nachfolgende Schlussfolgerungen und Antworten als Text zusammengefasst werden können. Deaktivieren Sie sie, wenn die Videoverarbeitung gegen Richtlinien verstößt oder für Ihre Bereitstellung zu kostspielig ist.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Maximale Byteanzahl für die Videoanalyse`},help:{"v1-2mp77v-3v":`Standardgrößenlimit für Videoeingaben bei konfigurierten und automatisch erkannten Modellen. Passen Sie diesen Wert an die Nutzdatenlimits des Anbieters und die Bandbreite Ihrer Bereitstellung an.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Maximale Zeichenanzahl für die Videoanalyse`},help:{"v1-1j0x40b-3j":`Standardmäßige maximale Länge der Videobeschreibung. Verwenden Sie einen niedrigeren Wert für kompakten Kontext oder einen höheren Wert für detaillierte Szenenzusammenfassungen.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Bevorzugtes Modell für die Videoanalyse`},help:{"v1-1cygq5k-3c":`Einen mit einer Fähigkeitskennzeichnung versehenen Eintrag aus tools.media.models für das Videoverständnis vor den übrigen kompatiblen Ausweichoptionen bevorzugen.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Prompt für das Videoverständnis`},help:{"v1-ul2jx4-3r":`Standard-Prompt für das Videoverständnis, sofern ein Eintrag ihn nicht überschreibt. Halten Sie ihn deterministisch, wenn nachgelagerte Anwendungen auf stabile Zusammenfassungen angewiesen sind.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Geltungsbereich des Videoverständnisses`},help:{"v1-7gfrx3-3s":`Das Videoverständnis nach Kanal, Chattyp oder Quellschlüssel einschränken. Halten Sie den Geltungsbereich in stark frequentierten oder nicht vertrauenswürdigen Kanälen eng, um die Verarbeitung zu steuern.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Zeitlimit für das Videoverständnis (Sek.)`},help:{"v1-e8rzsy-33":`Standard-Zeitlimit für Anfragen zum Videoverständnis. Erhöhen Sie es für längere Clips oder langsamere lokale Analysemodelle.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Liste zulässiger Nachrichtenaktionen`},help:{"v1-1iceqwa-5c":`Globale Liste zulässiger Nachrichtenaktionen für das Nachrichten-Tool. Nur verwenden, wenn die gesamte Laufzeitumgebung einen reduzierten Aktionsumfang bereitstellen und akzeptieren soll; für öffentliche oder in einer Sandbox ausgeführte Agenten sind agentenspezifische Listen vorzuziehen.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Nachrichten-Broadcast aktivieren`},help:{"v1-1ms74z7-14":`Broadcast-Aktion aktivieren (Standard: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Kontextübergreifendes Senden erlauben (anbieterübergreifend)`},help:{"v1-276qxo-2s":`Senden über verschiedene Anbieter hinweg erlauben (Standard: true). Auf false setzen, um anbieterübergreifende Nachrichten zu blockieren.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Kontextübergreifendes Senden erlauben (gleicher Anbieter)`},help:{"v1-1sg4x49-1z":`Senden an andere Kanäle innerhalb desselben Anbieters erlauben (Standard: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Markierung für kontextübergreifendes Senden`},help:{"v1-1fg6jrp-1z":`Beim kontextübergreifenden Senden eine sichtbare Herkunftsmarkierung hinzufügen (Standard: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Präfix der Markierung für kontextübergreifendes Senden`},help:{"v1-eblsru-1p":`Textpräfix für Markierungen beim kontextübergreifenden Senden (unterstützt "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Suffix der Markierung für kontextübergreifendes Senden`},help:{"v1-1nk0jub-1p":`Textsuffix für Markierungen beim kontextübergreifenden Senden (unterstützt "{channel}").`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Werkzeugprofil`},help:{"v1-h6k98q-5k":`Name des globalen Werkzeugprofils, mit dem eine vordefinierte Basis für Werkzeugrichtlinien ausgewählt wird, bevor Ausnahmen für Zulassen und Verweigern angewendet werden. Verwenden Sie dies für einheitliche Umgebungseinstellungen über alle Agenten hinweg und behalten Sie Profilnamen bei.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Werkzeugrichtlinie für die Sandbox`},help:{"v1-ea7awo-4k":`Rahmen für Werkzeugrichtlinien bei Agentenausführungen in der Sandbox, damit für Sandbox-Ausführungen eigene Berechtigungsgrenzen gelten können. Verwenden Sie dies, um in Sandbox-Kontexten strengere Sicherheitsvorgaben durchzusetzen.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Richtlinie zum Zulassen/Verweigern von Werkzeugen in der Sandbox`},help:{"v1-ub701o-4t":`Richtlinie zum Zulassen und Verweigern von Werkzeugen, die angewendet wird, wenn Agenten in Sandbox-Ausführungsumgebungen laufen. Halten Sie die Berechtigungen möglichst gering, damit Sandbox-Aufgaben nicht auf unnötige externe Aktionen ausgeweitet werden können.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Sitzungssichtbarkeit für Tools`},help:{"v1-1vtq2rh-c5":`Steuert, auf welche Sitzungen sessions_list/sessions_history/sessions_search/sessions_send/session_status zugreifen können. (Standard "all" = jede Sitzung auf dem Gateway, einschließlich der Sitzungen anderer Agenten und Benutzer; "agent" = jede Sitzung unter der aktuellen Agenten-ID; "self" = nur die aktuelle Sitzung; "tree" = aktuelle Sitzung + gestartete Subagenten-Sitzungen). Der agentenübergreifende Zugriff ist standardmäßig aktiviert und wird durch tools.agentToAgent begrenzt; wählen Sie eine engere Sichtbarkeit, um den Zugriff einzuschränken.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Tool-Richtlinie für Subagenten`},help:{"v1-1xoug01-4z":`Übergeordnete Tool-Richtlinie für gestartete Subagenten, um die Tool-Verfügbarkeit gegenüber den Standardvorgaben des übergeordneten Agenten einzuschränken oder zu erweitern. Damit bleiben die Fähigkeiten delegierter Agenten auf den Zweck der Aufgabe begrenzt.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Richtlinie zum Zulassen/Sperren von Tools für Subagenten`},help:{"v1-7vxsbf-5d":`Richtlinie zum Zulassen/Sperren von Tools, die auf die Laufzeitumgebungen gestarteter Subagenten angewendet wird. Halten Sie diesen Umfang enger als den des übergeordneten Agenten. Tools des übergeordneten Agenten wie progress_card sind immer gesperrt, auch bei Freigabe über allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Schwarm`},help:{"v1-1q96vvs-45":`Subagenten-Orchestrierung im Kollektormodus. Standardmäßig aktiviert; zum Deaktivieren auf false setzen. Tool-Berechtigungen gelten weiterhin für agents_wait und die Startoptionen für Schwärme.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Standardagent für Schwärme`},help:{"v1-p4alpg-2m":`Standard-Zielagent für Schwarmstarts ohne agentId. Die Zulassungsliste für Subagenten gilt weiterhin.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Schwarm aktivieren`},help:{"v1-1nnnrq9-2e":`Aktiviert Subagenten im Kollektormodus und agents_wait. Standardmäßig aktiviert; zum Deaktivieren auf false setzen.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Aktive untergeordnete Agenten pro Schwarmgruppe`},help:{"v1-kfx6qp-1c":`Maximale Anzahl aktiver untergeordneter Kollektor-Agenten pro Schwarmgruppe.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`Gleichzeitige untergeordnete Schwarm-Agenten`},help:{"v1-1d46jtm-1s":`Maximale Anzahl gleichzeitig ausgeführter untergeordneter Kollektor-Agenten pro Schwarmgruppe.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Untergeordnete Agenten pro Schwarmgruppe insgesamt`},help:{"v1-1gc9vl1-1e":`Maximale Anzahl über die gesamte Lebensdauer gestarteter Kollektor-Agenten pro Schwarmgruppe.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Maximale Schwarm-Wartezeit`},help:{"v1-bog18y-1g":`Maximale von agents_wait akzeptierte Zeitüberschreitung in Sekunden.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Werkzeugsuche`},help:{"v1-s0kx04-7y":`Große Werkzeugkataloge von OpenClaw, MCP und Clients kompakter bereitstellen. Wenn keine Einstellung festgelegt ist, verwenden OpenClaw-Laufzeitumgebungen automatisch die strukturierte Werkzeugsuche; ein aktivierter Code Mode hat Vorrang, und Codex verwendet seine native Suche. Auf false setzen, um die Funktion zu deaktivieren, auf true für die Code-Brücke oder die Objektform verwenden, um einen Modus auszuwählen.`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`Zeitlimit für Code der Werkzeugsuche`},help:{"v1-105r499-34":"Maximale Dauer einer Ausführung von `tool_search_code` in Millisekunden. Die Laufzeitumgebung begrenzt Werte auf den unterstützten Bereich von 1 bis 60 Sekunden."}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Werkzeugsuche aktivieren`},help:{"v1-1vm3hfr-4h":"Aktiviert die Werkzeugsuche. Wenn aktiviert, verbirgt OpenClaw bei Ausführungen in der eingebetteten Laufzeitumgebung große Werkzeugkataloge hinter `tool_search_code` oder strukturierten Werkzeugen zum Suchen, Beschreiben und Aufrufen."}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Maximale Ergebnisanzahl der Werkzeugsuche`},help:{"v1-7du4kh-32":`Maximale Anzahl von Ergebnissen der Werkzeugsuche, die ein Modell anfordern kann. Zur Laufzeit werden die Werte auf den unterstützten Bereich 1..50 begrenzt.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Schnittstelle der Werkzeugsuche`},help:{"v1-jybcbe-7x":'Wählen Sie die Schnittstelle für das Modell: "code" stellt `tool_search_code` bereit; "tools" stellt strukturierte Ausweichwerkzeuge zum Suchen, Beschreiben und Aufrufen bereit; "directory" hält ein begrenztes Werkzeugverzeichnis sichtbar, stellt eine begrenzte Auswahl wahrscheinlicher oder erforderlicher Schemata bereit und macht den Rest erst über Suchen, Beschreiben und Aufrufen zugänglich.'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Standardanzahl der Ergebnisse der Werkzeugsuche`},help:{"v1-1uchq7t-39":"Standardanzahl der zurückgegebenen Ergebnisse der Werkzeugsuche, wenn das Modell kein Limit angibt. Zur Laufzeit wird dieser Wert auf `maxSearchLimit` begrenzt."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Werkzeug für strukturierte Pläne aktivieren`},help:{"v1-1xgegme-4o":"Einheitliches Statuswerkzeug `progress_card` für dauerhaft gespeicherte Pläne und beschreibende Notizen in übergeordneten Sitzungen. Standardmäßig aktiviert; zum Deaktivieren auf false setzen. Für Unteragenten grundsätzlich nicht verfügbar."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Web-Werkzeuge`},help:{"v1-fpsy5-4y":`Gruppe von Richtlinien für Web-Werkzeuge zur Konfiguration von Such- und Abrufanbietern, Limits und Ausweichverhalten. Stimmen Sie aktivierte Einstellungen auf die Verfügbarkeit von API-Schlüsseln und die Richtlinien für ausgehende Netzwerkverbindungen ab.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`Cache-TTL für Web-Abrufe (Min.)`},help:{"v1-1hk89qp-17":`Cache-TTL in Minuten für web_fetch-Ergebnisse.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Web-Abrufwerkzeug aktivieren`},help:{"v1-yrswld-1f":`Das Werkzeug web_fetch aktivieren (einfacher HTTP-Abruf).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Anfrage-Header für Webabrufe`},help:{"v1-16bjkv5-me":"Zusätzliche Anfrage-Header, die bei direkten web_fetch-Anfragen gesendet werden, etwa Header für Gateway-Routing oder Authentifizierung. Jeder konfigurierte Wert wird als vertraulich behandelt und in offengelegten Konfigurationen und Debug-Aufzeichnungen unkenntlich gemacht. Die Werte sind einfache Zeichenfolgen, unterstützen die Ersetzung mit ${VAR} sowie die globale Escape-Syntax $${VAR} für literale Werte und werden an vom Modell ausgewählte URLs gesendet. Einträge werden beim Erstellen der Anfrage statt beim Laden der Konfiguration validiert. Ein ungültiger Name oder ein nicht sendbarer Wert wird daher verworfen und protokolliert, statt die Funktion zu deaktivieren; Accept, Accept-Language, User-Agent und Framing-Header wie Transfer-Encoding werden ebenfalls verworfen. Verwenden Sie tools.web.fetch.userAgent, um den User-Agent zu ändern. Bei ursprungsübergreifenden Weiterleitungen bleiben nur die Header erhalten, die auf der Liste sicherer Header von guarded-fetch stehen. Änderungen an den tatsächlich gesendeten Headern führen zu getrennten Bereichen im Abruf-Cache."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Maximale Zeichenanzahl für Webabrufe`},help:{"v1-12d1fw7-1d":`Maximale Anzahl der von web_fetch zurückgegebenen Zeichen (bei Überschreitung gekürzt).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Absolute Zeichenobergrenze für Webabrufe`},help:{"v1-cl2mf1-1v":`Absolute Obergrenze für maxChars bei web_fetch (gilt für Konfiguration und Tool-Aufrufe).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Maximale Weiterleitungen für Webabrufe`},help:{"v1-t6eak9-1h":`Maximale Anzahl zulässiger Weiterleitungen für web_fetch (Standard: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Maximale Downloadgröße für Webabrufe (Bytes)`},help:{"v1-q6ld9c-10":`Maximale Downloadgröße, bevor der Inhalt gekürzt wird.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Anbieter für Webabrufe`},help:{"v1-6pb3nv-v":`ID des Ausweichanbieters für den Webabruf.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Readability-Extraktion für den Webabruf`},help:{"v1-19exqzx-2c":`Readability verwenden, um den Hauptinhalt aus HTML zu extrahieren (ersatzweise wird eine einfache HTML-Bereinigung durchgeführt).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`SSRF-Richtlinie für den Webabruf`},help:{"v1-qtn7zx-3c":`Gezielte Überschreibungen der SSRF-Richtlinie für web_fetch. Eng begrenzen und nur für bekannte Proxy-Umgebungen im lokalen Netzwerk aktivieren.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Zulässige Hostnamen für den Webabruf`},help:{"v1-1j9ctya-35":`Exakte Hostnamen oder IP-Literale, die für web_fetch zugelassen sind, einschließlich ansonsten blockierter Ziele. Die Liste so kurz wie möglich halten.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`IPv6-Bereich für eindeutige lokale Adressen beim Webabruf zulassen`},help:{"v1-1eyz55i-3b":`Eindeutige lokale IPv6-Adressen (fc00::/7) für die Kompatibilität mit vertrauenswürdigen Fake-IP-Proxys wie sing-box, Clash oder Surge zulassen.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`RFC-2544-Benchmark-Bereich beim Webabruf zulassen`},help:{"v1-u5asdb-2y":`IP-Adressen aus dem RFC-2544-Benchmark-Bereich (198.18.0.0/15) für die Kompatibilität mit Fake-IP-Proxys wie Clash oder Surge zulassen.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Blockierte Hostnamen für den Webabruf`},help:{"v1-1164vvk-66":`Hostnamenmuster, die bei jeder web_fetch-Weiterleitung vor der DNS-Auflösung und den Zulassungsregeln gesperrt werden. Unterstützt exakte Hostnamen sowie "*.example.com" ausschließlich für Subdomains; fügen Sie "example.com" separat hinzu, um auch die Stammdomain zu sperren. Leer oder nicht gesetzt werden keine zusätzlichen Sperren angewendet.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Webabruf: Privates Netzwerk zulassen (gefährlich)`},help:{"v1-2s6mv7-3t":`Erlaubt web_fetch den Zugriff auf private und interne Netzwerkziele. Lassen Sie diese Option deaktiviert, es sei denn, die vom Modell ausgewählten URLs sind in dieser Bereitstellung vertrauenswürdig.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Zeitlimit für Webabruf (Sek.)`},help:{"v1-1c3yfr4-16":`Zeitlimit in Sekunden für web_fetch-Anfragen.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent für Webabruf`},help:{"v1-s7pe8j-1e":`User-Agent-Header für web_fetch-Anfragen überschreiben.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Vertrauenswürdiger Umgebungsproxy für Webabruf`},help:{"v1-1ypkqj7-54":`Leitet web_fetch über einen vertrauenswürdigen, per Umgebungsvariablen konfigurierten HTTP(S)-Proxy und überlässt dem Proxy die DNS-Auflösung. Aktivieren Sie diese Option nur, wenn der Proxy vom Betreiber kontrolliert wird und nach der DNS-Auflösung die Richtlinien für ausgehende Verbindungen durchsetzt.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`Cache-TTL für Websuche (Min.)`},help:{"v1-6trzlf-18":`Cache-TTL in Minuten für web_search-Ergebnisse.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Websuchwerkzeug aktivieren`},help:{"v1-n1cm4y-27":`Verwaltete web_search und optionale Codex-native Suche für unterstützte Modelle aktivieren.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Maximale Ergebnisanzahl der Websuche`},help:{"v1-mrw7mi-z":`Anzahl der zurückzugebenden Ergebnisse (1–10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Zulässige Domains für Codex`},help:{"v1-1cv4y44-43":`Domain-Zulassungsliste für die native Codex-Funktion web_search. Bei Durchläufen mit nativ gehosteter Suche beschränkt sie auch verwaltetes web_fetch; Durchläufe mit verwalteten Anbietern bleiben unverändert.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Kontextgröße der Codex-Suche`},help:{"v1-antack-1u":`Vorgabe für die Kontextgröße der nativen Codex-Suche: "low", "medium" oder "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Native Codex-Websuche aktivieren`},help:{"v1-ek2jzd-1k":`Native Codex-Websuche für Codex-fähige Modelle aktivieren.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Modus der Codex-Websuche`},help:{"v1-1ahyq9f-32":`Bevorzugter Modus der nativen Codex-Websuche: "cached" (Standard; uneingeschränkte Codex-Durchläufe verwenden dafür "live") oder "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Stadt des Codex-Nutzers`},help:{"v1-1y95orp-1d":`Ungefähre Stadt, die an die native Codex-Websuche übermittelt wird.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Land des Codex-Nutzers`},help:{"v1-1xkm5ms-1g":`Ungefähres Land, das an die native Codex-Websuche übermittelt wird.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Region des Codex-Nutzers`},help:{"v1-lhar02-1l":`Ungefähre Region bzw. ungefähres Bundesland, die bzw. das an die native Codex-Websuche gesendet wird.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Zeitzone des Codex-Benutzers`},help:{"v1-fgv9fh-1h":`Ungefähre Zeitzone, die an die native Codex-Websuche gesendet wird.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Websuchanbieter`},help:{"v1-10omglr-1x":`ID des Suchanbieters. Wird automatisch anhand der verfügbaren API-Schlüssel erkannt, wenn sie nicht angegeben ist.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Zeitlimit für die Websuche (Sek.)`},help:{"v1-i0egvw-17":`Zeitlimit in Sekunden für web_search-Anfragen.`}},transcripts:{label:{"v1-1iqk6o8-b":`Transkripte`},help:{"v1-1i0sc09-66":`Zentrale Einstellungen zur Transkripterfassung für Besprechungsnotizen, aufzeichnungsfähige Agenten-Tools und konfigurierte Autostart-Quellen für Live-Besprechungen. Besprechungs-Plugins erfassen standardmäßig dauerhaft gespeicherte Notizen; setzen Sie enabled auf false, um dies global zu deaktivieren.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Autostart-Quellen für Transkripte`},help:{"v1-1mzsl79-5s":`Live-Transkriptquellen, die ab dem Start des Gateway automatisch verwaltet werden. Jeder Eintrag ist durch sein Vorhandensein aktiviert; entfernen Sie einen Eintrag, um die entsprechende Quelle zu deaktivieren. Quellen erfassen kontinuierlich, sofern whenOccupied nicht aktiviert ist.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`Transkript-Konto-ID`},help:{"v1-6g2kjj-4b":`Optionale Kennung des Anbieterkontos oder Arbeitsbereichs für Transkriptquellen, die eine eindeutige Kontozuordnung benötigen. Verwenden Sie das vom Anbieter dokumentierte Format für die Konto-ID.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`Transkript-Kanal-ID`},help:{"v1-1lk9d5o-4u":`Anbieterspezifische Kanal-ID für die Quelle des Live-Transkripts, etwa einen Discord-Sprachkanal oder Slack-Huddle-Kanal. Prüfen Sie die anbieterspezifische Bedeutung der ID, bevor Sie den automatischen Start aktivieren.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`Discord-Server-ID`},help:{"v1-fyfgnk-4l":`Optionale Discord-Server-ID für Transkriptquellen aus Discord-Sprachkanälen. Konfigurieren Sie diese zusammen mit der passenden channelId, wenn der Anbieter Sprachkanäle innerhalb eines bestimmten Servers nachschlagen muss.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`Meeting-URL für das Transkript`},help:{"v1-1xtt9ci-4f":`Optionale Meeting-URL für Anbieter, die per URL statt per Kanal-ID beitreten. Verwenden Sie nur vertrauenswürdige Meeting-Links, da der automatische Start zum Beitritt und zur Aufzeichnung dieses Meetings führen kann.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`Anbieter-ID der Transkriptquelle`},help:{"v1-1uur06p-3s":`Anbieter-ID der Transkriptquelle, etwa eines Anbieters für Discord-Sprachkanäle oder eines künftigen Anbieters für Slack-Huddles. Verwenden Sie exakt die vom Anbieter-Plugin bereitgestellte ID.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`Transkriptsitzungs-ID`},help:{"v1-xyo4x5-5o":`Optionale feste Transkriptsitzungs-ID für diese automatisch startende Quelle. Wird ignoriert, wenn whenOccupied auf true gesetzt ist. Lassen Sie das Feld für generierte IDs ungesetzt, sofern Sie keinen stabilen täglichen Selektor benötigen und Kollisionen am selben Tag vermeiden können.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Transkripttitel`},help:{"v1-ycjnmp-5y":`Optionaler Titel für zukünftige Transkriptaufzeichnungen. Wenn nur Titel geändert werden, laufen aktuelle Aufzeichnungen weiter; ihr bei der Aufnahme festgelegter Titel und gespeicherte Notizen werden nicht umbenannt. Bei anderen Änderungen an der Quelle gilt weiterhin das übliche Neustartverhalten.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Transkriptaufzeichnung bei Anwesenheit`},help:{"v1-34jid4-78":`Startet jedes Mal eine neue Transkriptsitzung, wenn Personen in der Quelle anwesend sind, und beendet sie (mit Erstellung von Notizen), sobald die letzte Person die Quelle verlässt. Erfordert einen Anbieter, der Anwesenheit meldet, etwa discord-voice. Standard: false (kontinuierliche Aufzeichnung ab dem Start des Gateway).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Transkripte aktiviert`},help:{"v1-fyqqr0-6d":`Aktiviert dauerhaft gespeicherte automatische Besprechungsnotizen, das Agentenwerkzeug transcripts und konfigurierte Autostart-Quellen. Standard: true. Auf false setzen, um die dauerhafte Speicherung und das Werkzeug zu deaktivieren; im expliziten Transkriptionsmodus für Besprechungen bleibt der begrenzte Live-Ausschnitt erhalten.`}},tts:{label:{"v1-bmxkk9-e":`Sprachausgabe`},help:{"v1-1o27tk2-4n":`Richtlinie für die Sprachausgabe von Agentenantworten auf unterstützten Sprach- oder Audiooberflächen. Deaktiviert lassen, sofern die Sprachwiedergabe nicht Teil Ihres Arbeitsablaufs als Betreiber oder Nutzer ist.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`TTS-Persona`},help:{"v1-1r0opcb-29":`ID der standardmäßigen TTS-Persona. Lokale Einstellungen für TTS-Personas können diesen Wert pro Host überschreiben.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`TTS-Personas`},help:{"v1-19aybhl-2l":`Benannte TTS-Personas, die eine konsistente stimmliche Identität sowie anbieterspezifische Sprachzuordnungen definieren.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`TTS-Persona`},help:{"v1-10s52ah-2l":`Eine TTS-Persona. Verwenden Sie anbieterspezifische Zuordnungen für genaue Stimmen/Modelle und Prompt-Vorlagen.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Anbieterzuordnungen für TTS-Personas`},help:{"v1-993jop-3e":`Anbieterspezifische Zuordnungen für TTS-Personas, nach Sprachanbieter-ID indiziert. Diese werden für die aktive Persona mit tts.providers zusammengeführt und haben dabei Vorrang.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`TTS-Anbietereinstellungen`},help:{"v1-1k80nl4-4y":`Anbieterspezifische TTS-Einstellungen, nach Sprachanbieter-ID indiziert. Verwenden Sie diese anstelle der mitgelieferten anbieterspezifischen Schlüssel auf oberster Ebene, damit Sprach-Plugins vom zentralen Konfigurationsschema entkoppelt bleiben.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`TTS-Anbieterkonfiguration`},help:{"v1-dwapva-3d":`Anbieterspezifische TTS-Konfiguration für eine einzelne Sprachanbieter-ID. Beschränken Sie die Felder auf das Plugin, zu dem dieser Anbieter gehört.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`API-Schlüssel des TTS-Anbieters`},help:{"v1-1m2fj0i-2o":`API-Schlüssel des Anbieters, den dieser Sprachanbieter verwendet, wenn sein Plugin einen authentifizierten TTS-Zugriff erfordert.`}},tui:{label:{"v1-c8hus1-b":`Terminal-Benutzeroberfläche`},help:{"v1-1fg9vw2-3s":`Anzeigeeinstellungen der Terminal-Benutzeroberfläche. Verwenden Sie diesen Abschnitt für Darstellungseinstellungen, die nur das Terminal betreffen, ohne das Verhalten des Gateway oder anderer Benutzeroberflächen zu ändern.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Fußzeile der Terminal-Benutzeroberfläche`},help:{"v1-6e12l3-3k":`Anzeigeeinstellungen für die Fußzeile der Terminal-Benutzeroberfläche. Halten Sie optionale Kontextangaben kompakt, damit Informationen zu Sitzung, Modell, Ziel und Tokens lesbar bleiben.`}},ui:{label:{"v1-ye4dff-2":`Benutzeroberfläche`},help:{"v1-dt1924-42":`Darstellungseinstellungen der Benutzeroberfläche für Akzente und Anzeigepräferenzen der Bedienperson. Verwenden Sie diese zur Anpassung der Lesbarkeit, ohne das Laufzeitverhalten zu ändern.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Benutzerdefinierte Akzentfarbe`},help:{"v1-16klzws-4z":`Akzentfarbe der Control UI: #RRGGBB für eine benutzerdefinierte Farbe oder 'theme' für die Palette des ausgewählten Designs. Überschreibt ui.seamColor; löschen Sie den Wert, um die konfigurierte Nahtfarbe oder den Standardwert des Designs zu übernehmen.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Akzentfarbe`},help:{"v1-14q3r4h-4g":`Primäre Akzentfarbe für Hervorhebungen, Kennzeichnungen und visuelle Erkennungsmerkmale auf UI-Flächen. Verwenden Sie kontrastreiche Werte, die in hellen und dunklen Designs gut lesbar bleiben.`}},update:{label:{"v1-k12u1x-7":`Aktualisierungen`},help:{"v1-11c5k8v-5c":`Updatekanal und Verhalten der Prüfung beim Start, um die OpenClaw-Laufzeitversionen aktuell zu halten. Verwenden Sie in Produktionsumgebungen konservative Kanäle und experimentellere Kanäle nur in kontrollierten Umgebungen.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Automatische Updates aktiviert`},help:{"v1-49xs2h-3c":`Aktiviert automatische Updates im Hintergrund für Paketinstallationen über stable und beta; extended-stable wird nie automatisch angewendet (Standard: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Updatekanal`},help:{"v1-lqtdvf-5b":`Updatekanal für git- und npm-Installationen ("stable", "extended-stable", "beta" oder "dev"). extended-stable ist nur für Pakete verfügbar: Die Installation erfolgt ausschließlich im Vordergrund, mit optionalen rein informativen Hinweisen beim Start.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Beim Start nach Updates suchen`},help:{"v1-qy3q9g-5v":`Prüft beim Start des Gateway auf Updates, einschließlich rein informativer Hinweise zu extended-stable (Standard: true). Auf false setzen, um automatische Update-Prüfungen und -Installationen für Gateway und Headless-Knoten sowie anonyme Update-Pings zu deaktivieren.`}},voicewake:{label:{"v1-txt1wb-a":`Sprachaktivierung`}},web:{label:{"v1-1ae9z56-b":`Webkanal`}},wizard:{label:{"v1-28jonk-h":`Einrichtungseinstellungen`},help:{"v1-14jh6rm-3b":`Benutzerverwaltete Einrichtungseinstellungen. Der maschinenverwaltete Assistentenverlauf und Bestätigungsstatus werden in der gemeinsamen Statusdatenbank gespeichert.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Zugriff auf die Einrichtungserkennung`},help:{"v1-1nqxt0w-38":`Zustimmung zur Erkennung bei der geführten Einrichtung: "full" scannt ohne Rückfrage, während "guarded" vor der Prüfung lokaler Anwendungen nachfragt.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`App-Empfehlungen bei der Einrichtung`},help:{"v1-ub8uoi-30":`Legt fest, ob die geführte Einrichtung die Bezeichnungen installierter Anwendungen verwenden darf, um passende Plugins und Skills zu empfehlen.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Zeitstempel des letzten Assistentendurchlaufs`},help:{"v1-1y0fbk-1k":`Zeitstempel des letzten erfolgreich gespeicherten Assistentendurchlaufs.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Befehl des letzten Assistentendurchlaufs`},help:{"v1-x2pfkk-15":`Befehl, der den letzten Assistentendurchlauf gestartet hat.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Commit des letzten Assistentendurchlaufs`},help:{"v1-h0jkmt-1i":`Quellcode-Commit, der beim letzten Assistentendurchlauf in der Entwicklungsumgebung verwendet wurde.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Modus des letzten Assistentendurchlaufs`},help:{"v1-16508qy-1r":`Gibt an, ob der letzte Assistentendurchlauf auf die Einrichtung mit "local" oder "remote" ausgerichtet war.`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Version des letzten Assistentendurchlaufs`},help:{"v1-1tr4z9d-19":`OpenClaw-Version, die beim letzten Assistentendurchlauf verwendet wurde.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Zeitstempel der Sicherheitsbestätigung im Assistenten`},help:{"v1-86i182-2a":`Zeitstempel der Bestätigung des Sicherheitshinweises bei der Einrichtung, der zusammen mit der Zielkonfiguration gespeichert wird.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Worktree-Beschleunigung`},help:{"v1-9es3gc-4r":`Dateisystembeschleunigung für neue verwaltete Worktrees verwenden, sofern unterstützt (Standard: true). Auf false setzen, um einen normalen Git-Checkout und das Kopieren von Dateien zu verwenden. Gilt nur für neue Worktrees.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Worktree-Stammverzeichnis`},help:{"v1-1tgti9j-5d":`Globales Verzeichnis für neue verwaltete Worktrees. Verwenden Sie einen absoluten Pfad oder ~ für Ihr Home-Verzeichnis; der Standardwert ist <state-dir>/worktrees. Bestehende Worktrees behalten ihre gespeicherten Pfade, wenn dieser Wert geändert wird.`}}}}})))()}export{n,t};